/* Ví dụ & cách dùng cho từ vựng HSK 3 (chỉ thêm từ chưa có trong examples-data.js) */
window.VOCAB_EXAMPLES = window.VOCAB_EXAMPLES || {};
(function(add){ Object.keys(add).forEach(function(k){ if (!window.VOCAB_EXAMPLES[k]) window.VOCAB_EXAMPLES[k] = add[k]; }); })({"啊":{"en":"particle for confirmation, exclamation or softening","exs":[{"use":"Đứng cuối câu, làm giọng nhẹ nhàng, xác nhận hoặc cảm thán.","ex":"你也来啊！","py":"Nǐ yě lái a!","vi":"Bạn cũng đến à!","en":"You came too!"},{"use":"Đứng cuối câu hỏi để nhấn nhẹ, thân mật hơn.","ex":"你什么时候走啊？","py":"Nǐ shénme shíhou zǒu a?","vi":"Khi nào bạn đi vậy?","en":"So when are you leaving?"},{"use":"Dùng để nhắc nhở, dặn dò một cách nhẹ nhàng.","ex":"快点儿啊，要迟到了。","py":"Kuài diǎnr a, yào chídào le.","vi":"Nhanh lên nào, sắp muộn rồi.","en":"Hurry up, we're going to be late."}]},"搬":{"en":"to move; to carry","exs":[{"use":"搬 + vật: bê, khiêng đồ.","ex":"请你帮我搬一下桌子。","py":"Qǐng nǐ bāng wǒ bān yíxià zhuōzi.","vi":"Bạn giúp tôi bê cái bàn một chút nhé.","en":"Please help me move the table."},{"use":"搬家: chuyển nhà.","ex":"我们下个月要搬家。","py":"Wǒmen xià ge yuè yào bān jiā.","vi":"Tháng sau chúng tôi sẽ chuyển nhà.","en":"We are moving house next month."},{"use":"搬 + đến/到 + nơi chốn.","ex":"他把书搬到了楼上。","py":"Tā bǎ shū bān dào le lóushàng.","vi":"Anh ấy bê sách lên tầng trên.","en":"He carried the books upstairs."}]},"北方":{"en":"north; the northern part","exs":[{"use":"Chỉ hướng bắc hoặc khu vực phía bắc của một nước.","ex":"北方的冬天很冷。","py":"Běifāng de dōngtiān hěn lěng.","vi":"Mùa đông miền Bắc rất lạnh.","en":"Winters in the north are very cold."},{"use":"北方人: người miền Bắc.","ex":"他是北方人，喜欢吃面条。","py":"Tā shì běifāng rén, xǐhuan chī miàntiáo.","vi":"Anh ấy là người miền Bắc, thích ăn mì.","en":"He is from the north and likes noodles."},{"use":"Đối lập với 南方 (miền Nam).","ex":"我想去北方看雪。","py":"Wǒ xiǎng qù běifāng kàn xuě.","vi":"Tôi muốn lên miền Bắc ngắm tuyết.","en":"I want to go north to see snow."}]},"打算":{"en":"plan; to plan, to intend","exs":[{"use":"打算 + động từ: định làm gì (động từ).","ex":"周末你打算做什么？","py":"Zhōumò nǐ dǎsuàn zuò shénme?","vi":"Cuối tuần bạn định làm gì?","en":"What do you plan to do this weekend?"},{"use":"有打算: có dự định (danh từ).","ex":"毕业以后你有什么打算？","py":"Bìyè yǐhòu nǐ yǒu shénme dǎsuàn?","vi":"Sau khi tốt nghiệp bạn có dự định gì?","en":"What are your plans after graduation?"},{"use":"不打算 + động từ: không định làm gì.","ex":"我不打算去旅游了。","py":"Wǒ bù dǎsuàn qù lǚyóu le.","vi":"Tôi không định đi du lịch nữa.","en":"I'm no longer planning to travel."}]},"带":{"en":"to bring, to take along","exs":[{"use":"带 + vật: mang theo đồ vật.","ex":"出门别忘了带雨伞。","py":"Chūmén bié wàng le dài yǔsǎn.","vi":"Ra ngoài đừng quên mang ô.","en":"Don't forget to take an umbrella when you go out."},{"use":"带 + người + 去/来: dẫn ai đi cùng.","ex":"我带朋友去过长城。","py":"Wǒ dài péngyou qùguo Chángchéng.","vi":"Tôi đã dẫn bạn đi Vạn Lý Trường Thành.","en":"I took my friend to the Great Wall."},{"use":"带来 / 带走: mang đến / mang đi.","ex":"请把你的照片带来。","py":"Qǐng bǎ nǐ de zhàopiàn dàilái.","vi":"Hãy mang ảnh của bạn đến nhé.","en":"Please bring your photo."}]},"地图":{"en":"map","exs":[{"use":"Danh từ chỉ bản đồ; lượng từ thường dùng: 张.","ex":"桌子上有一张中国地图。","py":"Zhuōzi shàng yǒu yì zhāng Zhōngguó dìtú.","vi":"Trên bàn có một tấm bản đồ Trung Quốc.","en":"There is a map of China on the table."},{"use":"看地图 / 买地图: xem / mua bản đồ.","ex":"我们先看看地图再出发。","py":"Wǒmen xiān kànkan dìtú zài chūfā.","vi":"Chúng ta xem bản đồ trước rồi hãy xuất phát.","en":"Let's look at the map before we set off."},{"use":"手机地图: bản đồ trên điện thoại.","ex":"他用手机地图找到了那家饭馆。","py":"Tā yòng shǒujī dìtú zhǎodào le nà jiā fànguǎn.","vi":"Anh ấy dùng bản đồ điện thoại tìm thấy quán ăn đó.","en":"He found the restaurant using a phone map."}]},"复习":{"en":"to review","exs":[{"use":"复习 + nội dung: ôn lại bài đã học.","ex":"我每天晚上复习生词。","py":"Wǒ měitiān wǎnshang fùxí shēngcí.","vi":"Mỗi tối tôi đều ôn từ mới.","en":"I review new words every evening."},{"use":"复习 + 功课 / 考试: ôn bài, ôn thi.","ex":"明天考试，我今天要复习功课。","py":"Míngtiān kǎoshì, wǒ jīntiān yào fùxí gōngkè.","vi":"Mai thi, hôm nay tôi phải ôn bài.","en":"The exam is tomorrow, so I must review today."},{"use":"复习一下: ôn một chút (nhẹ nhàng).","ex":"上课前先复习一下。","py":"Shàngkè qián xiān fùxí yíxià.","vi":"Trước khi vào học hãy ôn lại một chút.","en":"Review a little before class."}]},"跟":{"en":"with; and; to follow","exs":[{"use":"跟 + người + động từ: làm gì cùng ai.","ex":"周末我跟朋友去看电影。","py":"Zhōumò wǒ gēn péngyou qù kàn diànyǐng.","vi":"Cuối tuần tôi đi xem phim với bạn.","en":"I'm going to the movies with a friend this weekend."},{"use":"跟 + người + 说/学/借: nói/học/mượn với ai.","ex":"我想跟你借一本书。","py":"Wǒ xiǎng gēn nǐ jiè yì běn shū.","vi":"Tôi muốn mượn bạn một quyển sách.","en":"I'd like to borrow a book from you."},{"use":"跟……一样: giống như…","ex":"他的爱好跟我一样。","py":"Tā de àihào gēn wǒ yíyàng.","vi":"Sở thích của anh ấy giống tôi.","en":"His hobby is the same as mine."}]},"面包":{"en":"bread","exs":[{"use":"Danh từ; lượng từ: 块, 片, 个.","ex":"早饭我吃了两片面包。","py":"Zǎofàn wǒ chī le liǎng piàn miànbāo.","vi":"Bữa sáng tôi ăn hai lát bánh mì.","en":"I had two slices of bread for breakfast."},{"use":"面包店: tiệm bánh mì.","ex":"前面有一家很大的面包店。","py":"Qiánmiàn yǒu yì jiā hěn dà de miànbāo diàn.","vi":"Phía trước có một tiệm bánh mì rất lớn.","en":"There's a big bakery up ahead."},{"use":"面包 + 牛奶: món ăn sáng quen thuộc.","ex":"他喜欢吃面包，喝牛奶。","py":"Tā xǐhuan chī miànbāo, hē niúnǎi.","vi":"Anh ấy thích ăn bánh mì, uống sữa.","en":"He likes bread and milk."}]},"南（方）":{"en":"south; the southern part","exs":[{"use":"南 / 南方: hướng nam, khu vực phía nam.","ex":"南方的夏天又热又湿。","py":"Nánfāng de xiàtiān yòu rè yòu shī.","vi":"Mùa hè miền Nam vừa nóng vừa ẩm.","en":"Summers in the south are hot and humid."},{"use":"南方人: người miền Nam.","ex":"她是南方人，喜欢吃米饭。","py":"Tā shì nánfāng rén, xǐhuan chī mǐfàn.","vi":"Cô ấy là người miền Nam, thích ăn cơm.","en":"She's from the south and likes rice."},{"use":"往南走: đi về hướng nam.","ex":"往南走五分钟就到了。","py":"Wǎng nán zǒu wǔ fēnzhōng jiù dào le.","vi":"Đi về phía nam năm phút là tới.","en":"Walk south for five minutes and you're there."}]},"一直":{"en":"all along; continuously; straight ahead","exs":[{"use":"一直 + động từ: kéo dài liên tục.","ex":"外面一直在下雨。","py":"Wàimiàn yìzhí zài xià yǔ.","vi":"Bên ngoài trời mưa mãi không ngừng.","en":"It has been raining outside all the time."},{"use":"一直走: đi thẳng (chỉ đường).","ex":"一直往前走，就能看到银行。","py":"Yìzhí wǎng qián zǒu, jiù néng kàndào yínháng.","vi":"Cứ đi thẳng về phía trước là thấy ngân hàng.","en":"Go straight ahead and you'll see the bank."},{"use":"一直 + 没 + động từ: vẫn chưa…","ex":"他一直没给我打电话。","py":"Tā yìzhí méi gěi wǒ dǎ diànhuà.","vi":"Anh ấy vẫn chưa gọi điện cho tôi.","en":"He still hasn't called me."}]},"游戏":{"en":"game","exs":[{"use":"Danh từ: trò chơi; cũng dùng cho game điện tử.","ex":"孩子们喜欢玩儿游戏。","py":"Háizimen xǐhuan wánr yóuxì.","vi":"Bọn trẻ thích chơi trò chơi.","en":"Children like playing games."},{"use":"玩儿游戏 / 打游戏: chơi game.","ex":"他周末在家打游戏。","py":"Tā zhōumò zài jiā dǎ yóuxì.","vi":"Cuối tuần anh ấy ở nhà chơi game.","en":"He plays video games at home on weekends."},{"use":"电脑游戏: game máy tính.","ex":"这个电脑游戏很有意思。","py":"Zhège diànnǎo yóuxì hěn yǒu yìsi.","vi":"Trò chơi máy tính này rất thú vị.","en":"This computer game is very interesting."}]},"着急":{"en":"worried; anxious; impatient","exs":[{"use":"Tính từ/động từ chỉ trạng thái sốt ruột.","ex":"别着急，慢慢说。","py":"Bié zháojí, mànman shuō.","vi":"Đừng sốt ruột, cứ từ từ nói.","en":"Don't worry, speak slowly."},{"use":"为 + việc + 着急: lo lắng vì việc gì.","ex":"他为找不到工作很着急。","py":"Tā wèi zhǎo bú dào gōngzuò hěn zháojí.","vi":"Anh ấy rất sốt ruột vì không tìm được việc.","en":"He is anxious about not finding a job."},{"use":"着急 + 做 + việc: vội làm gì.","ex":"你着急回家吗？","py":"Nǐ zháojí huí jiā ma?","vi":"Bạn vội về nhà à?","en":"Are you in a hurry to go home?"}]},"周末":{"en":"weekend","exs":[{"use":"Danh từ chỉ thời gian; thường đặt đầu câu.","ex":"周末你有什么计划？","py":"Zhōumò nǐ yǒu shénme jìhuà?","vi":"Cuối tuần bạn có kế hoạch gì?","en":"What are your plans for the weekend?"},{"use":"这个周末 / 上个周末: cuối tuần này / trước.","ex":"上个周末我去爬山了。","py":"Shàng ge zhōumò wǒ qù pá shān le.","vi":"Cuối tuần trước tôi đi leo núi.","en":"Last weekend I went hiking."},{"use":"周末 + 常常 + động từ: thói quen cuối tuần.","ex":"周末我常常睡到很晚。","py":"Zhōumò wǒ chángcháng shuì dào hěn wǎn.","vi":"Cuối tuần tôi thường ngủ đến rất muộn.","en":"I often sleep in on weekends."}]},"作业":{"en":"homework","exs":[{"use":"Danh từ; 做作业: làm bài tập.","ex":"我还没做完作业。","py":"Wǒ hái méi zuòwán zuòyè.","vi":"Tôi vẫn chưa làm xong bài tập.","en":"I haven't finished my homework yet."},{"use":"作业 + 很多 / 很难: nhiều / khó.","ex":"今天的作业太多了。","py":"Jīntiān de zuòyè tài duō le.","vi":"Bài tập hôm nay nhiều quá.","en":"There's too much homework today."},{"use":"交作业: nộp bài tập.","ex":"明天上课要交作业。","py":"Míngtiān shàngkè yào jiāo zuòyè.","vi":"Mai vào lớp phải nộp bài tập.","en":"Homework is due in class tomorrow."}]},"把":{"en":"measure word for things with a handle","exs":[{"use":"一把 + danh từ có tay cầm: một cái ô, một cái ghế.","ex":"门口放着一把雨伞。","py":"Ménkǒu fàng zhe yì bǎ yǔsǎn.","vi":"Ở cửa có đặt một chiếc ô.","en":"There is an umbrella by the door."},{"use":"一把椅子: một cái ghế.","ex":"教室里少了一把椅子。","py":"Jiàoshì lǐ shǎo le yì bǎ yǐzi.","vi":"Trong lớp thiếu một cái ghế.","en":"The classroom is short of one chair."},{"use":"一把刀 / 一把钥匙: một con dao / một chiếc chìa khóa.","ex":"我找不到那把钥匙了。","py":"Wǒ zhǎo bú dào nà bǎ yàoshi le.","vi":"Tôi không tìm thấy chiếc chìa khóa đó nữa.","en":"I can't find that key any more."}]},"办公室":{"en":"office","exs":[{"use":"Danh từ chỉ nơi làm việc.","ex":"经理在办公室里等你。","py":"Jīnglǐ zài bàngōngshì lǐ děng nǐ.","vi":"Giám đốc đang đợi bạn trong văn phòng.","en":"The manager is waiting for you in the office."},{"use":"在办公室: ở văn phòng.","ex":"他每天都在办公室工作八个小时。","py":"Tā měitiān dōu zài bàngōngshì gōngzuò bā ge xiǎoshí.","vi":"Mỗi ngày anh ấy làm việc tám tiếng ở văn phòng.","en":"He works eight hours a day in the office."},{"use":"办公室 + 的 + danh từ.","ex":"办公室的电话响了。","py":"Bàngōngshì de diànhuà xiǎng le.","vi":"Điện thoại văn phòng reo rồi.","en":"The office phone is ringing."}]},"脚":{"en":"foot","exs":[{"use":"Danh từ chỉ bộ phận cơ thể.","ex":"我的脚很疼。","py":"Wǒ de jiǎo hěn téng.","vi":"Chân tôi rất đau.","en":"My foot hurts a lot."},{"use":"脚 + 受伤 / 疼: chân bị thương / đau.","ex":"他踢球的时候伤了脚。","py":"Tā tī qiú de shíhou shāng le jiǎo.","vi":"Lúc đá bóng anh ấy bị thương ở chân.","en":"He hurt his foot while playing football."},{"use":"一双脚 / 脚步: đôi chân / bước chân.","ex":"我听到了他的脚步声。","py":"Wǒ tīngdào le tā de jiǎobù shēng.","vi":"Tôi nghe thấy tiếng bước chân của anh ấy.","en":"I heard the sound of his footsteps."}]},"经理":{"en":"manager","exs":[{"use":"Danh từ chỉ chức vụ; thường đứng sau họ: 王经理.","ex":"王经理明天去北京。","py":"Wáng jīnglǐ míngtiān qù Běijīng.","vi":"Giám đốc Vương mai đi Bắc Kinh.","en":"Manager Wang is going to Beijing tomorrow."},{"use":"找经理: tìm giám đốc.","ex":"有人在门口找经理。","py":"Yǒu rén zài ménkǒu zhǎo jīnglǐ.","vi":"Có người ở cửa tìm giám đốc.","en":"Someone at the door is looking for the manager."},{"use":"公司经理: giám đốc công ty.","ex":"他是这家公司的经理。","py":"Tā shì zhè jiā gōngsī de jīnglǐ.","vi":"Ông ấy là giám đốc của công ty này.","en":"He is the manager of this company."}]},"辆":{"en":"measure word for vehicles","exs":[{"use":"一辆 + xe: xe hơi, xe đạp, xe buýt…","ex":"门口停着一辆红色的汽车。","py":"Ménkǒu tíng zhe yí liàng hóngsè de qìchē.","vi":"Trước cửa đỗ một chiếc ô tô màu đỏ.","en":"A red car is parked at the door."},{"use":"一辆自行车: một chiếc xe đạp.","ex":"他新买了一辆自行车。","py":"Tā xīn mǎi le yí liàng zìxíngchē.","vi":"Anh ấy mới mua một chiếc xe đạp.","en":"He just bought a new bicycle."},{"use":"几辆车: mấy chiếc xe.","ex":"路上有很多辆出租车。","py":"Lùshang yǒu hěn duō liàng chūzūchē.","vi":"Trên đường có rất nhiều taxi.","en":"There are lots of taxis on the road."}]},"楼":{"en":"building; floor","exs":[{"use":"楼: tòa nhà. 几楼: tầng mấy.","ex":"这座楼有二十层。","py":"Zhè zuò lóu yǒu èrshí céng.","vi":"Tòa nhà này có hai mươi tầng.","en":"This building has twenty floors."},{"use":"数字 + 楼: tầng số mấy.","ex":"我家住在五楼。","py":"Wǒ jiā zhù zài wǔ lóu.","vi":"Nhà tôi ở tầng năm.","en":"I live on the fifth floor."},{"use":"上楼 / 下楼: lên lầu / xuống lầu.","ex":"他下楼去买早饭了。","py":"Tā xià lóu qù mǎi zǎofàn le.","vi":"Anh ấy xuống lầu mua đồ ăn sáng.","en":"He went downstairs to buy breakfast."}]},"拿":{"en":"to take; to hold","exs":[{"use":"拿 + vật: cầm, lấy vật gì.","ex":"请把那本书拿给我。","py":"Qǐng bǎ nà běn shū ná gěi wǒ.","vi":"Làm ơn đưa cho tôi quyển sách đó.","en":"Please hand me that book."},{"use":"拿 + 出来 / 回来: lấy ra / mang về.","ex":"他从包里拿出一把伞。","py":"Tā cóng bāo lǐ ná chū yì bǎ sǎn.","vi":"Anh ấy lấy từ trong túi ra một chiếc ô.","en":"He took an umbrella out of his bag."},{"use":"拿着: đang cầm trong tay.","ex":"她手里拿着一束花。","py":"Tā shǒu lǐ ná zhe yí shù huā.","vi":"Trong tay cô ấy cầm một bó hoa.","en":"She is holding a bunch of flowers."}]},"难":{"en":"difficult","exs":[{"use":"Tính từ; đối lập với 容易.","ex":"这道题太难了。","py":"Zhè dào tí tài nán le.","vi":"Câu hỏi này khó quá.","en":"This question is too hard."},{"use":"难 + động từ: khó làm gì (难学, 难找).","ex":"汉字很难写。","py":"Hànzì hěn nán xiě.","vi":"Chữ Hán rất khó viết.","en":"Chinese characters are hard to write."},{"use":"不难: không khó.","ex":"这个问题不难回答。","py":"Zhège wèntí bù nán huídá.","vi":"Câu hỏi này không khó trả lời.","en":"This question isn't hard to answer."}]},"胖":{"en":"fat","exs":[{"use":"Tính từ miêu tả người hoặc động vật.","ex":"他最近有点儿胖了。","py":"Tā zuìjìn yǒudiǎnr pàng le.","vi":"Dạo này anh ấy hơi béo lên.","en":"He's gotten a bit fat lately."},{"use":"太胖 / 不胖: quá béo / không béo.","ex":"我不想太胖，所以天天运动。","py":"Wǒ bù xiǎng tài pàng, suǒyǐ tiāntiān yùndòng.","vi":"Tôi không muốn quá béo nên ngày nào cũng tập thể dục.","en":"I don't want to get too fat, so I exercise every day."},{"use":"胖 vs 瘦: béo vs gầy.","ex":"他比以前胖多了。","py":"Tā bǐ yǐqián pàng duō le.","vi":"Anh ấy béo hơn trước nhiều.","en":"He is much fatter than before."}]},"其实":{"en":"actually; in fact","exs":[{"use":"Dùng để nói sự thật khác với điều người ta tưởng.","ex":"其实这个问题很容易。","py":"Qíshí zhège wèntí hěn róngyì.","vi":"Thật ra vấn đề này rất dễ.","en":"Actually, this question is quite easy."},{"use":"看起来……，其实……: trông có vẻ… nhưng thực ra…","ex":"他看起来很凶，其实人很好。","py":"Tā kàn qǐlai hěn xiōng, qíshí rén hěn hǎo.","vi":"Trông anh ấy dữ, nhưng thực ra là người rất tốt.","en":"He looks fierce, but he's actually very nice."},{"use":"其实 + 我 + động từ: thật ra tôi…","ex":"其实我也不知道他在哪儿。","py":"Qíshí wǒ yě bù zhīdào tā zài nǎr.","vi":"Thật ra tôi cũng không biết anh ấy ở đâu.","en":"Actually, I don't know where he is either."}]},"容易":{"en":"easy","exs":[{"use":"Tính từ; đối lập với 难.","ex":"这个字很容易写。","py":"Zhège zì hěn róngyì xiě.","vi":"Chữ này rất dễ viết.","en":"This character is very easy to write."},{"use":"容易 + động từ: dễ làm gì, dễ xảy ra.","ex":"天气冷了，容易感冒。","py":"Tiānqì lěng le, róngyì gǎnmào.","vi":"Trời lạnh rồi, dễ bị cảm.","en":"It's getting cold, so it's easy to catch a cold."},{"use":"不容易: không dễ.","ex":"在国外生活不容易。","py":"Zài guówài shēnghuó bù róngyì.","vi":"Sống ở nước ngoài không dễ dàng.","en":"Living abroad isn't easy."}]},"伞":{"en":"umbrella","exs":[{"use":"Danh từ; lượng từ: 把.","ex":"外面下雨了，带把伞吧。","py":"Wàimiàn xià yǔ le, dài bǎ sǎn ba.","vi":"Ngoài trời mưa rồi, mang theo cái ô đi.","en":"It's raining outside, take an umbrella."},{"use":"打伞: che ô, giương ô.","ex":"她打着一把红伞走过来。","py":"Tā dǎ zhe yì bǎ hóng sǎn zǒu guòlai.","vi":"Cô ấy che chiếc ô đỏ đi tới.","en":"She walked over holding a red umbrella."},{"use":"忘了伞 / 借伞: quên ô / mượn ô.","ex":"我把伞忘在公共汽车上了。","py":"Wǒ bǎ sǎn wàng zài gōnggòng qìchē shàng le.","vi":"Tôi để quên cái ô trên xe buýt rồi.","en":"I left my umbrella on the bus."}]},"瘦":{"en":"thin; slim","exs":[{"use":"Tính từ miêu tả người, động vật; cũng dùng cho quần áo chật.","ex":"他比哥哥瘦。","py":"Tā bǐ gēge shòu.","vi":"Anh ấy gầy hơn anh trai.","en":"He is thinner than his older brother."},{"use":"瘦了: đã gầy đi.","ex":"生病以后，她瘦了很多。","py":"Shēngbìng yǐhòu, tā shòu le hěn duō.","vi":"Sau khi bệnh, cô ấy gầy đi nhiều.","en":"She lost a lot of weight after getting sick."},{"use":"衣服太瘦: quần áo quá chật.","ex":"这件衣服有点儿瘦，我穿不了。","py":"Zhè jiàn yīfu yǒudiǎnr shòu, wǒ chuān bù liǎo.","vi":"Cái áo này hơi chật, tôi mặc không vừa.","en":"This piece of clothing is a bit tight; I can't wear it."}]},"树":{"en":"tree","exs":[{"use":"Danh từ; lượng từ: 棵.","ex":"院子里有一棵大树。","py":"Yuànzi lǐ yǒu yì kē dà shù.","vi":"Trong sân có một cây to.","en":"There is a big tree in the yard."},{"use":"树 + 下 / 上: dưới / trên cây.","ex":"孩子们在树下玩儿。","py":"Háizimen zài shù xià wánr.","vi":"Bọn trẻ chơi dưới gốc cây.","en":"The children are playing under the tree."},{"use":"种树: trồng cây.","ex":"春天我们一起去种树。","py":"Chūntiān wǒmen yìqǐ qù zhòng shù.","vi":"Mùa xuân chúng ta cùng đi trồng cây.","en":"We'll plant trees together in spring."}]},"疼":{"en":"painful; to hurt","exs":[{"use":"Tính từ/động từ: đau ở bộ phận nào đó.","ex":"我头疼，想休息一下。","py":"Wǒ tóu téng, xiǎng xiūxi yíxià.","vi":"Tôi đau đầu, muốn nghỉ một lát.","en":"I have a headache and want to rest."},{"use":"部位 + 疼: chỗ nào đau.","ex":"你的腿还疼吗？","py":"Nǐ de tuǐ hái téng ma?","vi":"Chân bạn còn đau không?","en":"Does your leg still hurt?"},{"use":"疼 + 得 + bổ ngữ: đau đến mức…","ex":"牙疼得睡不着觉。","py":"Yá téng de shuì bù zháo jiào.","vi":"Đau răng đến mức không ngủ được.","en":"My tooth hurts so much I can't sleep."}]},"腿":{"en":"leg","exs":[{"use":"Danh từ chỉ bộ phận cơ thể.","ex":"爬山以后我的腿很酸。","py":"Pá shān yǐhòu wǒ de tuǐ hěn suān.","vi":"Sau khi leo núi chân tôi rất mỏi.","en":"My legs ache after climbing the mountain."},{"use":"腿 + 疼 / 受伤: chân đau / bị thương.","ex":"他的腿受伤了，不能走路。","py":"Tā de tuǐ shòushāng le, bù néng zǒulù.","vi":"Chân anh ấy bị thương, không đi được.","en":"His leg is injured and he can't walk."},{"use":"长腿 / 短腿: chân dài / ngắn.","ex":"那个女孩儿的腿又细又长。","py":"Nàge nǚháir de tuǐ yòu xì yòu cháng.","vi":"Đôi chân cô gái đó vừa thon vừa dài.","en":"That girl has long, slender legs."}]},"秘书":{"en":"secretary","exs":[{"use":"Danh từ chỉ nghề nghiệp.","ex":"她是经理的秘书。","py":"Tā shì jīnglǐ de mìshū.","vi":"Cô ấy là thư ký của giám đốc.","en":"She is the manager's secretary."},{"use":"当秘书: làm thư ký.","ex":"他想毕业后当秘书。","py":"Tā xiǎng bìyè hòu dāng mìshū.","vi":"Anh ấy muốn làm thư ký sau khi tốt nghiệp.","en":"He wants to be a secretary after graduating."},{"use":"请秘书 + động từ: nhờ thư ký làm gì.","ex":"我请秘书给你发了邮件。","py":"Wǒ qǐng mìshū gěi nǐ fā le yóujiàn.","vi":"Tôi nhờ thư ký gửi thư điện tử cho bạn.","en":"I asked my secretary to email you."}]},"太太":{"en":"Mrs.; madam; wife","exs":[{"use":"Cách gọi lịch sự người phụ nữ đã kết hôn.","ex":"王太太今天没来上班。","py":"Wáng tàitai jīntiān méi lái shàngbān.","vi":"Bà Vương hôm nay không đến làm.","en":"Mrs. Wang didn't come to work today."},{"use":"我太太: vợ tôi (cách nói lịch sự).","ex":"我太太做饭做得很好。","py":"Wǒ tàitai zuò fàn zuò de hěn hǎo.","vi":"Vợ tôi nấu ăn rất giỏi.","en":"My wife cooks very well."},{"use":"先生和太太: ông và bà.","ex":"张先生和张太太都是医生。","py":"Zhāng xiānsheng hé Zhāng tàitai dōu shì yīshēng.","vi":"Ông Trương và bà Trương đều là bác sĩ.","en":"Mr. and Mrs. Zhang are both doctors."}]},"衬衫":{"en":"shirt","exs":[{"use":"Danh từ; lượng từ: 件.","ex":"他穿了一件白衬衫。","py":"Tā chuān le yí jiàn bái chènshān.","vi":"Anh ấy mặc một chiếc sơ mi trắng.","en":"He is wearing a white shirt."},{"use":"买衬衫: mua áo sơ mi.","ex":"我想给爸爸买一件衬衫。","py":"Wǒ xiǎng gěi bàba mǎi yí jiàn chènshān.","vi":"Tôi muốn mua cho bố một chiếc áo sơ mi.","en":"I want to buy my dad a shirt."},{"use":"衬衫 + 和 + 裤子: sơ mi và quần.","ex":"这件衬衫跟那条裤子很配。","py":"Zhè jiàn chènshān gēn nà tiáo kùzi hěn pèi.","vi":"Chiếc sơ mi này rất hợp với chiếc quần kia.","en":"This shirt goes well with those trousers."}]},"放":{"en":"to put; to place","exs":[{"use":"放 + vật + 在 + nơi: đặt vật ở đâu.","ex":"你把书放在桌子上吧。","py":"Nǐ bǎ shū fàng zài zhuōzi shàng ba.","vi":"Bạn để sách lên bàn nhé.","en":"Put the book on the table."},{"use":"放 + 糖/盐: cho thêm (đường, muối).","ex":"咖啡里别放太多糖。","py":"Kāfēi lǐ bié fàng tài duō táng.","vi":"Đừng cho quá nhiều đường vào cà phê.","en":"Don't put too much sugar in the coffee."},{"use":"放假: nghỉ lễ, nghỉ học.","ex":"下个月我们放假。","py":"Xià ge yuè wǒmen fàng jià.","vi":"Tháng sau chúng tôi được nghỉ.","en":"We have a holiday next month."}]},"还是":{"en":"or (in questions)","exs":[{"use":"A 还是 B? : hỏi chọn một trong hai.","ex":"你喝茶还是喝咖啡？","py":"Nǐ hē chá háishi hē kāfēi?","vi":"Bạn uống trà hay uống cà phê?","en":"Do you drink tea or coffee?"},{"use":"是……还是……: là… hay là…?","ex":"他是老师还是学生？","py":"Tā shì lǎoshī háishi xuésheng?","vi":"Anh ấy là giáo viên hay là học sinh?","en":"Is he a teacher or a student?"},{"use":"还是 + 动词: vẫn nên (đưa ra lời khuyên).","ex":"太晚了，你还是明天再走吧。","py":"Tài wǎn le, nǐ háishi míngtiān zài zǒu ba.","vi":"Muộn quá rồi, bạn vẫn nên mai hãy đi.","en":"It's too late; you'd better leave tomorrow."}]},"花":{"en":"flower; to spend; flower","exs":[{"use":"Danh từ; lượng từ: 朵, 束.","ex":"院子里的花开了。","py":"Yuànzi lǐ de huā kāi le.","vi":"Hoa trong sân đã nở.","en":"The flowers in the yard have bloomed."},{"use":"送花 / 买花: tặng hoa / mua hoa.","ex":"他给妈妈买了一束花。","py":"Tā gěi māma mǎi le yí shù huā.","vi":"Anh ấy mua cho mẹ một bó hoa.","en":"He bought his mom a bouquet of flowers."},{"use":"看花: ngắm hoa.","ex":"春天我们去公园看花。","py":"Chūntiān wǒmen qù gōngyuán kàn huā.","vi":"Mùa xuân chúng ta ra công viên ngắm hoa.","en":"We go to the park to see flowers in spring."},{"use":"花 (động từ): tiêu tiền, tốn thời gian.","ex":"这次旅行花了不少钱。","py":"Zhè cì lǚxíng huā le bù shǎo qián.","vi":"Chuyến du lịch này tốn không ít tiền.","en":"This trip cost quite a lot of money."},{"use":"花 + 时间: tốn thời gian.","ex":"写这篇文章花了我两天时间。","py":"Xiě zhè piān wénzhāng huā le wǒ liǎng tiān shíjiān.","vi":"Viết bài này tốn của tôi hai ngày.","en":"Writing this article took me two days."},{"use":"花钱: tiêu tiền.","ex":"他不爱花钱买衣服。","py":"Tā bú ài huā qián mǎi yīfu.","vi":"Anh ấy không thích tiêu tiền mua quần áo.","en":"He doesn't like spending money on clothes."}]},"或者":{"en":"or (in statements)","exs":[{"use":"A 或者 B: dùng trong câu trần thuật.","ex":"明天或者后天我去找你。","py":"Míngtiān huòzhě hòutiān wǒ qù zhǎo nǐ.","vi":"Ngày mai hoặc ngày kia tôi đến tìm bạn.","en":"I'll come to see you tomorrow or the day after."},{"use":"或者 + ……，或者 + ……: hoặc là… hoặc là…","ex":"我们或者坐地铁，或者打车去。","py":"Wǒmen huòzhě zuò dìtiě, huòzhě dǎ chē qù.","vi":"Chúng ta hoặc đi tàu điện ngầm hoặc đi taxi.","en":"We can take the subway or a taxi."},{"use":"Khác 还是: 或者 dùng trong câu khẳng định, 还是 dùng trong câu hỏi.","ex":"你可以给我打电话或者发短信。","py":"Nǐ kěyǐ gěi wǒ dǎ diànhuà huòzhě fā duǎnxìn.","vi":"Bạn có thể gọi điện hoặc nhắn tin cho tôi.","en":"You can call me or text me."}]},"记得":{"en":"to remember","exs":[{"use":"记得 + việc/người: còn nhớ.","ex":"你还记得我吗？","py":"Nǐ hái jìde wǒ ma?","vi":"Bạn còn nhớ tôi không?","en":"Do you still remember me?"},{"use":"记得 + 动词: nhớ phải làm gì.","ex":"出门记得带钥匙。","py":"Chūmén jìde dài yàoshi.","vi":"Ra ngoài nhớ mang theo chìa khóa.","en":"Remember to take your keys when you go out."},{"use":"不记得: không nhớ.","ex":"我不记得他叫什么名字了。","py":"Wǒ bú jìde tā jiào shénme míngzi le.","vi":"Tôi không nhớ anh ấy tên là gì nữa.","en":"I don't remember his name any more."}]},"裤子":{"en":"trousers; pants","exs":[{"use":"Danh từ; lượng từ: 条.","ex":"这条裤子太长了。","py":"Zhè tiáo kùzi tài cháng le.","vi":"Chiếc quần này dài quá.","en":"These trousers are too long."},{"use":"穿裤子 / 买裤子: mặc / mua quần.","ex":"他今天穿了一条黑裤子。","py":"Tā jīntiān chuān le yì tiáo hēi kùzi.","vi":"Hôm nay anh ấy mặc quần đen.","en":"He is wearing black trousers today."},{"use":"一条裤子: một chiếc quần.","ex":"我想试试那条蓝裤子。","py":"Wǒ xiǎng shìshi nà tiáo lán kùzi.","vi":"Tôi muốn thử chiếc quần xanh kia.","en":"I'd like to try on those blue trousers."}]},"绿":{"en":"green","exs":[{"use":"Tính từ chỉ màu; cũng nói 绿色.","ex":"春天来了，树都绿了。","py":"Chūntiān lái le, shù dōu lǜ le.","vi":"Mùa xuân đến, cây cối đều xanh rồi.","en":"Spring has come and the trees have turned green."},{"use":"绿 + 的 + danh từ.","ex":"我喜欢那件绿的衬衫。","py":"Wǒ xǐhuan nà jiàn lǜ de chènshān.","vi":"Tôi thích chiếc sơ mi xanh lá kia.","en":"I like that green shirt."},{"use":"绿茶: trà xanh.","ex":"他每天早上喝一杯绿茶。","py":"Tā měitiān zǎoshang hē yì bēi lǜchá.","vi":"Mỗi sáng anh ấy uống một tách trà xanh.","en":"He drinks a cup of green tea every morning."}]},"爬山":{"en":"to climb a mountain; to hike","exs":[{"use":"Động từ ly hợp: 爬 + 山; có thể chen từ vào giữa.","ex":"周末我们去爬山吧。","py":"Zhōumò wǒmen qù pá shān ba.","vi":"Cuối tuần chúng ta đi leo núi nhé.","en":"Let's go hiking this weekend."},{"use":"爬过山: đã từng leo núi.","ex":"你爬过泰山吗？","py":"Nǐ pá guo Tài Shān ma?","vi":"Bạn đã từng leo núi Thái Sơn chưa?","en":"Have you ever climbed Mount Tai?"},{"use":"爬山 + 很累 / 对身体好.","ex":"爬山对身体很好。","py":"Pá shān duì shēntǐ hěn hǎo.","vi":"Leo núi rất tốt cho sức khỏe.","en":"Hiking is good for your health."}]},"舒服":{"en":"comfortable; well","exs":[{"use":"Tính từ chỉ cảm giác thoải mái về cơ thể hoặc tinh thần.","ex":"这把椅子坐着很舒服。","py":"Zhè bǎ yǐzi zuò zhe hěn shūfu.","vi":"Chiếc ghế này ngồi rất thoải mái.","en":"This chair is very comfortable to sit on."},{"use":"不舒服: không khỏe, khó chịu.","ex":"我今天有点儿不舒服，想回家休息。","py":"Wǒ jīntiān yǒudiǎnr bù shūfu, xiǎng huí jiā xiūxi.","vi":"Hôm nay tôi hơi không khỏe, muốn về nhà nghỉ.","en":"I don't feel well today and want to go home to rest."},{"use":"穿着舒服: mặc thấy thoải mái.","ex":"这双鞋穿着很舒服。","py":"Zhè shuāng xié chuān zhe hěn shūfu.","vi":"Đôi giày này đi rất êm chân.","en":"These shoes are very comfortable to wear."}]},"甜":{"en":"sweet","exs":[{"use":"Tính từ chỉ vị ngọt.","ex":"这个西瓜很甜。","py":"Zhège xīguā hěn tián.","vi":"Quả dưa hấu này rất ngọt.","en":"This watermelon is very sweet."},{"use":"太甜 / 不甜: ngọt quá / không ngọt.","ex":"这杯咖啡太甜了，我不想喝。","py":"Zhè bēi kāfēi tài tián le, wǒ bù xiǎng hē.","vi":"Cà phê này ngọt quá, tôi không muốn uống.","en":"This coffee is too sweet; I don't want it."},{"use":"甜的 / 甜点: đồ ngọt.","ex":"孩子们都爱吃甜的。","py":"Háizimen dōu ài chī tián de.","vi":"Trẻ con đều thích ăn đồ ngọt.","en":"Kids all love sweet things."}]},"条":{"en":"measure word for long thin things (trousers, skirts, fish, roads)","exs":[{"use":"一条 + quần / váy / cá / đường / sông.","ex":"她买了一条新裙子。","py":"Tā mǎi le yì tiáo xīn qúnzi.","vi":"Cô ấy mua một chiếc váy mới.","en":"She bought a new skirt."},{"use":"一条河 / 一条路.","ex":"这条路很安静。","py":"Zhè tiáo lù hěn ānjìng.","vi":"Con đường này rất yên tĩnh.","en":"This road is very quiet."},{"use":"一条鱼.","ex":"桌子上有一条大鱼。","py":"Zhuōzi shàng yǒu yì tiáo dà yú.","vi":"Trên bàn có một con cá to.","en":"There is a big fish on the table."}]},"小心":{"en":"careful; to be careful","exs":[{"use":"小心 + động từ/danh từ: cẩn thận với…","ex":"路很滑，小心一点儿。","py":"Lù hěn huá, xiǎoxīn yìdiǎnr.","vi":"Đường rất trơn, cẩn thận chút nhé.","en":"The road is slippery; be careful."},{"use":"小心 + 汽车: coi chừng (xe).","ex":"过马路要小心汽车。","py":"Guò mǎlù yào xiǎoxīn qìchē.","vi":"Qua đường phải coi chừng xe cộ.","en":"Watch out for cars when crossing the road."},{"use":"小心 + 点儿 + 别 + …: cẩn thận đừng…","ex":"小心别把杯子打碎了。","py":"Xiǎoxīn bié bǎ bēizi dǎsuì le.","vi":"Cẩn thận đừng làm vỡ cái cốc.","en":"Careful not to break the cup."}]},"新鲜":{"en":"fresh","exs":[{"use":"Tính từ dùng cho đồ ăn, không khí…","ex":"这些水果很新鲜。","py":"Zhèxiē shuǐguǒ hěn xīnxiān.","vi":"Những loại trái cây này rất tươi.","en":"These fruits are very fresh."},{"use":"新鲜空气: không khí trong lành.","ex":"早上公园里的空气很新鲜。","py":"Zǎoshang gōngyuán lǐ de kōngqì hěn xīnxiān.","vi":"Buổi sáng không khí trong công viên rất trong lành.","en":"The air in the park is fresh in the morning."},{"use":"新鲜事: chuyện mới lạ.","ex":"你有什么新鲜事要告诉我吗？","py":"Nǐ yǒu shénme xīnxiān shì yào gàosu wǒ ma?","vi":"Bạn có chuyện gì mới muốn kể cho tôi không?","en":"Do you have any news for me?"}]},"饮料":{"en":"drink; beverage","exs":[{"use":"Danh từ chung chỉ các loại đồ uống.","ex":"冰箱里有很多饮料。","py":"Bīngxiāng lǐ yǒu hěn duō yǐnliào.","vi":"Trong tủ lạnh có rất nhiều đồ uống.","en":"There are many drinks in the fridge."},{"use":"喝饮料.","ex":"你想喝什么饮料？","py":"Nǐ xiǎng hē shénme yǐnliào?","vi":"Bạn muốn uống gì?","en":"What would you like to drink?"},{"use":"买饮料.","ex":"我去超市买几瓶饮料。","py":"Wǒ qù chāoshì mǎi jǐ píng yǐnliào.","vi":"Tôi đi siêu thị mua vài chai nước.","en":"I'm going to the supermarket to buy some drinks."}]},"元":{"en":"yuan (unit of money)","exs":[{"use":"Số + 元: số tiền (văn viết; khẩu ngữ hay nói 块).","ex":"这件衬衫一百元。","py":"Zhè jiàn chènshān yì bǎi yuán.","vi":"Chiếc sơ mi này 100 tệ.","en":"This shirt costs 100 yuan."},{"use":"多少元: bao nhiêu tệ.","ex":"这双鞋多少元？","py":"Zhè shuāng xié duōshao yuán?","vi":"Đôi giày này bao nhiêu tệ?","en":"How many yuan are these shoes?"},{"use":"一共 + số + 元.","ex":"一共三十五元。","py":"Yígòng sānshíwǔ yuán.","vi":"Tổng cộng 35 tệ.","en":"That's 35 yuan in total."}]},"只":{"en":"only; just; measure word for animals; only","exs":[{"use":"只 + động từ: chỉ làm gì.","ex":"我只喝了一杯茶。","py":"Wǒ zhǐ hē le yì bēi chá.","vi":"Tôi chỉ uống một tách trà.","en":"I only had a cup of tea."},{"use":"只 + 有/是 + …: chỉ có/chỉ là…","ex":"教室里只有三个人。","py":"Jiàoshì lǐ zhǐ yǒu sān ge rén.","vi":"Trong lớp chỉ có ba người.","en":"There are only three people in the classroom."},{"use":"只 + 要/好: chỉ cần / đành phải.","ex":"我只想早点儿回家。","py":"Wǒ zhǐ xiǎng zǎodiǎnr huí jiā.","vi":"Tôi chỉ muốn về nhà sớm.","en":"I just want to go home early."},{"use":"只 (zhī): lượng từ cho động vật nhỏ, một chiếc trong cặp.","ex":"我家有一只小猫。","py":"Wǒ jiā yǒu yì zhī xiǎo māo.","vi":"Nhà tôi có một con mèo nhỏ.","en":"We have a little cat at home."},{"use":"一只鸟 / 两只手.","ex":"树上有三只鸟。","py":"Shù shàng yǒu sān zhī niǎo.","vi":"Trên cây có ba con chim.","en":"There are three birds in the tree."},{"use":"一只 + 眼睛 / 鞋.","ex":"我找不到另一只鞋了。","py":"Wǒ zhǎo bú dào lìng yì zhī xié le.","vi":"Tôi không tìm thấy chiếc giày còn lại.","en":"I can't find the other shoe."}]},"比赛":{"en":"match; competition","exs":[{"use":"Danh từ/động từ: 参加比赛, 比赛 + 结果.","ex":"明天有一场足球比赛。","py":"Míngtiān yǒu yì chǎng zúqiú bǐsài.","vi":"Ngày mai có một trận bóng đá.","en":"There is a football match tomorrow."},{"use":"参加比赛: tham gia thi đấu.","ex":"她想参加汉语比赛。","py":"Tā xiǎng cānjiā Hànyǔ bǐsài.","vi":"Cô ấy muốn tham gia cuộc thi tiếng Hán.","en":"She wants to take part in the Chinese contest."},{"use":"赢了 / 输了比赛: thắng / thua.","ex":"我们班赢了这次比赛。","py":"Wǒmen bān yíng le zhè cì bǐsài.","vi":"Lớp chúng tôi đã thắng cuộc thi lần này.","en":"Our class won this competition."}]},"超市":{"en":"supermarket","exs":[{"use":"Danh từ chỉ nơi mua sắm.","ex":"我去超市买水果。","py":"Wǒ qù chāoshì mǎi shuǐguǒ.","vi":"Tôi đi siêu thị mua trái cây.","en":"I'm going to the supermarket for fruit."},{"use":"去超市 / 在超市.","ex":"他在超市工作。","py":"Tā zài chāoshì gōngzuò.","vi":"Anh ấy làm việc ở siêu thị.","en":"He works at a supermarket."},{"use":"超市 + 附近: gần siêu thị.","ex":"我家就在超市旁边。","py":"Wǒ jiā jiù zài chāoshì pángbiān.","vi":"Nhà tôi ngay cạnh siêu thị.","en":"My home is right next to the supermarket."}]},"聪明":{"en":"clever; smart","exs":[{"use":"Tính từ chỉ người hoặc động vật.","ex":"这个孩子很聪明。","py":"Zhège háizi hěn cōngmíng.","vi":"Đứa trẻ này rất thông minh.","en":"This child is very smart."},{"use":"聪明 + 又 + 努力: thông minh lại chăm chỉ.","ex":"他又聪明又努力。","py":"Tā yòu cōngmíng yòu nǔlì.","vi":"Anh ấy vừa thông minh vừa chăm chỉ.","en":"He is both smart and hard-working."},{"use":"不聪明 / 太聪明了.","ex":"这只狗太聪明了。","py":"Zhè zhī gǒu tài cōngmíng le.","vi":"Con chó này thông minh quá.","en":"This dog is so clever."}]},"蛋糕":{"en":"cake","exs":[{"use":"Danh từ; lượng từ: 块, 个.","ex":"今天是我的生日，妈妈做了蛋糕。","py":"Jīntiān shì wǒ de shēngrì, māma zuò le dàngāo.","vi":"Hôm nay sinh nhật tôi, mẹ làm bánh kem.","en":"It's my birthday, and Mom made a cake."},{"use":"生日蛋糕: bánh sinh nhật.","ex":"我们买了一个大的生日蛋糕。","py":"Wǒmen mǎi le yí ge dà de shēngrì dàngāo.","vi":"Chúng tôi mua một chiếc bánh sinh nhật lớn.","en":"We bought a big birthday cake."},{"use":"吃蛋糕 / 切蛋糕.","ex":"请大家一起吃蛋糕。","py":"Qǐng dàjiā yìqǐ chī dàngāo.","vi":"Mời mọi người cùng ăn bánh.","en":"Please everyone have some cake."}]},"饿":{"en":"hungry","exs":[{"use":"Tính từ; trái nghĩa 饱.","ex":"我饿了，我们去吃饭吧。","py":"Wǒ è le, wǒmen qù chīfàn ba.","vi":"Tôi đói rồi, chúng ta đi ăn thôi.","en":"I'm hungry; let's go eat."},{"use":"饿 + 坏了: đói muốn xỉu.","ex":"一天没吃饭，他饿坏了。","py":"Yì tiān méi chīfàn, tā è huài le.","vi":"Cả ngày chưa ăn, anh ấy đói muốn xỉu.","en":"He hasn't eaten all day and is starving."},{"use":"肚子饿: bụng đói.","ex":"你肚子饿不饿？","py":"Nǐ dùzi è bu è?","vi":"Bụng bạn có đói không?","en":"Are you hungry?"}]},"分":{"en":"fen (unit of money); to divide; to distinguish; to distinguish; to divide","exs":[{"use":"分 (lượng từ): 1 đồng = 10 角 = 100 分.","ex":"这个只要五分钱。","py":"Zhège zhǐ yào wǔ fēn qián.","vi":"Cái này chỉ có năm xu.","en":"This costs only five fen."},{"use":"一块两毛五分: 1 tệ 2 hào 5 xu.","ex":"一共一块两毛五分。","py":"Yígòng yí kuài liǎng máo wǔ fēn.","vi":"Tổng cộng 1 tệ 2 hào 5 xu.","en":"That's 1 yuan, 2 jiao and 5 fen in total."},{"use":"分 (động từ): chia, phân biệt.","ex":"请把蛋糕分成四块。","py":"Qǐng bǎ dàngāo fēn chéng sì kuài.","vi":"Hãy chia chiếc bánh thành bốn miếng.","en":"Please cut the cake into four pieces."},{"use":"分 + 清楚 / 开: phân biệt, tách ra.","ex":"我分不清这两个字。","py":"Wǒ fēn bù qīng zhè liǎng ge zì.","vi":"Tôi không phân biệt được hai chữ này.","en":"I can't tell these two characters apart."},{"use":"分 + 成: chia thành.","ex":"请把这些书分成两类。","py":"Qǐng bǎ zhèxiē shū fēn chéng liǎng lèi.","vi":"Hãy chia những quyển sách này thành hai loại.","en":"Please divide these books into two groups."},{"use":"分 + 手 / 开: chia tay, tách ra.","ex":"他们去年分手了。","py":"Tāmen qùnián fēn shǒu le.","vi":"Họ đã chia tay vào năm ngoái.","en":"They broke up last year."}]},"回答":{"en":"to answer; to reply","exs":[{"use":"回答 + câu hỏi: trả lời câu hỏi.","ex":"请回答我的问题。","py":"Qǐng huídá wǒ de wèntí.","vi":"Xin hãy trả lời câu hỏi của tôi.","en":"Please answer my question."},{"use":"回答得 + 很好: trả lời rất tốt.","ex":"他回答得很清楚。","py":"Tā huídá de hěn qīngchu.","vi":"Anh ấy trả lời rất rõ ràng.","en":"He answered very clearly."},{"use":"回答不了: không trả lời được.","ex":"这个问题我回答不了。","py":"Zhège wèntí wǒ huídá bù liǎo.","vi":"Câu hỏi này tôi không trả lời được.","en":"I can't answer this question."}]},"角":{"en":"jiao (1/10 yuan)","exs":[{"use":"角 (= 毛): 10 角 = 1 元.","ex":"这支笔五角钱。","py":"Zhè zhī bǐ wǔ jiǎo qián.","vi":"Cây bút này năm hào.","en":"This pen costs five jiao."},{"use":"一元五角: 1 tệ 5 hào.","ex":"一杯豆浆一元五角。","py":"Yì bēi dòujiāng yì yuán wǔ jiǎo.","vi":"Một cốc sữa đậu nành 1 tệ 5 hào.","en":"A cup of soy milk costs 1.5 yuan."},{"use":"几角: mấy hào.","ex":"这个多少钱？三块四角。","py":"Zhège duōshao qián? Sān kuài sì jiǎo.","vi":"Cái này bao nhiêu? Ba tệ bốn hào.","en":"How much is this? 3.4 yuan."}]},"客人":{"en":"guest; customer","exs":[{"use":"Danh từ; chỉ khách đến nhà hoặc khách hàng.","ex":"家里来了几位客人。","py":"Jiā lǐ lái le jǐ wèi kèrén.","vi":"Trong nhà có vài vị khách đến.","en":"Some guests have come to our home."},{"use":"接待客人: tiếp khách.","ex":"她热情地接待客人。","py":"Tā rèqíng de jiēdài kèrén.","vi":"Cô ấy nhiệt tình tiếp khách.","en":"She welcomes the guests warmly."},{"use":"饭馆的客人: khách quán ăn.","ex":"今天饭馆的客人特别多。","py":"Jīntiān fànguǎn de kèrén tèbié duō.","vi":"Hôm nay khách quán ăn đặc biệt đông.","en":"There are especially many customers at the restaurant today."}]},"年级":{"en":"grade; year (at school)","exs":[{"use":"一年级 / 二年级…: lớp 1, lớp 2…","ex":"我弟弟上三年级。","py":"Wǒ dìdi shàng sān niánjí.","vi":"Em trai tôi học lớp ba.","en":"My younger brother is in third grade."},{"use":"你几年级？: bạn học năm mấy?","ex":"你是几年级的学生？","py":"Nǐ shì jǐ niánjí de xuésheng?","vi":"Bạn là sinh viên năm mấy?","en":"What year are you in?"},{"use":"同年级: cùng khối.","ex":"我们是同年级的同学。","py":"Wǒmen shì tóng niánjí de tóngxué.","vi":"Chúng tôi là bạn cùng khối.","en":"We are classmates in the same grade."}]},"年轻":{"en":"young","exs":[{"use":"Tính từ chỉ người trẻ tuổi.","ex":"她看起来很年轻。","py":"Tā kàn qǐlai hěn niánqīng.","vi":"Cô ấy trông rất trẻ.","en":"She looks very young."},{"use":"年轻人: người trẻ.","ex":"年轻人应该多锻炼身体。","py":"Niánqīngrén yīnggāi duō duànliàn shēntǐ.","vi":"Người trẻ nên tập thể dục nhiều.","en":"Young people should exercise more."},{"use":"年轻 + 的 + 老师.","ex":"我们的新老师很年轻。","py":"Wǒmen de xīn lǎoshī hěn niánqīng.","vi":"Cô giáo mới của chúng tôi rất trẻ.","en":"Our new teacher is very young."}]},"努力":{"en":"hard-working; to make an effort","exs":[{"use":"Tính từ/động từ: 努力 + 学习/工作.","ex":"他学习很努力。","py":"Tā xuéxí hěn nǔlì.","vi":"Anh ấy học rất chăm chỉ.","en":"He studies very hard."},{"use":"努力 + 地 + động từ.","ex":"她努力地练习写汉字。","py":"Tā nǔlì de liànxí xiě Hànzì.","vi":"Cô ấy chăm chỉ luyện viết chữ Hán.","en":"She works hard at practicing characters."},{"use":"继续努力: tiếp tục cố gắng.","ex":"你要继续努力，别放弃。","py":"Nǐ yào jìxù nǔlì, bié fàngqì.","vi":"Bạn cần tiếp tục cố gắng, đừng bỏ cuộc.","en":"Keep working hard and don't give up."}]},"热情":{"en":"warm; enthusiastic","exs":[{"use":"Tính từ chỉ thái độ đối với người khác.","ex":"这里的服务员都很热情。","py":"Zhèlǐ de fúwùyuán dōu hěn rèqíng.","vi":"Nhân viên phục vụ ở đây đều rất nhiệt tình.","en":"The waiters here are all very warm."},{"use":"热情 + 地 + động từ.","ex":"他热情地欢迎我们。","py":"Tā rèqíng de huānyíng wǒmen.","vi":"Anh ấy nhiệt tình chào đón chúng tôi.","en":"He welcomed us warmly."},{"use":"对人热情: nhiệt tình với mọi người.","ex":"她对客人总是很热情。","py":"Tā duì kèrén zǒngshì hěn rèqíng.","vi":"Cô ấy luôn nhiệt tình với khách.","en":"She is always warm toward customers."}]},"认真":{"en":"serious; conscientious","exs":[{"use":"Tính từ/động từ: làm việc nghiêm túc.","ex":"他做事很认真。","py":"Tā zuò shì hěn rènzhēn.","vi":"Anh ấy làm việc rất nghiêm túc.","en":"He is very serious about his work."},{"use":"认真 + 地 + động từ.","ex":"学生们认真地听老师讲课。","py":"Xuéshengmen rènzhēn de tīng lǎoshī jiǎngkè.","vi":"Học sinh chăm chú nghe thầy giảng bài.","en":"The students listen to the teacher attentively."},{"use":"认真 + 一点儿: cẩn thận hơn một chút.","ex":"写作业的时候要认真一点儿。","py":"Xiě zuòyè de shíhou yào rènzhēn yìdiǎnr.","vi":"Khi làm bài tập cần cẩn thận hơn một chút.","en":"Be more careful when you do your homework."}]},"又":{"en":"and; again","exs":[{"use":"又……又……: vừa… vừa… (hai tính chất cùng lúc).","ex":"这个蛋糕又好看又好吃。","py":"Zhège dàngāo yòu hǎokàn yòu hǎochī.","vi":"Chiếc bánh này vừa đẹp vừa ngon.","en":"This cake looks great and tastes great."},{"use":"又 + động từ: lại (việc đã xảy ra, lặp lại).","ex":"他昨天迟到了，今天又迟到了。","py":"Tā zuótiān chídào le, jīntiān yòu chídào le.","vi":"Hôm qua anh ấy đi muộn, hôm nay lại đi muộn.","en":"He was late yesterday and is late again today."},{"use":"又 + 来 / 下雨: lại đến / lại mưa.","ex":"外面又下雨了。","py":"Wàimiàn yòu xià yǔ le.","vi":"Bên ngoài lại mưa rồi.","en":"It's raining again outside."}]},"站":{"en":"to stand; station","exs":[{"use":"站 + 在 + nơi chốn: đứng ở đâu.","ex":"他站在门口等你。","py":"Tā zhàn zài ménkǒu děng nǐ.","vi":"Anh ấy đứng ở cửa đợi bạn.","en":"He's standing at the door waiting for you."},{"use":"站起来: đứng dậy.","ex":"老师来了，大家都站了起来。","py":"Lǎoshī lái le, dàjiā dōu zhàn le qǐlai.","vi":"Thầy giáo đến, mọi người đều đứng dậy.","en":"The teacher came in and everyone stood up."},{"use":"车站 / 地铁站: bến xe / ga tàu điện.","ex":"地铁站就在前面。","py":"Dìtiě zhàn jiù zài qiánmiàn.","vi":"Ga tàu điện ngầm ở ngay phía trước.","en":"The subway station is just ahead."}]},"照片":{"en":"photo; picture","exs":[{"use":"Danh từ; lượng từ: 张.","ex":"这张照片是在北京拍的。","py":"Zhè zhāng zhàopiàn shì zài Běijīng pāi de.","vi":"Bức ảnh này chụp ở Bắc Kinh.","en":"This photo was taken in Beijing."},{"use":"拍照片 / 看照片: chụp ảnh / xem ảnh.","ex":"我们一起看看旅行的照片吧。","py":"Wǒmen yìqǐ kànkan lǚxíng de zhàopiàn ba.","vi":"Chúng ta cùng xem ảnh chuyến du lịch nhé.","en":"Let's look at the travel photos together."},{"use":"照片 + 上: trong ảnh.","ex":"照片上的人是我爷爷。","py":"Zhàopiàn shàng de rén shì wǒ yéye.","vi":"Người trong ảnh là ông nội tôi.","en":"The person in the photo is my grandfather."}]},"总是":{"en":"always","exs":[{"use":"总是 + động từ: thói quen lặp đi lặp lại.","ex":"他总是第一个到教室。","py":"Tā zǒngshì dì-yī ge dào jiàoshì.","vi":"Anh ấy luôn là người đến lớp đầu tiên.","en":"He is always the first to arrive in the classroom."},{"use":"总是 + 笑 / 迟到: lúc nào cũng cười / muộn.","ex":"她总是笑着跟客人说话。","py":"Tā zǒngshì xiào zhe gēn kèrén shuōhuà.","vi":"Cô ấy luôn mỉm cười khi nói chuyện với khách.","en":"She always smiles when talking to customers."},{"use":"不总是: không phải lúc nào cũng.","ex":"他不总是这么忙。","py":"Tā bù zǒngshì zhème máng.","vi":"Không phải lúc nào anh ấy cũng bận thế này.","en":"He isn't always this busy."}]},"草":{"en":"grass","exs":[{"use":"Danh từ: cỏ; 草地: bãi cỏ.","ex":"春天，草都绿了。","py":"Chūntiān, cǎo dōu lǜ le.","vi":"Mùa xuân, cỏ đều xanh cả.","en":"In spring the grass turns green."},{"use":"草地 + 上: trên bãi cỏ.","ex":"孩子们在草地上玩儿。","py":"Háizimen zài cǎodì shàng wánr.","vi":"Bọn trẻ chơi trên bãi cỏ.","en":"The children are playing on the lawn."},{"use":"小草: cỏ non.","ex":"小草在雨后长得很快。","py":"Xiǎo cǎo zài yǔ hòu zhǎng de hěn kuài.","vi":"Cỏ non mọc rất nhanh sau mưa.","en":"Grass grows fast after rain."}]},"春（天）":{"en":"spring","exs":[{"use":"Danh từ chỉ mùa; nói gọn 春 trong từ ghép.","ex":"春天来了，天气变暖了。","py":"Chūntiān lái le, tiānqì biàn nuǎn le.","vi":"Mùa xuân đến, thời tiết ấm lên.","en":"Spring has come and it's getting warmer."},{"use":"春天 + 的 + 花.","ex":"春天的花开得很漂亮。","py":"Chūntiān de huā kāi de hěn piàoliang.","vi":"Hoa mùa xuân nở rất đẹp.","en":"Spring flowers bloom beautifully."},{"use":"春天 + 最 + 喜欢.","ex":"我最喜欢春天。","py":"Wǒ zuì xǐhuan chūntiān.","vi":"Tôi thích mùa xuân nhất.","en":"I like spring best."}]},"当然":{"en":"of course","exs":[{"use":"Phó từ khẳng định chắc chắn.","ex":"你会来吗？当然会。","py":"Nǐ huì lái ma? Dāngrán huì.","vi":"Bạn sẽ đến chứ? Đương nhiên rồi.","en":"Will you come? Of course."},{"use":"当然 + 可以 / 是.","ex":"当然可以，请坐。","py":"Dāngrán kěyǐ, qǐng zuò.","vi":"Đương nhiên được, mời ngồi.","en":"Of course you can; please sit."},{"use":"当然 + 不 + động từ.","ex":"我当然不会骗你。","py":"Wǒ dāngrán bú huì piàn nǐ.","vi":"Tất nhiên tôi sẽ không lừa bạn.","en":"Of course I wouldn't lie to you."}]},"发烧":{"en":"to have a fever","exs":[{"use":"Động từ ly hợp: 发 + 烧.","ex":"他发烧了，要去医院。","py":"Tā fā shāo le, yào qù yīyuàn.","vi":"Anh ấy bị sốt, phải đi bệnh viện.","en":"He has a fever and needs to go to the hospital."},{"use":"发高烧: sốt cao.","ex":"孩子昨晚发了高烧。","py":"Háizi zuówǎn fā le gāoshāo.","vi":"Tối qua đứa trẻ sốt cao.","en":"The child ran a high fever last night."},{"use":"发烧 + 感冒: sốt kèm cảm.","ex":"我感冒了，还有点儿发烧。","py":"Wǒ gǎnmào le, hái yǒudiǎnr fā shāo.","vi":"Tôi bị cảm, lại hơi sốt.","en":"I have a cold and a slight fever."}]},"感冒":{"en":"cold; to catch a cold","exs":[{"use":"Danh từ/động từ.","ex":"天气冷了，小心感冒。","py":"Tiānqì lěng le, xiǎoxīn gǎnmào.","vi":"Trời lạnh rồi, coi chừng cảm.","en":"It's getting cold; be careful not to catch a cold."},{"use":"感冒了: bị cảm.","ex":"我昨天感冒了，头很疼。","py":"Wǒ zuótiān gǎnmào le, tóu hěn téng.","vi":"Hôm qua tôi bị cảm, đầu rất đau.","en":"I caught a cold yesterday and have a bad headache."},{"use":"得了感冒 / 感冒药: bị cảm / thuốc cảm.","ex":"吃了感冒药，他好多了。","py":"Chī le gǎnmào yào, tā hǎo duō le.","vi":"Uống thuốc cảm xong anh ấy đỡ nhiều rồi.","en":"He feels much better after taking cold medicine."}]},"季节":{"en":"season","exs":[{"use":"Danh từ: 四个季节 = xuân, hạ, thu, đông.","ex":"一年有四个季节。","py":"Yì nián yǒu sì ge jìjié.","vi":"Một năm có bốn mùa.","en":"There are four seasons in a year."},{"use":"最喜欢的季节: mùa yêu thích.","ex":"你最喜欢哪个季节？","py":"Nǐ zuì xǐhuan nǎge jìjié?","vi":"Bạn thích mùa nào nhất?","en":"Which season do you like best?"},{"use":"这个季节: mùa này.","ex":"这个季节常常下雨。","py":"Zhège jìjié chángcháng xià yǔ.","vi":"Mùa này hay có mưa.","en":"It often rains in this season."}]},"裙子":{"en":"skirt; dress","exs":[{"use":"Danh từ; lượng từ: 条.","ex":"她穿着一条红裙子。","py":"Tā chuān zhe yì tiáo hóng qúnzi.","vi":"Cô ấy mặc chiếc váy đỏ.","en":"She is wearing a red skirt."},{"use":"夏天穿裙子.","ex":"夏天很多女孩儿喜欢穿裙子。","py":"Xiàtiān hěn duō nǚháir xǐhuan chuān qúnzi.","vi":"Mùa hè nhiều cô gái thích mặc váy.","en":"Many girls like wearing skirts in summer."},{"use":"买裙子.","ex":"这条裙子是我昨天买的。","py":"Zhè tiáo qúnzi shì wǒ zuótiān mǎi de.","vi":"Chiếc váy này tôi mới mua hôm qua.","en":"I bought this skirt yesterday."}]},"为":{"en":"for; on behalf of","exs":[{"use":"为 + người/việc + động từ: vì ai, vì việc gì.","ex":"我为你高兴。","py":"Wǒ wèi nǐ gāoxìng.","vi":"Tôi mừng cho bạn.","en":"I'm happy for you."},{"use":"为 + 人 + 服务: phục vụ ai.","ex":"她为客人准备了茶。","py":"Tā wèi kèrén zhǔnbèi le chá.","vi":"Cô ấy pha trà cho khách.","en":"She prepared tea for the guests."},{"use":"为 + 什么: vì sao.","ex":"你为什么没来上课？","py":"Nǐ wèishénme méi lái shàngkè?","vi":"Vì sao bạn không đến lớp?","en":"Why didn't you come to class?"}]},"夏（天）":{"en":"summer","exs":[{"use":"Danh từ chỉ mùa.","ex":"夏天太热了。","py":"Xiàtiān tài rè le.","vi":"Mùa hè nóng quá.","en":"Summer is too hot."},{"use":"夏天 + 常常 + động từ.","ex":"夏天我们常常去游泳。","py":"Xiàtiān wǒmen chángcháng qù yóuyǒng.","vi":"Mùa hè chúng tôi hay đi bơi.","en":"We often go swimming in summer."},{"use":"夏天 + 的 + 晚上.","ex":"夏天的晚上可以在外面乘凉。","py":"Xiàtiān de wǎnshang kěyǐ zài wàimiàn chéngliáng.","vi":"Buổi tối mùa hè có thể ra ngoài hóng mát.","en":"On summer evenings you can cool off outside."}]},"用":{"en":"to use; to need","exs":[{"use":"用 + công cụ + động từ: dùng cái gì để làm gì.","ex":"我用手机听音乐。","py":"Wǒ yòng shǒujī tīng yīnyuè.","vi":"Tôi dùng điện thoại nghe nhạc.","en":"I listen to music on my phone."},{"use":"不用: không cần.","ex":"你不用来接我。","py":"Nǐ búyòng lái jiē wǒ.","vi":"Bạn không cần đến đón tôi.","en":"You don't need to pick me up."},{"use":"用 + 汉语 + 说: nói bằng tiếng Hán.","ex":"请用汉语回答。","py":"Qǐng yòng Hànyǔ huídá.","vi":"Xin hãy trả lời bằng tiếng Hán.","en":"Please answer in Chinese."}]},"越":{"en":"the more…","exs":[{"use":"越来越 + tính từ: ngày càng…","ex":"天气越来越热了。","py":"Tiānqì yuè lái yuè rè le.","vi":"Thời tiết ngày càng nóng.","en":"The weather is getting hotter and hotter."},{"use":"越 A 越 B: càng A càng B.","ex":"汉语越学越有意思。","py":"Hànyǔ yuè xué yuè yǒu yìsi.","vi":"Tiếng Hán càng học càng thú vị.","en":"The more I study Chinese, the more interesting it is."},{"use":"越来越 + 喜欢.","ex":"我越来越喜欢这座城市。","py":"Wǒ yuè lái yuè xǐhuan zhè zuò chéngshì.","vi":"Tôi ngày càng thích thành phố này.","en":"I like this city more and more."}]},"照顾":{"en":"to take care of","exs":[{"use":"照顾 + người: chăm sóc ai.","ex":"她在家照顾生病的妈妈。","py":"Tā zài jiā zhàogù shēngbìng de māma.","vi":"Cô ấy ở nhà chăm sóc mẹ bị ốm.","en":"She stays home to care for her sick mother."},{"use":"照顾好 + ……: chăm sóc tốt.","ex":"你要照顾好自己。","py":"Nǐ yào zhàogù hǎo zìjǐ.","vi":"Bạn phải chăm sóc tốt bản thân nhé.","en":"Take good care of yourself."},{"use":"谢谢你的照顾: cảm ơn sự chăm sóc.","ex":"谢谢你一直照顾我。","py":"Xièxie nǐ yìzhí zhàogù wǒ.","vi":"Cảm ơn bạn luôn chăm sóc tôi.","en":"Thank you for always taking care of me."}]},"最近":{"en":"recently; lately","exs":[{"use":"Phó từ/danh từ chỉ thời gian: thường đứng trước động từ.","ex":"你最近怎么样？","py":"Nǐ zuìjìn zěnmeyàng?","vi":"Dạo này bạn thế nào?","en":"How have you been lately?"},{"use":"最近 + 很忙 / 常常.","ex":"我最近很忙，没时间去玩儿。","py":"Wǒ zuìjìn hěn máng, méi shíjiān qù wánr.","vi":"Dạo này tôi rất bận, không có thời gian đi chơi.","en":"I've been busy lately and have no time to play."},{"use":"最近 + 才 / 刚: gần đây mới.","ex":"他最近才搬到这里。","py":"Tā zuìjìn cái bān dào zhèlǐ.","vi":"Gần đây anh ấy mới chuyển đến đây.","en":"He only moved here recently."}]},"帮忙":{"en":"to help","exs":[{"use":"Động từ ly hợp: 帮 + 忙; có thể nói 帮 + người + 忙.","ex":"你能帮我一个忙吗？","py":"Nǐ néng bāng wǒ yí ge máng ma?","vi":"Bạn có thể giúp tôi một việc không?","en":"Could you do me a favor?"},{"use":"帮忙 + 做 + việc.","ex":"他常常帮忙照顾邻居的孩子。","py":"Tā chángcháng bāngmáng zhàogù línjū de háizi.","vi":"Anh ấy thường giúp trông con cho hàng xóm.","en":"He often helps look after the neighbor's child."},{"use":"谢谢你的帮忙 / 请帮忙.","ex":"谢谢你来帮忙。","py":"Xièxie nǐ lái bāngmáng.","vi":"Cảm ơn bạn đã đến giúp.","en":"Thanks for coming to help."}]},"锻炼":{"en":"to exercise; to train","exs":[{"use":"锻炼 + 身体: rèn luyện sức khỏe.","ex":"他每天早上锻炼身体。","py":"Tā měitiān zǎoshang duànliàn shēntǐ.","vi":"Mỗi sáng anh ấy tập thể dục.","en":"He exercises every morning."},{"use":"锻炼 + 一下 / 一个小时.","ex":"我想每天锻炼一个小时。","py":"Wǒ xiǎng měitiān duànliàn yí ge xiǎoshí.","vi":"Tôi muốn mỗi ngày tập một tiếng.","en":"I want to exercise an hour a day."},{"use":"多锻炼: tập nhiều.","ex":"你要多锻炼，身体才健康。","py":"Nǐ yào duō duànliàn, shēntǐ cái jiànkāng.","vi":"Bạn phải tập nhiều thì cơ thể mới khỏe.","en":"You need to exercise more to stay healthy."}]},"刚才":{"en":"just now","exs":[{"use":"Danh từ chỉ thời gian; có thể đứng trước hoặc sau chủ ngữ.","ex":"刚才谁给你打电话了？","py":"Gāngcái shéi gěi nǐ dǎ diànhuà le?","vi":"Vừa nãy ai gọi điện cho bạn vậy?","en":"Who called you just now?"},{"use":"刚才 + 的 + danh từ.","ex":"刚才的话你听清楚了吗？","py":"Gāngcái de huà nǐ tīng qīngchu le ma?","vi":"Lời vừa rồi bạn nghe rõ chưa?","en":"Did you hear what was just said clearly?"},{"use":"就在刚才: ngay vừa nãy.","ex":"他就在刚才离开了。","py":"Tā jiù zài gāngcái líkāi le.","vi":"Anh ấy vừa mới rời đi ngay vừa nãy.","en":"He left just a moment ago."}]},"更":{"en":"even more","exs":[{"use":"更 + tính từ: càng hơn nữa (so sánh).","ex":"今天比昨天更冷。","py":"Jīntiān bǐ zuótiān gèng lěng.","vi":"Hôm nay lạnh hơn hôm qua.","en":"Today is even colder than yesterday."},{"use":"更 + 喜欢 / 想.","ex":"我更喜欢夏天。","py":"Wǒ gèng xǐhuan xiàtiān.","vi":"Tôi thích mùa hè hơn.","en":"I like summer even more."},{"use":"更 + 好 / 难.","ex":"这个办法更简单。","py":"Zhège bànfǎ gèng jiǎndān.","vi":"Cách này còn đơn giản hơn.","en":"This method is even simpler."}]},"公园":{"en":"park","exs":[{"use":"Danh từ chỉ nơi nghỉ ngơi, vui chơi.","ex":"我们周末去公园玩儿吧。","py":"Wǒmen zhōumò qù gōngyuán wánr ba.","vi":"Cuối tuần chúng ta đi công viên chơi nhé.","en":"Let's go to the park this weekend."},{"use":"在公园 + động từ.","ex":"老人们在公园里锻炼身体。","py":"Lǎorénmen zài gōngyuán lǐ duànliàn shēntǐ.","vi":"Người già tập thể dục trong công viên.","en":"Elderly people exercise in the park."},{"use":"公园 + 里 / 门口.","ex":"公园门口有很多人。","py":"Gōngyuán ménkǒu yǒu hěn duō rén.","vi":"Ở cổng công viên có rất nhiều người.","en":"There are many people at the park gate."}]},"讲":{"en":"to speak; to explain; to tell","exs":[{"use":"讲 + 故事 / 课: kể chuyện / giảng bài.","ex":"老师在给我们讲故事。","py":"Lǎoshī zài gěi wǒmen jiǎng gùshi.","vi":"Cô giáo đang kể chuyện cho chúng tôi.","en":"The teacher is telling us a story."},{"use":"讲 + 清楚: giải thích rõ.","ex":"请你再讲一遍，好吗？","py":"Qǐng nǐ zài jiǎng yí biàn, hǎo ma?","vi":"Bạn nói lại một lần nữa được không?","en":"Could you explain it once more?"},{"use":"讲 + 汉语 / 英语: nói tiếng.","ex":"他讲汉语讲得很流利。","py":"Tā jiǎng Hànyǔ jiǎng de hěn liúlì.","vi":"Anh ấy nói tiếng Hán rất lưu loát.","en":"He speaks Chinese fluently."}]},"离开":{"en":"to leave; to depart from","exs":[{"use":"离开 + nơi chốn / người.","ex":"他昨天已经离开北京了。","py":"Tā zuótiān yǐjīng líkāi Běijīng le.","vi":"Hôm qua anh ấy đã rời Bắc Kinh.","en":"He left Beijing yesterday."},{"use":"离开 + 家 / 学校.","ex":"她十八岁就离开了家。","py":"Tā shíbā suì jiù líkāi le jiā.","vi":"Cô ấy rời nhà từ năm mười tám tuổi.","en":"She left home at eighteen."},{"use":"离不开: không thể thiếu.","ex":"现在的人离不开手机。","py":"Xiànzài de rén lí bù kāi shǒujī.","vi":"Con người ngày nay không thể thiếu điện thoại.","en":"People today can't do without phones."}]},"聊天（儿）":{"en":"to chat","exs":[{"use":"Động từ ly hợp: 聊 + 天儿.","ex":"我们在咖啡馆聊天儿。","py":"Wǒmen zài kāfēiguǎn liáotiānr.","vi":"Chúng tôi trò chuyện ở quán cà phê.","en":"We chat in the café."},{"use":"跟 + người + 聊天.","ex":"我常跟朋友聊天儿。","py":"Wǒ cháng gēn péngyou liáotiānr.","vi":"Tôi thường trò chuyện với bạn bè.","en":"I often chat with friends."},{"use":"聊了一会儿天: trò chuyện một lúc.","ex":"他们聊了一个小时的天。","py":"Tāmen liáo le yí ge xiǎoshí de tiān.","vi":"Họ trò chuyện suốt một tiếng.","en":"They chatted for an hour."}]},"明白":{"en":"to understand; clear","exs":[{"use":"Tính từ/động từ: hiểu rõ.","ex":"老师讲得很清楚，我都明白了。","py":"Lǎoshī jiǎng de hěn qīngchu, wǒ dōu míngbai le.","vi":"Thầy giảng rất rõ, tôi hiểu hết rồi.","en":"The teacher explained clearly and I understood."},{"use":"不明白: không hiểu.","ex":"这个句子我不太明白。","py":"Zhège jùzi wǒ bú tài míngbai.","vi":"Câu này tôi không hiểu lắm.","en":"I don't quite understand this sentence."},{"use":"明白 + 了吗: hiểu chưa.","ex":"你明白我的意思了吗？","py":"Nǐ míngbai wǒ de yìsi le ma?","vi":"Bạn hiểu ý tôi chưa?","en":"Do you understand what I mean?"}]},"清楚":{"en":"clear; distinct","exs":[{"use":"Tính từ; 听清楚 / 看清楚: nghe / nhìn rõ (bổ ngữ kết quả).","ex":"这张照片很清楚。","py":"Zhè zhāng zhàopiàn hěn qīngchu.","vi":"Tấm ảnh này rất rõ nét.","en":"This photo is very clear."},{"use":"听清楚 / 看清楚.","ex":"我没听清楚你的名字。","py":"Wǒ méi tīng qīngchu nǐ de míngzi.","vi":"Tôi nghe chưa rõ tên bạn.","en":"I didn't catch your name clearly."},{"use":"弄清楚 / 说清楚: làm rõ / nói rõ.","ex":"这件事你一定要说清楚。","py":"Zhè jiàn shì nǐ yídìng yào shuō qīngchu.","vi":"Việc này nhất định bạn phải nói cho rõ.","en":"You must make this matter clear."}]},"特别":{"en":"especially; special","exs":[{"use":"特别 + tính từ: rất, vô cùng.","ex":"今天特别冷。","py":"Jīntiān tèbié lěng.","vi":"Hôm nay lạnh đặc biệt.","en":"It's especially cold today."},{"use":"特别 + 喜欢 / 想.","ex":"我特别喜欢吃北京烤鸭。","py":"Wǒ tèbié xǐhuan chī Běijīng kǎoyā.","vi":"Tôi đặc biệt thích ăn vịt quay Bắc Kinh.","en":"I especially love Peking duck."},{"use":"特别 (tính từ): đặc biệt, khác thường.","ex":"这是一个特别的礼物。","py":"Zhè shì yí ge tèbié de lǐwù.","vi":"Đây là một món quà đặc biệt.","en":"This is a special gift."}]},"突然":{"en":"suddenly","exs":[{"use":"Phó từ/tính từ: 突然 + động từ.","ex":"灯突然灭了。","py":"Dēng tūrán miè le.","vi":"Đèn đột nhiên tắt.","en":"The light suddenly went out."},{"use":"突然 + 想起来 / 发现.","ex":"我突然想起来今天有会议。","py":"Wǒ tūrán xiǎng qǐlai jīntiān yǒu huìyì.","vi":"Tôi chợt nhớ hôm nay có cuộc họp.","en":"I suddenly remembered there's a meeting today."},{"use":"很突然: rất đột ngột.","ex":"这件事发生得很突然。","py":"Zhè jiàn shì fāshēng de hěn tūrán.","vi":"Việc này xảy ra rất đột ngột.","en":"This happened very suddenly."}]},"音乐":{"en":"music","exs":[{"use":"Danh từ.","ex":"我喜欢听轻松的音乐。","py":"Wǒ xǐhuan tīng qīngsōng de yīnyuè.","vi":"Tôi thích nghe nhạc nhẹ nhàng.","en":"I like listening to relaxing music."},{"use":"听音乐 / 音乐会.","ex":"周末我们去听音乐会吧。","py":"Zhōumò wǒmen qù tīng yīnyuèhuì ba.","vi":"Cuối tuần chúng ta đi nghe hòa nhạc nhé.","en":"Let's go to a concert this weekend."},{"use":"对音乐感兴趣.","ex":"他对音乐很感兴趣。","py":"Tā duì yīnyuè hěn gǎn xìngqù.","vi":"Anh ấy rất hứng thú với âm nhạc.","en":"He is very interested in music."}]},"睡着":{"en":"to fall asleep","exs":[{"use":"睡着 = 睡 + 着 (bổ ngữ kết quả: đã vào giấc ngủ).","ex":"他看着电视就睡着了。","py":"Tā kàn zhe diànshì jiù shuì zháo le.","vi":"Anh ấy vừa xem tivi vừa ngủ thiếp đi.","en":"He fell asleep watching TV."},{"use":"睡不着: không ngủ được.","ex":"外面太吵了，我睡不着。","py":"Wàimiàn tài chǎo le, wǒ shuì bù zháo.","vi":"Bên ngoài ồn quá, tôi không ngủ được.","en":"It's too noisy outside; I can't fall asleep."},{"use":"很快就睡着了.","ex":"孩子听着音乐，很快就睡着了。","py":"Háizi tīng zhe yīnyuè, hěn kuài jiù shuì zháo le.","vi":"Đứa trẻ vừa nghe nhạc vừa nhanh chóng ngủ thiếp đi.","en":"The child fell asleep quickly listening to music."}]},"眼镜":{"en":"glasses","exs":[{"use":"Danh từ; lượng từ: 副.","ex":"我的眼镜找不到了。","py":"Wǒ de yǎnjìng zhǎo bú dào le.","vi":"Tôi không tìm thấy kính của mình.","en":"I can't find my glasses."},{"use":"戴眼镜: đeo kính.","ex":"他戴着一副黑色的眼镜。","py":"Tā dài zhe yí fù hēisè de yǎnjìng.","vi":"Anh ấy đeo một cặp kính màu đen.","en":"He wears a pair of black glasses."},{"use":"配眼镜 / 买眼镜.","ex":"我明天去配一副新眼镜。","py":"Wǒ míngtiān qù pèi yí fù xīn yǎnjìng.","vi":"Mai tôi đi làm một cặp kính mới.","en":"I'm getting new glasses made tomorrow."}]},"半":{"en":"half","exs":[{"use":"半 + lượng từ: một nửa; 点半: …giờ rưỡi.","ex":"现在是三点半。","py":"Xiànzài shì sān diǎn bàn.","vi":"Bây giờ là ba giờ rưỡi.","en":"It's half past three now."},{"use":"一半 / 半个月.","ex":"我吃了一半，剩下的给你。","py":"Wǒ chī le yíbàn, shèngxià de gěi nǐ.","vi":"Tôi ăn một nửa, phần còn lại cho bạn.","en":"I ate half; the rest is for you."},{"use":"一个半小时: một tiếng rưỡi.","ex":"从这里到机场要一个半小时。","py":"Cóng zhèlǐ dào jīchǎng yào yí ge bàn xiǎoshí.","vi":"Từ đây đến sân bay mất một tiếng rưỡi.","en":"It takes an hour and a half to get to the airport."}]},"差":{"en":"to be short of; poor","exs":[{"use":"差 + số lượng: còn thiếu; chỉ giờ: 差五分八点.","ex":"现在差十分八点。","py":"Xiànzài chà shí fēn bā diǎn.","vi":"Bây giờ còn mười phút nữa là tám giờ.","en":"It's ten to eight now."},{"use":"差 + 一点儿: thiếu một chút.","ex":"我差一点儿迟到。","py":"Wǒ chà yìdiǎnr chídào.","vi":"Tôi suýt nữa thì đến muộn.","en":"I almost got there late."},{"use":"差 (tính từ): kém, tệ.","ex":"他的成绩不太差。","py":"Tā de chéngjì bú tài chà.","vi":"Điểm của anh ấy không đến nỗi kém.","en":"His grades aren't too bad."}]},"迟到":{"en":"to be late","exs":[{"use":"Động từ: 迟到 + 了; không cần tân ngữ.","ex":"对不起，我迟到了。","py":"Duìbuqǐ, wǒ chídào le.","vi":"Xin lỗi, tôi đến muộn.","en":"Sorry, I'm late."},{"use":"上课迟到 / 上班迟到.","ex":"他上班常常迟到。","py":"Tā shàngbān chángcháng chídào.","vi":"Anh ấy đi làm hay bị muộn.","en":"He is often late for work."},{"use":"迟到 + 十分钟.","ex":"火车迟到了十分钟。","py":"Huǒchē chídào le shí fēnzhōng.","vi":"Tàu đến muộn mười phút.","en":"The train was ten minutes late."}]},"感兴趣":{"en":"to be interested in","exs":[{"use":"对 + danh từ + 感兴趣: hứng thú với…","ex":"我对历史很感兴趣。","py":"Wǒ duì lìshǐ hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với lịch sử.","en":"I'm very interested in history."},{"use":"不感兴趣: không hứng thú.","ex":"他对足球不感兴趣。","py":"Tā duì zúqiú bù gǎn xìngqù.","vi":"Anh ấy không hứng thú với bóng đá.","en":"He isn't interested in football."},{"use":"对什么感兴趣: hứng thú với gì.","ex":"你对什么感兴趣？","py":"Nǐ duì shénme gǎn xìngqù?","vi":"Bạn hứng thú với điều gì?","en":"What are you interested in?"}]},"欢迎":{"en":"to welcome","exs":[{"use":"欢迎 + người: chào đón ai.","ex":"欢迎你来我们公司。","py":"Huānyíng nǐ lái wǒmen gōngsī.","vi":"Chào mừng bạn đến công ty chúng tôi.","en":"Welcome to our company."},{"use":"欢迎光临: kính chào quý khách.","ex":"欢迎光临，请问几位？","py":"Huānyíng guānglín, qǐngwèn jǐ wèi?","vi":"Kính chào quý khách, xin hỏi mấy vị ạ?","en":"Welcome! How many are in your party?"},{"use":"受欢迎: được hoan nghênh.","ex":"这位老师很受学生欢迎。","py":"Zhè wèi lǎoshī hěn shòu xuésheng huānyíng.","vi":"Thầy giáo này rất được học sinh yêu mến.","en":"This teacher is very popular with students."}]},"接":{"en":"to pick up; to meet; to answer (a call)","exs":[{"use":"接 + người: đón ai.","ex":"我去机场接朋友。","py":"Wǒ qù jīchǎng jiē péngyou.","vi":"Tôi ra sân bay đón bạn.","en":"I'm going to the airport to pick up a friend."},{"use":"接电话: nghe điện thoại.","ex":"他正在开会，没接电话。","py":"Tā zhèngzài kāihuì, méi jiē diànhuà.","vi":"Anh ấy đang họp nên không nghe máy.","en":"He's in a meeting and didn't answer the phone."},{"use":"接孩子: đón con.","ex":"妈妈每天去学校接孩子。","py":"Māma měitiān qù xuéxiào jiē háizi.","vi":"Mỗi ngày mẹ đến trường đón con.","en":"Mom picks the child up from school every day."}]},"结婚":{"en":"to get married","exs":[{"use":"Động từ ly hợp: 结 + 婚; 跟 + người + 结婚.","ex":"他们明年打算结婚。","py":"Tāmen míngnián dǎsuàn jié hūn.","vi":"Sang năm họ định kết hôn.","en":"They plan to get married next year."},{"use":"跟 + 人 + 结婚.","ex":"她跟大学同学结婚了。","py":"Tā gēn dàxué tóngxué jié hūn le.","vi":"Cô ấy kết hôn với bạn đại học.","en":"She married her college classmate."},{"use":"结过婚: đã từng kết hôn.","ex":"你结婚了吗？","py":"Nǐ jié hūn le ma?","vi":"Bạn kết hôn chưa?","en":"Are you married?"}]},"久":{"en":"for a long time","exs":[{"use":"Tính từ/phó từ chỉ thời gian dài.","ex":"好久不见！","py":"Hǎojiǔ bú jiàn!","vi":"Lâu rồi không gặp!","en":"Long time no see!"},{"use":"多久: bao lâu.","ex":"你在这儿住了多久？","py":"Nǐ zài zhèr zhù le duō jiǔ?","vi":"Bạn sống ở đây bao lâu rồi?","en":"How long have you lived here?"},{"use":"不久: không lâu.","ex":"他来北京不久。","py":"Tā lái Běijīng bù jiǔ.","vi":"Anh ấy đến Bắc Kinh chưa lâu.","en":"He hasn't been in Beijing long."}]},"刻":{"en":"quarter of an hour","exs":[{"use":"一刻 = 15 phút; 三刻 = 45 phút.","ex":"现在是八点一刻。","py":"Xiànzài shì bā diǎn yí kè.","vi":"Bây giờ là tám giờ mười lăm.","en":"It's a quarter past eight."},{"use":"差一刻 + giờ: kém 15 phút.","ex":"差一刻九点，我们走吧。","py":"Chà yí kè jiǔ diǎn, wǒmen zǒu ba.","vi":"Chín giờ kém mười lăm rồi, chúng ta đi thôi.","en":"It's a quarter to nine; let's go."},{"use":"三刻: 45 phút.","ex":"会议九点三刻开始。","py":"Huìyì jiǔ diǎn sān kè kāishǐ.","vi":"Cuộc họp bắt đầu lúc chín giờ bốn mươi lăm.","en":"The meeting starts at 9:45."}]},"同事":{"en":"colleague","exs":[{"use":"Danh từ chỉ người làm cùng cơ quan.","ex":"他是我的同事。","py":"Tā shì wǒ de tóngshì.","vi":"Anh ấy là đồng nghiệp của tôi.","en":"He is my colleague."},{"use":"跟同事 + động từ.","ex":"我跟同事一起去吃午饭。","py":"Wǒ gēn tóngshì yìqǐ qù chī wǔfàn.","vi":"Tôi đi ăn trưa cùng đồng nghiệp.","en":"I go to lunch with my colleagues."},{"use":"老同事 / 新同事.","ex":"我们公司来了一位新同事。","py":"Wǒmen gōngsī lái le yí wèi xīn tóngshì.","vi":"Công ty chúng tôi có thêm một đồng nghiệp mới.","en":"A new colleague has joined our company."}]},"以前":{"en":"before; in the past","exs":[{"use":"以前 + (câu): trước đây. 动词 + 以前: trước khi…","ex":"以前我不喜欢喝茶。","py":"Yǐqián wǒ bù xǐhuan hē chá.","vi":"Trước đây tôi không thích uống trà.","en":"I didn't like tea before."},{"use":"三年以前: ba năm trước.","ex":"三年以前我在上海工作。","py":"Sān nián yǐqián wǒ zài Shànghǎi gōngzuò.","vi":"Ba năm trước tôi làm việc ở Thượng Hải.","en":"Three years ago I worked in Shanghai."},{"use":"睡觉以前: trước khi ngủ.","ex":"睡觉以前我喜欢看书。","py":"Shuìjiào yǐqián wǒ xǐhuan kàn shū.","vi":"Trước khi ngủ tôi thích đọc sách.","en":"I like to read before bed."}]},"银行":{"en":"bank","exs":[{"use":"Danh từ chỉ nơi gửi, rút tiền.","ex":"银行在超市的旁边。","py":"Yínháng zài chāoshì de pángbiān.","vi":"Ngân hàng nằm cạnh siêu thị.","en":"The bank is next to the supermarket."},{"use":"去银行 + 取钱 / 存钱.","ex":"我下午要去银行取钱。","py":"Wǒ xiàwǔ yào qù yínháng qǔ qián.","vi":"Chiều nay tôi phải đến ngân hàng rút tiền.","en":"I need to withdraw money at the bank this afternoon."},{"use":"在银行工作.","ex":"她姐姐在银行工作。","py":"Tā jiějie zài yínháng gōngzuò.","vi":"Chị gái cô ấy làm việc ở ngân hàng.","en":"Her older sister works at a bank."}]},"安静":{"en":"quiet","exs":[{"use":"Tính từ chỉ nơi chốn hoặc người yên lặng.","ex":"图书馆里很安静。","py":"Túshūguǎn lǐ hěn ānjìng.","vi":"Trong thư viện rất yên tĩnh.","en":"It's very quiet in the library."},{"use":"请安静! : xin giữ yên lặng.","ex":"请大家安静一下。","py":"Qǐng dàjiā ānjìng yíxià.","vi":"Xin mọi người giữ yên lặng một chút.","en":"Everyone, please be quiet for a moment."},{"use":"安静 + 地 + động từ.","ex":"孩子安静地坐在椅子上。","py":"Háizi ānjìng de zuò zài yǐzi shàng.","vi":"Đứa trẻ yên lặng ngồi trên ghế.","en":"The child sits quietly on the chair."}]},"变化":{"en":"to change; change","exs":[{"use":"Động từ/danh từ; 变化 + 很大: thay đổi lớn.","ex":"这座城市的变化很大。","py":"Zhè zuò chéngshì de biànhuà hěn dà.","vi":"Thành phố này thay đổi rất nhiều.","en":"This city has changed a lot."},{"use":"发生变化: xảy ra thay đổi.","ex":"他的生活发生了很大的变化。","py":"Tā de shēnghuó fāshēng le hěn dà de biànhuà.","vi":"Cuộc sống của anh ấy đã có thay đổi lớn.","en":"His life has changed greatly."},{"use":"变化 + 得 + 很快.","ex":"天气变化得很快。","py":"Tiānqì biànhuà de hěn kuài.","vi":"Thời tiết thay đổi rất nhanh.","en":"The weather changes quickly."}]},"层":{"en":"floor; storey (measure word)","exs":[{"use":"数字 + 层: tầng thứ mấy / bao nhiêu tầng.","ex":"这座楼一共有三十层。","py":"Zhè zuò lóu yígòng yǒu sānshí céng.","vi":"Tòa nhà này có tất cả ba mươi tầng.","en":"This building has thirty floors in total."},{"use":"第几层: tầng thứ mấy.","ex":"你的办公室在第几层？","py":"Nǐ de bàngōngshì zài dì jǐ céng?","vi":"Văn phòng bạn ở tầng mấy?","en":"Which floor is your office on?"},{"use":"一层 / 二层: tầng 1 / tầng 2.","ex":"饭馆在二层。","py":"Fànguǎn zài èr céng.","vi":"Quán ăn ở tầng hai.","en":"The restaurant is on the second floor."}]},"电梯":{"en":"elevator; lift","exs":[{"use":"Danh từ; 坐电梯: đi thang máy.","ex":"我们坐电梯上去吧。","py":"Wǒmen zuò diàntī shàngqu ba.","vi":"Chúng ta đi thang máy lên nhé.","en":"Let's take the elevator up."},{"use":"等电梯: đợi thang máy.","ex":"电梯前站着很多人。","py":"Diàntī qián zhàn zhe hěn duō rén.","vi":"Trước thang máy có nhiều người đứng.","en":"Many people are standing in front of the elevator."},{"use":"电梯 + 坏了.","ex":"电梯坏了，我们只好走楼梯。","py":"Diàntī huài le, wǒmen zhǐhǎo zǒu lóutī.","vi":"Thang máy hỏng, chúng tôi đành đi cầu thang.","en":"The elevator is broken, so we have to take the stairs."}]},"害怕":{"en":"to be afraid","exs":[{"use":"害怕 + 名词/动词: sợ gì / sợ làm gì.","ex":"我很害怕黑暗。","py":"Wǒ hěn hàipà hēi'àn.","vi":"Tôi rất sợ bóng tối.","en":"I'm very afraid of the dark."},{"use":"害怕 + 动词: ngại, sợ làm gì.","ex":"他害怕在很多人面前说话。","py":"Tā hàipà zài hěn duō rén miànqián shuōhuà.","vi":"Anh ấy sợ nói trước nhiều người.","en":"He's afraid of speaking in front of many people."},{"use":"别害怕: đừng sợ.","ex":"别害怕，我陪着你。","py":"Bié hàipà, wǒ péi zhe nǐ.","vi":"Đừng sợ, tôi ở bên bạn.","en":"Don't be afraid; I'm here with you."}]},"几乎":{"en":"almost; nearly","exs":[{"use":"几乎 + động từ/ phủ định: gần như.","ex":"他几乎每天都去锻炼。","py":"Tā jīhū měitiān dōu qù duànliàn.","vi":"Anh ấy gần như ngày nào cũng đi tập.","en":"He works out almost every day."},{"use":"几乎 + 没 / 不: hầu như không.","ex":"这里几乎没有人。","py":"Zhèlǐ jīhū méiyǒu rén.","vi":"Ở đây gần như không có ai.","en":"There's almost nobody here."},{"use":"几乎 + 一样.","ex":"这两个字几乎一样。","py":"Zhè liǎng ge zì jīhū yíyàng.","vi":"Hai chữ này gần như giống hệt nhau.","en":"These two characters are almost identical."}]},"见面":{"en":"to meet (face to face)","exs":[{"use":"Động từ ly hợp: 见 + 面; 跟 + người + 见面.","ex":"我们明天下午见面吧。","py":"Wǒmen míngtiān xiàwǔ jiàn miàn ba.","vi":"Chiều mai chúng ta gặp nhau nhé.","en":"Let's meet tomorrow afternoon."},{"use":"跟 + 人 + 见面.","ex":"我下周跟老同学见面。","py":"Wǒ xià zhōu gēn lǎo tóngxué jiàn miàn.","vi":"Tuần sau tôi gặp bạn học cũ.","en":"I'm meeting an old classmate next week."},{"use":"见过面 / 没见过面.","ex":"我们好久没见面了。","py":"Wǒmen hǎojiǔ méi jiàn miàn le.","vi":"Chúng ta lâu rồi chưa gặp nhau.","en":"We haven't met for a long time."}]},"健康":{"en":"healthy; health","exs":[{"use":"Tính từ/danh từ: sức khỏe.","ex":"他的身体很健康。","py":"Tā de shēntǐ hěn jiànkāng.","vi":"Cơ thể anh ấy rất khỏe mạnh.","en":"He is in very good health."},{"use":"对健康 + 好: tốt cho sức khỏe.","ex":"早睡早起对健康有好处。","py":"Zǎo shuì zǎo qǐ duì jiànkāng yǒu hǎochu.","vi":"Ngủ sớm dậy sớm có lợi cho sức khỏe.","en":"Going to bed and rising early is good for your health."},{"use":"健康 + 的 + 生活.","ex":"他过着健康的生活。","py":"Tā guò zhe jiànkāng de shēnghuó.","vi":"Anh ấy sống một cuộc sống lành mạnh.","en":"He leads a healthy life."}]},"老":{"en":"old; of long standing","exs":[{"use":"Tính từ: già. 老 + họ: gọi thân mật (老王).","ex":"他爷爷已经很老了。","py":"Tā yéye yǐjīng hěn lǎo le.","vi":"Ông của anh ấy đã rất già.","en":"His grandfather is already very old."},{"use":"老 + 朋友 / 同学: bạn cũ.","ex":"我们是老朋友了。","py":"Wǒmen shì lǎo péngyou le.","vi":"Chúng tôi là bạn lâu năm rồi.","en":"We are old friends."},{"use":"老 + 是: luôn luôn (khẩu ngữ).","ex":"他老是忘记带钥匙。","py":"Tā lǎoshì wàngjì dài yàoshi.","vi":"Anh ấy cứ hay quên mang chìa khóa.","en":"He is always forgetting his keys."}]},"马上":{"en":"immediately; right away","exs":[{"use":"马上 + 就 / 要 + động từ: sắp, ngay lập tức.","ex":"你等一下，我马上来。","py":"Nǐ děng yíxià, wǒ mǎshàng lái.","vi":"Bạn đợi chút, tôi đến ngay.","en":"Wait a moment; I'll be right there."},{"use":"马上就 + 要 + ……了.","ex":"飞机马上就要起飞了。","py":"Fēijī mǎshàng jiù yào qǐfēi le.","vi":"Máy bay sắp cất cánh rồi.","en":"The plane is about to take off."},{"use":"马上 + 回答 / 出发.","ex":"请马上回答我。","py":"Qǐng mǎshàng huídá wǒ.","vi":"Xin hãy trả lời tôi ngay.","en":"Please answer me right away."}]},"满意":{"en":"satisfied","exs":[{"use":"对 + danh từ + 满意: hài lòng với…","ex":"我对这家饭馆很满意。","py":"Wǒ duì zhè jiā fànguǎn hěn mǎnyì.","vi":"Tôi rất hài lòng với quán ăn này.","en":"I'm very satisfied with this restaurant."},{"use":"不满意: không hài lòng.","ex":"经理对我的工作不太满意。","py":"Jīnglǐ duì wǒ de gōngzuò bú tài mǎnyì.","vi":"Giám đốc không hài lòng lắm với công việc của tôi.","en":"The manager isn't very satisfied with my work."},{"use":"满意 + 的 + 答案.","ex":"我终于得到了满意的回答。","py":"Wǒ zhōngyú dédào le mǎnyì de huídá.","vi":"Cuối cùng tôi cũng nhận được câu trả lời thỏa đáng.","en":"I finally got a satisfactory answer."}]},"洗手间":{"en":"restroom; bathroom","exs":[{"use":"Danh từ: cách nói lịch sự của nhà vệ sinh.","ex":"请问，洗手间在哪儿？","py":"Qǐngwèn, xǐshǒujiān zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu ạ?","en":"Excuse me, where is the restroom?"},{"use":"去洗手间.","ex":"我去一下洗手间。","py":"Wǒ qù yíxià xǐshǒujiān.","vi":"Tôi đi nhà vệ sinh một lát.","en":"I'm going to the restroom for a moment."},{"use":"洗手间 + 在 + 楼上.","ex":"洗手间在二楼，电梯旁边。","py":"Xǐshǒujiān zài èr lóu, diàntī pángbiān.","vi":"Nhà vệ sinh ở tầng hai, cạnh thang máy.","en":"The restroom is on the second floor, next to the elevator."}]},"熊猫":{"en":"panda","exs":[{"use":"Danh từ chỉ gấu trúc, quốc bảo Trung Quốc.","ex":"我想去看大熊猫。","py":"Wǒ xiǎng qù kàn dà xióngmāo.","vi":"Tôi muốn đi xem gấu trúc.","en":"I want to go see the giant panda."},{"use":"熊猫 + 爱吃 + 竹子.","ex":"熊猫最爱吃竹子。","py":"Xióngmāo zuì ài chī zhúzi.","vi":"Gấu trúc thích ăn tre nhất.","en":"Pandas love eating bamboo most."},{"use":"可爱的熊猫.","ex":"那只小熊猫真可爱。","py":"Nà zhī xiǎo xióngmāo zhēn kě'ài.","vi":"Chú gấu trúc nhỏ kia dễ thương thật.","en":"That little panda is so cute."}]},"一会儿":{"en":"a moment; a little while","exs":[{"use":"一会儿 + 就 + động từ: lát nữa sẽ…","ex":"你先坐一会儿，经理马上来。","py":"Nǐ xiān zuò yíhuìr, jīnglǐ mǎshàng lái.","vi":"Bạn ngồi một lát, giám đốc đến ngay.","en":"Sit for a moment; the manager will be here soon."},{"use":"过一会儿: một lát sau.","ex":"过一会儿再给我打电话吧。","py":"Guò yíhuìr zài gěi wǒ dǎ diànhuà ba.","vi":"Lát nữa hãy gọi cho tôi nhé.","en":"Call me again in a while."},{"use":"休息一会儿.","ex":"我们休息一会儿再走。","py":"Wǒmen xiūxi yíhuìr zài zǒu.","vi":"Chúng ta nghỉ một lát rồi hãy đi.","en":"Let's rest a moment before leaving."}]},"重要":{"en":"important","exs":[{"use":"Tính từ; 重要 + 的 + danh từ.","ex":"这是一件很重要的事。","py":"Zhè shì yí jiàn hěn zhòngyào de shì.","vi":"Đây là một việc rất quan trọng.","en":"This is a very important matter."},{"use":"对 + 人 + 来说 + 重要.","ex":"健康对每个人都很重要。","py":"Jiànkāng duì měi ge rén dōu hěn zhòngyào.","vi":"Sức khỏe quan trọng với mọi người.","en":"Health is important to everyone."},{"use":"最重要的是 + ……: điều quan trọng nhất là…","ex":"最重要的是别着急。","py":"Zuì zhòngyào de shì bié zháojí.","vi":"Điều quan trọng nhất là đừng nóng vội.","en":"The most important thing is not to rush."}]},"可乐":{"en":"cola","exs":[{"use":"Danh từ chỉ nước ngọt có ga.","ex":"我想喝一杯可乐。","py":"Wǒ xiǎng hē yì bēi kělè.","vi":"Tôi muốn uống một cốc cola.","en":"I'd like a glass of cola."},{"use":"一瓶可乐.","ex":"冰箱里还有两瓶可乐。","py":"Bīngxiāng lǐ hái yǒu liǎng píng kělè.","vi":"Trong tủ lạnh còn hai chai cola.","en":"There are still two bottles of cola in the fridge."},{"use":"可乐 + 太甜.","ex":"可乐太甜了，我喝不了太多。","py":"Kělè tài tián le, wǒ hē bù liǎo tài duō.","vi":"Cola ngọt quá, tôi không uống được nhiều.","en":"Cola is too sweet; I can't drink much."}]},"班":{"en":"class; shift","exs":[{"use":"班: lớp học. 上班 / 下班: đi làm / tan làm.","ex":"我们班有二十个学生。","py":"Wǒmen bān yǒu èrshí ge xuésheng.","vi":"Lớp chúng tôi có hai mươi học sinh.","en":"There are twenty students in our class."},{"use":"同班同学: bạn cùng lớp.","ex":"他是我的同班同学。","py":"Tā shì wǒ de tóng bān tóngxué.","vi":"Anh ấy là bạn cùng lớp của tôi.","en":"He is my classmate."},{"use":"班 + 老师 / 同学.","ex":"我们班的老师很年轻。","py":"Wǒmen bān de lǎoshī hěn niánqīng.","vi":"Cô giáo lớp chúng tôi rất trẻ.","en":"Our class teacher is very young."}]},"比较":{"en":"fairly; rather; to compare","exs":[{"use":"比较 + tính từ: khá là…","ex":"这个房间比较大。","py":"Zhège fángjiān bǐjiào dà.","vi":"Căn phòng này khá rộng.","en":"This room is fairly large."},{"use":"比较 + 喜欢 / 想.","ex":"我比较喜欢安静的地方。","py":"Wǒ bǐjiào xǐhuan ānjìng de dìfang.","vi":"Tôi khá thích nơi yên tĩnh.","en":"I rather like quiet places."},{"use":"比较 (động từ): so sánh.","ex":"请比较一下这两个句子。","py":"Qǐng bǐjiào yíxià zhè liǎng ge jùzi.","vi":"Hãy so sánh hai câu này.","en":"Please compare these two sentences."}]},"参加":{"en":"to take part in","exs":[{"use":"参加 + hoạt động: tham gia.","ex":"你参加明天的会议吗？","py":"Nǐ cānjiā míngtiān de huìyì ma?","vi":"Bạn có tham gia cuộc họp ngày mai không?","en":"Will you attend tomorrow's meeting?"},{"use":"参加 + 比赛 / 考试 / 活动.","ex":"他参加了汉语考试。","py":"Tā cānjiā le Hànyǔ kǎoshì.","vi":"Anh ấy đã dự kỳ thi tiếng Hán.","en":"He took the Chinese exam."},{"use":"参加过: đã từng tham gia.","ex":"我参加过两次这样的比赛。","py":"Wǒ cānjiā guo liǎng cì zhèyàng de bǐsài.","vi":"Tôi đã tham gia hai lần cuộc thi như thế.","en":"I've entered this kind of contest twice."}]},"担心":{"en":"to worry","exs":[{"use":"Động từ ly hợp: 担 + 心; 担心 + người/việc.","ex":"妈妈很担心我的身体。","py":"Māma hěn dānxīn wǒ de shēntǐ.","vi":"Mẹ rất lo cho sức khỏe của tôi.","en":"Mom worries a lot about my health."},{"use":"别担心: đừng lo.","ex":"别担心，一切都会好的。","py":"Bié dānxīn, yíqiè dōu huì hǎo de.","vi":"Đừng lo, mọi việc sẽ ổn thôi.","en":"Don't worry; everything will be fine."},{"use":"担心 + 会 + ……: lo rằng sẽ…","ex":"我担心他会迟到。","py":"Wǒ dānxīn tā huì chídào.","vi":"Tôi lo anh ấy sẽ đến muộn.","en":"I'm afraid he'll be late."}]},"放心":{"en":"to rest assured","exs":[{"use":"Động từ ly hợp; trái nghĩa 担心.","ex":"你放心，我会照顾好孩子。","py":"Nǐ fàngxīn, wǒ huì zhàogù hǎo háizi.","vi":"Bạn yên tâm, tôi sẽ chăm sóc con thật tốt.","en":"Don't worry; I'll take good care of the child."},{"use":"不放心: không yên tâm.","ex":"他一个人去，我不放心。","py":"Tā yí ge rén qù, wǒ bú fàngxīn.","vi":"Anh ấy đi một mình, tôi không yên tâm.","en":"I'm uneasy about him going alone."},{"use":"放心吧: cứ yên tâm.","ex":"放心吧，我不会忘的。","py":"Fàngxīn ba, wǒ bú huì wàng de.","vi":"Cứ yên tâm, tôi sẽ không quên đâu.","en":"Rest assured; I won't forget."}]},"了解":{"en":"to know well; to understand","exs":[{"use":"了解 + người/việc: hiểu rõ về…","ex":"我不太了解这个城市。","py":"Wǒ bú tài liǎojiě zhège chéngshì.","vi":"Tôi không hiểu rõ thành phố này lắm.","en":"I don't know this city very well."},{"use":"了解 + 情况 / 文化.","ex":"他想多了解中国文化。","py":"Tā xiǎng duō liǎojiě Zhōngguó wénhuà.","vi":"Anh ấy muốn tìm hiểu thêm về văn hóa Trung Quốc.","en":"He wants to learn more about Chinese culture."},{"use":"互相了解: hiểu nhau.","ex":"我们认识很久了，很了解对方。","py":"Wǒmen rènshi hěn jiǔ le, hěn liǎojiě duìfāng.","vi":"Chúng tôi quen nhau lâu, rất hiểu nhau.","en":"We've known each other for ages and understand each other well."}]},"先":{"en":"first; in advance","exs":[{"use":"先 + động từ, 再/然后 + động từ: làm trước, sau đó…","ex":"你先吃饭，再做作业。","py":"Nǐ xiān chīfàn, zài zuò zuòyè.","vi":"Bạn ăn cơm trước rồi hãy làm bài tập.","en":"Eat first, then do your homework."},{"use":"我先 + 走 / 去: tôi đi trước.","ex":"我还有事，先走了。","py":"Wǒ hái yǒu shì, xiān zǒu le.","vi":"Tôi còn việc nên đi trước nhé.","en":"I have something to do, so I'll go first."},{"use":"先 + 说 + 好.","ex":"我们先说好时间。","py":"Wǒmen xiān shuō hǎo shíjiān.","vi":"Chúng ta hãy chốt thời gian trước.","en":"Let's settle the time first."}]},"一定":{"en":"definitely; certainly","exs":[{"use":"一定 + 会/要 + động từ: chắc chắn sẽ…","ex":"明天我一定来。","py":"Míngtiān wǒ yídìng lái.","vi":"Ngày mai tôi nhất định sẽ đến.","en":"I'll definitely come tomorrow."},{"use":"不一定: chưa chắc.","ex":"他不一定知道这件事。","py":"Tā bù yídìng zhīdào zhè jiàn shì.","vi":"Chưa chắc anh ấy đã biết chuyện này.","en":"He doesn't necessarily know about this."},{"use":"一定 + 要 + 动词: nhất định phải.","ex":"开车一定要小心。","py":"Kāichē yídìng yào xiǎoxīn.","vi":"Lái xe nhất định phải cẩn thận.","en":"You must be careful when driving."}]},"一样":{"en":"the same; as … as","exs":[{"use":"A 跟/和 B 一样: A giống B.","ex":"我的手机跟你的一样。","py":"Wǒ de shǒujī gēn nǐ de yíyàng.","vi":"Điện thoại của tôi giống của bạn.","en":"My phone is the same as yours."},{"use":"一样 + tính từ: ngang nhau.","ex":"他跟哥哥一样高。","py":"Tā gēn gēge yíyàng gāo.","vi":"Anh ấy cao bằng anh trai.","en":"He is as tall as his older brother."},{"use":"不一样: khác nhau.","ex":"这两个地方不一样。","py":"Zhè liǎng ge dìfang bù yíyàng.","vi":"Hai nơi này không giống nhau.","en":"These two places are different."}]},"影响":{"en":"influence; to affect","exs":[{"use":"Danh từ/động từ: 对 + …… + 有影响.","ex":"天气会影响我们的计划。","py":"Tiānqì huì yǐngxiǎng wǒmen de jìhuà.","vi":"Thời tiết sẽ ảnh hưởng đến kế hoạch của chúng ta.","en":"The weather will affect our plans."},{"use":"对 + 人 + 有影响.","ex":"朋友对他的影响很大。","py":"Péngyou duì tā de yǐngxiǎng hěn dà.","vi":"Bạn bè có ảnh hưởng rất lớn đến anh ấy.","en":"Friends have a great influence on him."},{"use":"受影响: chịu ảnh hưởng.","ex":"他的学习没有受到影响。","py":"Tā de xuéxí méiyǒu shòudào yǐngxiǎng.","vi":"Việc học của anh ấy không bị ảnh hưởng.","en":"His studies haven't been affected."}]},"中间":{"en":"middle; between","exs":[{"use":"Danh từ chỉ vị trí: 在……中间.","ex":"他坐在我和小明中间。","py":"Tā zuò zài wǒ hé Xiǎomíng zhōngjiān.","vi":"Anh ấy ngồi giữa tôi và Tiểu Minh.","en":"He sits between me and Xiaoming."},{"use":"中间 + 的 + danh từ.","ex":"请把中间的椅子搬走。","py":"Qǐng bǎ zhōngjiān de yǐzi bān zǒu.","vi":"Hãy bê chiếc ghế ở giữa đi.","en":"Please move away the chair in the middle."},{"use":"路中间: giữa đường.","ex":"别站在路中间。","py":"Bié zhàn zài lù zhōngjiān.","vi":"Đừng đứng giữa đường.","en":"Don't stand in the middle of the road."}]},"最后":{"en":"finally; last","exs":[{"use":"最后 + (câu): cuối cùng (thứ tự thời gian).","ex":"最后他们还是同意了。","py":"Zuìhòu tāmen háishi tóngyì le.","vi":"Cuối cùng họ vẫn đồng ý.","en":"In the end, they agreed."},{"use":"最后一 + 个/次: cái/lần cuối cùng.","ex":"这是最后一次机会。","py":"Zhè shì zuìhòu yí cì jīhuì.","vi":"Đây là cơ hội cuối cùng.","en":"This is the last chance."},{"use":"先……，然后……，最后……: trước…, sau đó…, cuối cùng…","ex":"先洗手，然后吃饭，最后喝汤。","py":"Xiān xǐ shǒu, ránhòu chīfàn, zuìhòu hē tāng.","vi":"Trước rửa tay, sau đó ăn cơm, cuối cùng uống canh.","en":"First wash your hands, then eat, and finally have soup."}]},"矮":{"en":"short (of height)","exs":[{"use":"Tính từ miêu tả chiều cao người hoặc vật; trái nghĩa 高.","ex":"他比我矮一点儿。","py":"Tā bǐ wǒ ǎi yìdiǎnr.","vi":"Anh ấy thấp hơn tôi một chút.","en":"He is a little shorter than me."},{"use":"个子矮: dáng thấp.","ex":"她个子很矮，够不到书架。","py":"Tā gèzi hěn ǎi, gòu bú dào shūjià.","vi":"Cô ấy thấp nên với không tới giá sách.","en":"She is short and can't reach the bookshelf."},{"use":"矮 + 一点儿 / 多了.","ex":"这座楼比那座矮多了。","py":"Zhè zuò lóu bǐ nà zuò ǎi duō le.","vi":"Tòa nhà này thấp hơn tòa kia nhiều.","en":"This building is much lower than that one."}]},"地方":{"en":"place","exs":[{"use":"Danh từ chỉ nơi chốn; 地方 đọc nhẹ \"fang\".","ex":"这个地方很安静。","py":"Zhège dìfang hěn ānjìng.","vi":"Nơi này rất yên tĩnh.","en":"This place is very quiet."},{"use":"什么地方 / 好地方.","ex":"你想去什么地方玩儿？","py":"Nǐ xiǎng qù shénme dìfang wánr?","vi":"Bạn muốn đi chơi ở đâu?","en":"Where would you like to go?"},{"use":"有地方 / 没地方 + 动词.","ex":"这里没地方放行李。","py":"Zhèlǐ méi dìfang fàng xíngli.","vi":"Ở đây không có chỗ để hành lý.","en":"There's no room for luggage here."}]},"方便":{"en":"convenient","exs":[{"use":"Tính từ: 很方便 / 不方便.","ex":"这儿离地铁站很近，很方便。","py":"Zhèr lí dìtiě zhàn hěn jìn, hěn fāngbiàn.","vi":"Ở đây gần ga tàu điện, rất thuận tiện.","en":"It's close to the subway here, so it's convenient."},{"use":"方便 + 吗: có tiện không.","ex":"明天下午你方便吗？","py":"Míngtiān xiàwǔ nǐ fāngbiàn ma?","vi":"Chiều mai bạn có tiện không?","en":"Is tomorrow afternoon convenient for you?"},{"use":"为了方便……: để thuận tiện.","ex":"为了方便大家，我们开了一家新店。","py":"Wèile fāngbiàn dàjiā, wǒmen kāi le yì jiā xīn diàn.","vi":"Để thuận tiện cho mọi người, chúng tôi mở một cửa hàng mới.","en":"We opened a new shop for everyone's convenience."}]},"附近":{"en":"nearby; vicinity","exs":[{"use":"Danh từ chỉ nơi chốn: 附近 + 有…; 在……附近.","ex":"这附近有银行吗？","py":"Zhè fùjìn yǒu yínháng ma?","vi":"Gần đây có ngân hàng không?","en":"Is there a bank nearby?"},{"use":"学校附近: gần trường.","ex":"他住在学校附近。","py":"Tā zhù zài xuéxiào fùjìn.","vi":"Anh ấy sống gần trường.","en":"He lives near the school."},{"use":"附近 + 的 + danh từ.","ex":"我常去附近的公园散步。","py":"Wǒ cháng qù fùjìn de gōngyuán sànbù.","vi":"Tôi hay đi dạo ở công viên gần đây.","en":"I often walk in the nearby park."}]},"个子":{"en":"height; stature","exs":[{"use":"个子 + 高 / 矮: cao / thấp.","ex":"他个子很高。","py":"Tā gèzi hěn gāo.","vi":"Anh ấy cao lớn.","en":"He is tall."},{"use":"高个子 / 矮个子.","ex":"那个高个子是我们的老师。","py":"Nàge gāo gèzi shì wǒmen de lǎoshī.","vi":"Người cao kia là thầy giáo của chúng tôi.","en":"That tall man is our teacher."},{"use":"个子 + 比 + ……: so chiều cao.","ex":"弟弟的个子比我还高。","py":"Dìdi de gèzi bǐ wǒ hái gāo.","vi":"Em trai còn cao hơn tôi.","en":"My younger brother is even taller than I am."}]},"环境":{"en":"environment","exs":[{"use":"Danh từ: môi trường sống, làm việc.","ex":"这里的环境很好。","py":"Zhèlǐ de huánjìng hěn hǎo.","vi":"Môi trường ở đây rất tốt.","en":"The environment here is very good."},{"use":"保护环境: bảo vệ môi trường.","ex":"我们要保护环境。","py":"Wǒmen yào bǎohù huánjìng.","vi":"Chúng ta phải bảo vệ môi trường.","en":"We must protect the environment."},{"use":"学习环境 / 工作环境.","ex":"公司的工作环境很舒服。","py":"Gōngsī de gōngzuò huánjìng hěn shūfu.","vi":"Môi trường làm việc của công ty rất dễ chịu.","en":"The company's working environment is very comfortable."}]},"换":{"en":"to change; to exchange","exs":[{"use":"换 + danh từ: đổi cái gì (quần áo, tiền, chỗ…).","ex":"我想换一件大一点儿的。","py":"Wǒ xiǎng huàn yí jiàn dà yìdiǎnr de.","vi":"Tôi muốn đổi cái lớn hơn một chút.","en":"I'd like to change it for a bigger one."},{"use":"换衣服 / 换钱.","ex":"我去房间换件衣服。","py":"Wǒ qù fángjiān huàn jiàn yīfu.","vi":"Tôi vào phòng thay bộ đồ.","en":"I'll go and change clothes."},{"use":"换 + 成: đổi thành.","ex":"请把美元换成人民币。","py":"Qǐng bǎ měiyuán huàn chéng rénmínbì.","vi":"Hãy đổi đô la Mỹ sang nhân dân tệ.","en":"Please exchange US dollars into RMB."}]},"旧":{"en":"old; used","exs":[{"use":"Tính từ chỉ đồ vật cũ; trái nghĩa 新.","ex":"这辆自行车太旧了。","py":"Zhè liàng zìxíngchē tài jiù le.","vi":"Chiếc xe đạp này cũ quá.","en":"This bicycle is too old."},{"use":"旧 + 衣服 / 书.","ex":"他把旧衣服送给了朋友。","py":"Tā bǎ jiù yīfu sòng gěi le péngyou.","vi":"Anh ấy tặng quần áo cũ cho bạn.","en":"He gave his old clothes to a friend."},{"use":"新 vs 旧.","ex":"新的比旧的贵很多。","py":"Xīn de bǐ jiù de guì hěn duō.","vi":"Đồ mới đắt hơn đồ cũ nhiều.","en":"The new one is much more expensive than the old one."}]},"历史":{"en":"history","exs":[{"use":"Danh từ: môn học hoặc quá trình phát triển.","ex":"我对中国历史很感兴趣。","py":"Wǒ duì Zhōngguó lìshǐ hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với lịch sử Trung Quốc.","en":"I'm very interested in Chinese history."},{"use":"历史老师 / 历史书.","ex":"他是我们的历史老师。","py":"Tā shì wǒmen de lìshǐ lǎoshī.","vi":"Ông ấy là thầy dạy sử của chúng tôi.","en":"He is our history teacher."},{"use":"有……年的历史: có lịch sử… năm.","ex":"这所大学有一百年的历史。","py":"Zhè suǒ dàxué yǒu yì bǎi nián de lìshǐ.","vi":"Trường đại học này có lịch sử một trăm năm.","en":"This university has a hundred-year history."}]},"骑":{"en":"to ride","exs":[{"use":"骑 + xe/ngựa: đi bằng phương tiện ngồi dạng chân.","ex":"我每天骑自行车上班。","py":"Wǒ měitiān qí zìxíngchē shàngbān.","vi":"Mỗi ngày tôi đi làm bằng xe đạp.","en":"I cycle to work every day."},{"use":"骑马: cưỡi ngựa.","ex":"他会骑马吗？","py":"Tā huì qí mǎ ma?","vi":"Anh ấy biết cưỡi ngựa không?","en":"Can he ride a horse?"},{"use":"骑 + 得 + 很快.","ex":"她骑得很快。","py":"Tā qí de hěn kuài.","vi":"Cô ấy đạp rất nhanh.","en":"She rides very fast."}]},"数学":{"en":"mathematics","exs":[{"use":"Danh từ chỉ môn học.","ex":"我的数学不太好。","py":"Wǒ de shùxué bú tài hǎo.","vi":"Môn toán của tôi không giỏi lắm.","en":"I'm not very good at math."},{"use":"数学老师 / 数学题.","ex":"这道数学题太难了。","py":"Zhè dào shùxué tí tài nán le.","vi":"Bài toán này khó quá.","en":"This math problem is too hard."},{"use":"数学 + 比 + 历史 + 难.","ex":"我觉得数学比历史难多了。","py":"Wǒ juéde shùxué bǐ lìshǐ nán duō le.","vi":"Tôi thấy toán khó hơn sử nhiều.","en":"I think math is much harder than history."}]},"体育":{"en":"sports; physical education","exs":[{"use":"Danh từ: môn thể dục, hoạt động thể thao.","ex":"他最喜欢上体育课。","py":"Tā zuì xǐhuan shàng tǐyù kè.","vi":"Anh ấy thích học giờ thể dục nhất.","en":"He likes P.E. class best."},{"use":"体育 + 馆 / 老师.","ex":"体育馆里有很多人。","py":"Tǐyùguǎn lǐ yǒu hěn duō rén.","vi":"Trong nhà thi đấu có rất nhiều người.","en":"There are many people in the gym."},{"use":"爱好体育: yêu thể thao.","ex":"我弟弟很爱好体育。","py":"Wǒ dìdi hěn àihào tǐyù.","vi":"Em trai tôi rất yêu thể thao.","en":"My younger brother loves sports."}]},"主要":{"en":"main; major","exs":[{"use":"Tính từ: 主要 + danh từ; hoặc phó từ 主要是….","ex":"这是最主要的问题。","py":"Zhè shì zuì zhǔyào de wèntí.","vi":"Đây là vấn đề chủ yếu nhất.","en":"This is the main problem."},{"use":"主要是 + ……: chủ yếu là…","ex":"我喜欢这里，主要是因为环境好。","py":"Wǒ xǐhuan zhèlǐ, zhǔyào shì yīnwèi huánjìng hǎo.","vi":"Tôi thích nơi này chủ yếu vì môi trường tốt.","en":"I like it here mainly because the environment is good."},{"use":"主要 + 原因.","ex":"迟到的主要原因是堵车。","py":"Chídào de zhǔyào yuányīn shì dǔchē.","vi":"Nguyên nhân chính của việc đến muộn là tắc đường.","en":"The main reason for being late was traffic."}]},"自行车":{"en":"bicycle","exs":[{"use":"Danh từ; lượng từ: 辆.","ex":"我骑自行车去学校。","py":"Wǒ qí zìxíngchē qù xuéxiào.","vi":"Tôi đạp xe đến trường.","en":"I cycle to school."},{"use":"买自行车.","ex":"他想买一辆新自行车。","py":"Tā xiǎng mǎi yí liàng xīn zìxíngchē.","vi":"Anh ấy muốn mua một chiếc xe đạp mới.","en":"He wants to buy a new bicycle."},{"use":"自行车 + 坏了.","ex":"我的自行车坏了，得去修。","py":"Wǒ de zìxíngchē huài le, děi qù xiū.","vi":"Xe đạp của tôi hỏng, phải đem đi sửa.","en":"My bicycle is broken; I have to get it fixed."}]},"中介":{"en":"agent; intermediary","exs":[{"use":"Danh từ: 房屋中介: môi giới nhà đất.","ex":"我通过中介找到了房子。","py":"Wǒ tōngguò zhōngjiè zhǎodào le fángzi.","vi":"Tôi tìm được nhà qua môi giới.","en":"I found a place through an agent."},{"use":"找中介.","ex":"你可以去找一个中介帮忙。","py":"Nǐ kěyǐ qù zhǎo yí ge zhōngjiè bāngmáng.","vi":"Bạn có thể tìm một môi giới giúp.","en":"You can look for an agent to help."},{"use":"中介费: phí môi giới.","ex":"中介费是一个月的房租。","py":"Zhōngjiè fèi shì yí ge yuè de fángzū.","vi":"Phí môi giới bằng một tháng tiền thuê nhà.","en":"The agent's fee is one month's rent."}]},"笔记本（电脑）":{"en":"laptop; notebook","exs":[{"use":"Danh từ: 笔记本 còn có nghĩa là quyển vở ghi chép.","ex":"我的笔记本电脑坏了。","py":"Wǒ de bǐjìběn diànnǎo huài le.","vi":"Laptop của tôi bị hỏng rồi.","en":"My laptop is broken."},{"use":"带笔记本: mang theo laptop / vở ghi.","ex":"开会的时候请带笔记本。","py":"Kāihuì de shíhou qǐng dài bǐjìběn.","vi":"Khi họp xin hãy mang theo laptop.","en":"Please bring a laptop to the meeting."},{"use":"用笔记本记东西.","ex":"他用笔记本记下了老师的话。","py":"Tā yòng bǐjìběn jì xià le lǎoshī de huà.","vi":"Anh ấy ghi lại lời thầy vào quyển vở.","en":"He wrote down the teacher's words in a notebook."}]},"词典":{"en":"dictionary","exs":[{"use":"Danh từ; lượng từ: 本.","ex":"我买了一本汉语词典。","py":"Wǒ mǎi le yì běn Hànyǔ cídiǎn.","vi":"Tôi mua một quyển từ điển tiếng Hán.","en":"I bought a Chinese dictionary."},{"use":"查词典: tra từ điển.","ex":"不认识的字可以查词典。","py":"Bú rènshi de zì kěyǐ chá cídiǎn.","vi":"Chữ không biết có thể tra từ điển.","en":"Look up unknown characters in a dictionary."},{"use":"电子词典.","ex":"他用电子词典学汉语。","py":"Tā yòng diànzǐ cídiǎn xué Hànyǔ.","vi":"Anh ấy dùng từ điển điện tử học tiếng Hán.","en":"He uses an electronic dictionary to study Chinese."}]},"灯":{"en":"lamp; light","exs":[{"use":"Danh từ; 开灯 / 关灯: bật / tắt đèn.","ex":"请把灯关了。","py":"Qǐng bǎ dēng guān le.","vi":"Làm ơn tắt đèn đi.","en":"Please turn off the light."},{"use":"开灯: bật đèn.","ex":"屋里太黑了，快开灯吧。","py":"Wū lǐ tài hēi le, kuài kāi dēng ba.","vi":"Trong phòng tối quá, mau bật đèn đi.","en":"It's too dark in here; turn on the light."},{"use":"一盏灯: một ngọn đèn.","ex":"桌子上有一盏小灯。","py":"Zhuōzi shàng yǒu yì zhǎn xiǎo dēng.","vi":"Trên bàn có một chiếc đèn nhỏ.","en":"There is a small lamp on the table."}]},"地铁":{"en":"subway","exs":[{"use":"Danh từ: 坐地铁: đi tàu điện ngầm.","ex":"我每天坐地铁上班。","py":"Wǒ měitiān zuò dìtiě shàngbān.","vi":"Mỗi ngày tôi đi làm bằng tàu điện ngầm.","en":"I take the subway to work every day."},{"use":"地铁站 / 地铁票.","ex":"地铁站离这儿很近。","py":"Dìtiě zhàn lí zhèr hěn jìn.","vi":"Ga tàu điện ngầm rất gần đây.","en":"The subway station is very close."},{"use":"换地铁: đổi tàu.","ex":"你要在前面那站换地铁。","py":"Nǐ yào zài qiánmiàn nà zhàn huàn dìtiě.","vi":"Bạn phải đổi tàu ở ga phía trước.","en":"You need to change trains at the next station."}]},"电子邮件":{"en":"e-mail","exs":[{"use":"Danh từ; khẩu ngữ hay nói 邮件.","ex":"请把资料发到我的电子邮件里。","py":"Qǐng bǎ zīliào fā dào wǒ de diànzǐ yóujiàn lǐ.","vi":"Hãy gửi tài liệu vào email của tôi.","en":"Please send the materials to my email."},{"use":"发电子邮件 / 收电子邮件.","ex":"他每天要发很多电子邮件。","py":"Tā měitiān yào fā hěn duō diànzǐ yóujiàn.","vi":"Mỗi ngày anh ấy phải gửi rất nhiều email.","en":"He sends lots of emails every day."},{"use":"电子邮件地址.","ex":"你的电子邮件地址是什么？","py":"Nǐ de diànzǐ yóujiàn dìzhǐ shì shénme?","vi":"Địa chỉ email của bạn là gì?","en":"What is your email address?"}]},"关":{"en":"to close; to turn off","exs":[{"use":"关 + 门/灯/电视: đóng / tắt.","ex":"走的时候请关门。","py":"Zǒu de shíhou qǐng guān mén.","vi":"Lúc đi xin hãy đóng cửa.","en":"Please close the door when you leave."},{"use":"关 + 空调 / 电脑.","ex":"别忘了关电脑。","py":"Bié wàng le guān diànnǎo.","vi":"Đừng quên tắt máy tính.","en":"Don't forget to turn off the computer."},{"use":"关上 / 关好.","ex":"他把窗户关好了。","py":"Tā bǎ chuānghu guān hǎo le.","vi":"Anh ấy đã đóng cửa sổ cẩn thận.","en":"He closed the window properly."}]},"还":{"en":"to return; to give back","exs":[{"use":"还 (huán) + vật/tiền: trả lại.","ex":"这本书我明天还你。","py":"Zhè běn shū wǒ míngtiān huán nǐ.","vi":"Quyển sách này mai tôi trả bạn.","en":"I'll give this book back to you tomorrow."},{"use":"还钱: trả tiền.","ex":"我下个月还你钱。","py":"Wǒ xià ge yuè huán nǐ qián.","vi":"Tháng sau tôi trả tiền bạn.","en":"I'll pay you back next month."},{"use":"借 + 还: mượn rồi trả.","ex":"图书馆的书要按时还。","py":"Túshūguǎn de shū yào ànshí huán.","vi":"Sách thư viện phải trả đúng hạn.","en":"Library books must be returned on time."}]},"会议":{"en":"meeting; conference","exs":[{"use":"Danh từ; 开会议 / 参加会议.","ex":"明天上午有一个重要的会议。","py":"Míngtiān shàngwǔ yǒu yí ge zhòngyào de huìyì.","vi":"Sáng mai có một cuộc họp quan trọng.","en":"There is an important meeting tomorrow morning."},{"use":"会议室: phòng họp.","ex":"经理在会议室等大家。","py":"Jīnglǐ zài huìyìshì děng dàjiā.","vi":"Giám đốc đợi mọi người trong phòng họp.","en":"The manager is waiting in the meeting room."},{"use":"会议 + 结束 / 开始.","ex":"会议九点开始，十一点结束。","py":"Huìyì jiǔ diǎn kāishǐ, shíyī diǎn jiéshù.","vi":"Cuộc họp bắt đầu lúc chín giờ, kết thúc lúc mười một giờ.","en":"The meeting starts at nine and ends at eleven."}]},"结束":{"en":"to end; to finish","exs":[{"use":"结束 + (…): kết thúc; trái nghĩa 开始.","ex":"电影什么时候结束？","py":"Diànyǐng shénme shíhou jiéshù?","vi":"Bao giờ phim kết thúc?","en":"When does the movie end?"},{"use":"会议 / 考试 + 结束了.","ex":"考试结束后我们去吃饭。","py":"Kǎoshì jiéshù hòu wǒmen qù chīfàn.","vi":"Thi xong chúng ta đi ăn.","en":"After the exam ends we'll go eat."},{"use":"结束 + 工作 / 谈话.","ex":"他很快结束了谈话。","py":"Tā hěn kuài jiéshù le tánhuà.","vi":"Anh ấy nhanh chóng kết thúc cuộc trò chuyện.","en":"He wrapped up the conversation quickly."}]},"借":{"en":"to borrow; to lend","exs":[{"use":"跟 + người + 借 + vật: mượn của ai. 借给 + người: cho ai mượn.","ex":"我想跟你借一本词典。","py":"Wǒ xiǎng gēn nǐ jiè yì běn cídiǎn.","vi":"Tôi muốn mượn bạn một quyển từ điển.","en":"I'd like to borrow a dictionary from you."},{"use":"借给 + 人.","ex":"他把自行车借给了我。","py":"Tā bǎ zìxíngchē jiè gěi le wǒ.","vi":"Anh ấy cho tôi mượn xe đạp.","en":"He lent me his bicycle."},{"use":"借书 / 借钱.","ex":"我常去图书馆借书。","py":"Wǒ cháng qù túshūguǎn jiè shū.","vi":"Tôi thường đến thư viện mượn sách.","en":"I often borrow books from the library."}]},"空调":{"en":"air conditioner","exs":[{"use":"Danh từ: 开空调 / 关空调.","ex":"房间里太热了，开空调吧。","py":"Fángjiān lǐ tài rè le, kāi kōngtiáo ba.","vi":"Trong phòng nóng quá, bật điều hòa đi.","en":"It's too hot in here; turn on the air conditioner."},{"use":"走的时候关空调.","ex":"别忘了把空调关了。","py":"Bié wàng le bǎ kōngtiáo guān le.","vi":"Đừng quên tắt điều hòa.","en":"Don't forget to turn off the air conditioner."},{"use":"空调坏了 / 修空调.","ex":"我们家的空调坏了。","py":"Wǒmen jiā de kōngtiáo huài le.","vi":"Điều hòa nhà chúng tôi hỏng rồi.","en":"Our air conditioner is broken."}]},"口":{"en":"mouth; measure word (family members, mouthfuls)","exs":[{"use":"一家 + 数字 + 口人: gia đình có … người.","ex":"我家有四口人。","py":"Wǒ jiā yǒu sì kǒu rén.","vi":"Nhà tôi có bốn người.","en":"There are four people in my family."},{"use":"一口: một ngụm / một miếng.","ex":"他喝了一口水。","py":"Tā hē le yì kǒu shuǐ.","vi":"Anh ấy uống một ngụm nước.","en":"He took a sip of water."},{"use":"口 (danh từ): miệng.","ex":"请张开口。","py":"Qǐng zhāngkāi kǒu.","vi":"Xin hãy há miệng ra.","en":"Please open your mouth."}]},"筷子":{"en":"chopsticks","exs":[{"use":"Danh từ; lượng từ: 双.","ex":"我会用筷子吃饭。","py":"Wǒ huì yòng kuàizi chīfàn.","vi":"Tôi biết dùng đũa ăn cơm.","en":"I can eat with chopsticks."},{"use":"一双筷子.","ex":"请给我一双筷子。","py":"Qǐng gěi wǒ yì shuāng kuàizi.","vi":"Cho tôi một đôi đũa.","en":"Please give me a pair of chopsticks."},{"use":"拿筷子 / 放筷子.","ex":"桌子上放着两双筷子。","py":"Zhuōzi shàng fàng zhe liǎng shuāng kuàizi.","vi":"Trên bàn đặt hai đôi đũa.","en":"Two pairs of chopsticks lie on the table."}]},"啤酒":{"en":"beer","exs":[{"use":"Danh từ; lượng từ: 瓶, 杯.","ex":"他喝了两瓶啤酒。","py":"Tā hē le liǎng píng píjiǔ.","vi":"Anh ấy uống hai chai bia.","en":"He drank two bottles of beer."},{"use":"喝啤酒.","ex":"夏天很多人喜欢喝冰啤酒。","py":"Xiàtiān hěn duō rén xǐhuan hē bīng píjiǔ.","vi":"Mùa hè nhiều người thích uống bia lạnh.","en":"Many people like cold beer in summer."},{"use":"来一瓶啤酒.","ex":"服务员，再来一瓶啤酒。","py":"Fúwùyuán, zài lái yì píng píjiǔ.","vi":"Phục vụ ơi, cho thêm một chai bia.","en":"Waiter, another bottle of beer please."}]},"瓶子":{"en":"bottle","exs":[{"use":"Danh từ; lượng từ khi đếm: 个 / 只.","ex":"桌子上有一个空瓶子。","py":"Zhuōzi shàng yǒu yí ge kōng píngzi.","vi":"Trên bàn có một cái chai rỗng.","en":"There is an empty bottle on the table."},{"use":"瓶子里 + 有.","ex":"瓶子里还有一点儿水。","py":"Píngzi lǐ hái yǒu yìdiǎnr shuǐ.","vi":"Trong chai còn một ít nước.","en":"There's still a little water in the bottle."},{"use":"小瓶子 / 玻璃瓶子.","ex":"这个玻璃瓶子很漂亮。","py":"Zhège bōli píngzi hěn piàoliang.","vi":"Chiếc chai thủy tinh này rất đẹp.","en":"This glass bottle is lovely."}]},"双":{"en":"pair (measure word)","exs":[{"use":"一双 + giày / đũa / tay…","ex":"我想买一双运动鞋。","py":"Wǒ xiǎng mǎi yì shuāng yùndòng xié.","vi":"Tôi muốn mua một đôi giày thể thao.","en":"I'd like to buy a pair of sneakers."},{"use":"一双筷子 / 一双手.","ex":"这双筷子是新的。","py":"Zhè shuāng kuàizi shì xīn de.","vi":"Đôi đũa này là đồ mới.","en":"This pair of chopsticks is new."},{"use":"双 + 数字: 双人 / 双份.","ex":"我们订了一间双人房。","py":"Wǒmen dìng le yì jiān shuāngrén fáng.","vi":"Chúng tôi đặt một phòng đôi.","en":"We booked a double room."}]},"图书馆":{"en":"library","exs":[{"use":"Danh từ chỉ nơi mượn, đọc sách.","ex":"他每天都去图书馆看书。","py":"Tā měitiān dōu qù túshūguǎn kàn shū.","vi":"Mỗi ngày anh ấy đều đến thư viện đọc sách.","en":"He goes to the library to read every day."},{"use":"在图书馆 + 借 / 还书.","ex":"这本书要在图书馆还。","py":"Zhè běn shū yào zài túshūguǎn huán.","vi":"Quyển sách này phải trả ở thư viện.","en":"This book must be returned at the library."},{"use":"学校图书馆.","ex":"学校图书馆晚上十点关门。","py":"Xuéxiào túshūguǎn wǎnshang shí diǎn guān mén.","vi":"Thư viện trường đóng cửa lúc mười giờ tối.","en":"The school library closes at ten at night."}]},"忘记":{"en":"to forget","exs":[{"use":"忘记 + việc / động từ: quên.","ex":"我忘记带钥匙了。","py":"Wǒ wàngjì dài yàoshi le.","vi":"Tôi quên mang chìa khóa rồi.","en":"I forgot to bring my keys."},{"use":"别忘记 + ……: đừng quên.","ex":"别忘记明天的会议。","py":"Bié wàngjì míngtiān de huìyì.","vi":"Đừng quên cuộc họp ngày mai.","en":"Don't forget tomorrow's meeting."},{"use":"忘记 + 了 + 名字.","ex":"我忘记他叫什么了。","py":"Wǒ wàngjì tā jiào shénme le.","vi":"Tôi quên anh ấy tên gì rồi.","en":"I've forgotten what his name is."}]},"习惯":{"en":"to be used to; habit","exs":[{"use":"习惯 + 动词/名词: quen với. 习惯 (danh từ): thói quen.","ex":"我还不习惯这里的天气。","py":"Wǒ hái bù xíguàn zhèlǐ de tiānqì.","vi":"Tôi vẫn chưa quen với thời tiết ở đây.","en":"I'm not used to the weather here yet."},{"use":"习惯 + 了.","ex":"住了一年，我已经习惯了。","py":"Zhù le yì nián, wǒ yǐjīng xíguàn le.","vi":"Ở một năm rồi, tôi đã quen.","en":"After a year, I've gotten used to it."},{"use":"好习惯 / 坏习惯: thói quen tốt / xấu.","ex":"早睡早起是个好习惯。","py":"Zǎo shuì zǎo qǐ shì ge hǎo xíguàn.","vi":"Ngủ sớm dậy sớm là một thói quen tốt.","en":"Going to bed and getting up early is a good habit."}]},"包":{"en":"bag; sack","exs":[{"use":"Danh từ: túi xách, cặp.","ex":"我的包里有一本书。","py":"Wǒ de bāo lǐ yǒu yì běn shū.","vi":"Trong túi tôi có một quyển sách.","en":"There's a book in my bag."},{"use":"背包 / 书包: ba lô / cặp sách.","ex":"他的书包很重。","py":"Tā de shūbāo hěn zhòng.","vi":"Cặp sách của anh ấy rất nặng.","en":"His school bag is very heavy."},{"use":"包 + 里 / 外.","ex":"她把手机放在包里了。","py":"Tā bǎ shǒujī fàng zài bāo lǐ le.","vi":"Cô ấy cất điện thoại vào túi.","en":"She put her phone in her bag."}]},"发现":{"en":"to find; to discover","exs":[{"use":"发现 + (câu / việc): nhận ra, phát hiện.","ex":"我发现钱包不见了。","py":"Wǒ fāxiàn qiánbāo bú jiàn le.","vi":"Tôi phát hiện ví không thấy đâu nữa.","en":"I found that my wallet was missing."},{"use":"发现 + 问题.","ex":"老师发现了他的错误。","py":"Lǎoshī fāxiàn le tā de cuòwù.","vi":"Cô giáo phát hiện lỗi của cậu ấy.","en":"The teacher spotted his mistake."},{"use":"没发现 / 才发现.","ex":"到家以后才发现忘带钥匙了。","py":"Dào jiā yǐhòu cái fāxiàn wàng dài yàoshi le.","vi":"Về đến nhà mới phát hiện quên mang chìa khóa.","en":"I only noticed I'd forgotten my keys after getting home."}]},"黑板":{"en":"blackboard","exs":[{"use":"Danh từ: 在黑板上写字.","ex":"老师在黑板上写了一个汉字。","py":"Lǎoshī zài hēibǎn shàng xiě le yí ge Hànzì.","vi":"Cô giáo viết một chữ Hán lên bảng.","en":"The teacher wrote a character on the blackboard."},{"use":"擦黑板: lau bảng.","ex":"值日生要擦黑板。","py":"Zhírìshēng yào cā hēibǎn.","vi":"Học sinh trực nhật phải lau bảng.","en":"The student on duty has to wipe the board."},{"use":"看黑板.","ex":"请大家看黑板。","py":"Qǐng dàjiā kàn hēibǎn.","vi":"Mời mọi người nhìn lên bảng.","en":"Everyone, please look at the blackboard."}]},"护照":{"en":"passport","exs":[{"use":"Danh từ; lượng từ: 本.","ex":"出国一定要带护照。","py":"Chūguó yídìng yào dài hùzhào.","vi":"Ra nước ngoài nhất định phải mang hộ chiếu.","en":"You must bring your passport when going abroad."},{"use":"办护照: làm hộ chiếu.","ex":"我下周去办护照。","py":"Wǒ xià zhōu qù bàn hùzhào.","vi":"Tuần sau tôi đi làm hộ chiếu.","en":"I'm applying for a passport next week."},{"use":"护照 + 丢了 / 找到了.","ex":"我的护照不见了！","py":"Wǒ de hùzhào bú jiàn le!","vi":"Hộ chiếu của tôi mất rồi!","en":"My passport is missing!"}]},"画":{"en":"to draw; picture","exs":[{"use":"Động từ: 画 + 画儿 / 人 / 花.","ex":"她喜欢画画儿。","py":"Tā xǐhuan huà huàr.","vi":"Cô ấy thích vẽ tranh.","en":"She likes drawing."},{"use":"画 + 得 + 很好: vẽ rất đẹp.","ex":"他画得很好。","py":"Tā huà de hěn hǎo.","vi":"Anh ấy vẽ rất đẹp.","en":"He draws very well."},{"use":"一张画 / 一幅画: một bức tranh.","ex":"墙上挂着一幅画。","py":"Qiáng shàng guà zhe yì fú huà.","vi":"Trên tường treo một bức tranh.","en":"A painting hangs on the wall."}]},"教":{"en":"to teach","exs":[{"use":"教 + người + 学科: dạy ai môn gì.","ex":"他教我们汉语。","py":"Tā jiāo wǒmen Hànyǔ.","vi":"Anh ấy dạy chúng tôi tiếng Hán.","en":"He teaches us Chinese."},{"use":"教 + 书: dạy học.","ex":"她在大学教书。","py":"Tā zài dàxué jiāo shū.","vi":"Cô ấy dạy học ở trường đại học.","en":"She teaches at a university."},{"use":"请你教我 + …….","ex":"请你教我怎么用这个机器。","py":"Qǐng nǐ jiāo wǒ zěnme yòng zhège jīqì.","vi":"Xin bạn chỉ tôi cách dùng cái máy này.","en":"Please teach me how to use this machine."}]},"起飞":{"en":"to take off (aircraft)","exs":[{"use":"Động từ dùng cho máy bay; trái nghĩa 降落.","ex":"飞机几点起飞？","py":"Fēijī jǐ diǎn qǐfēi?","vi":"Máy bay cất cánh lúc mấy giờ?","en":"What time does the plane take off?"},{"use":"马上就要起飞了.","ex":"飞机马上就要起飞了，请关机。","py":"Fēijī mǎshàng jiù yào qǐfēi le, qǐng guān jī.","vi":"Máy bay sắp cất cánh, xin hãy tắt máy.","en":"The plane is about to take off; please turn off your phone."},{"use":"准时起飞.","ex":"因为下雨，飞机没有准时起飞。","py":"Yīnwèi xià yǔ, fēijī méiyǒu zhǔnshí qǐfēi.","vi":"Vì mưa nên máy bay không cất cánh đúng giờ.","en":"The plane didn't take off on time because of rain."}]},"生气":{"en":"to get angry","exs":[{"use":"Động từ ly hợp: 生 + 气; 生 + 人 + 的气.","ex":"他生气了，一句话也不说。","py":"Tā shēng qì le, yí jù huà yě bù shuō.","vi":"Anh ấy giận, không nói một lời.","en":"He got angry and didn't say a word."},{"use":"别生气: đừng giận.","ex":"别生气，我不是故意的。","py":"Bié shēng qì, wǒ bú shì gùyì de.","vi":"Đừng giận, tôi không cố ý.","en":"Don't be angry; I didn't mean to."},{"use":"生 + 人 + 的气: giận ai.","ex":"妈妈在生我的气。","py":"Māma zài shēng wǒ de qì.","vi":"Mẹ đang giận tôi.","en":"Mom is angry with me."}]},"司机":{"en":"driver","exs":[{"use":"Danh từ chỉ nghề lái xe.","ex":"出租车司机很热情。","py":"Chūzūchē sījī hěn rèqíng.","vi":"Tài xế taxi rất nhiệt tình.","en":"The taxi driver is very friendly."},{"use":"当司机: làm tài xế.","ex":"他的爸爸是公共汽车司机。","py":"Tā de bàba shì gōnggòng qìchē sījī.","vi":"Bố anh ấy là tài xế xe buýt.","en":"His father is a bus driver."},{"use":"跟司机说 + …….","ex":"请跟司机说去机场。","py":"Qǐng gēn sījī shuō qù jīchǎng.","vi":"Hãy nói với tài xế là đi sân bay.","en":"Please tell the driver to go to the airport."}]},"太阳":{"en":"sun","exs":[{"use":"Danh từ; 出太阳: có nắng.","ex":"今天太阳很大。","py":"Jīntiān tàiyáng hěn dà.","vi":"Hôm nay nắng to.","en":"The sun is strong today."},{"use":"太阳 + 从东边升起.","ex":"太阳从东边升起来。","py":"Tàiyáng cóng dōngbiān shēng qǐlai.","vi":"Mặt trời mọc từ phía đông.","en":"The sun rises in the east."},{"use":"晒太阳: tắm nắng.","ex":"老人们坐在外面晒太阳。","py":"Lǎorénmen zuò zài wàimiàn shài tàiyáng.","vi":"Các cụ ngồi ngoài trời phơi nắng.","en":"The elderly sit outside enjoying the sun."}]},"西":{"en":"west","exs":[{"use":"Danh từ chỉ phương hướng: 西边 / 往西.","ex":"太阳从西边落下去。","py":"Tàiyáng cóng xībiān luò xiàqu.","vi":"Mặt trời lặn ở phía tây.","en":"The sun sets in the west."},{"use":"往西走.","ex":"往西走一百米就到了。","py":"Wǎng xī zǒu yì bǎi mǐ jiù dào le.","vi":"Đi về phía tây một trăm mét là tới.","en":"Go west a hundred metres and you're there."},{"use":"东西南北.","ex":"我分不清东西南北。","py":"Wǒ fēn bù qīng dōng xī nán běi.","vi":"Tôi không phân biệt được đông tây nam bắc.","en":"I can't tell north from south or east from west."}]},"行李箱":{"en":"suitcase","exs":[{"use":"Danh từ; lượng từ: 个.","ex":"他的行李箱很重。","py":"Tā de xínglixiāng hěn zhòng.","vi":"Va li của anh ấy rất nặng.","en":"His suitcase is very heavy."},{"use":"打开 / 关上行李箱.","ex":"请打开你的行李箱。","py":"Qǐng dǎkāi nǐ de xínglixiāng.","vi":"Xin hãy mở va li của bạn ra.","en":"Please open your suitcase."},{"use":"把……放进行李箱.","ex":"她把护照放进了行李箱。","py":"Tā bǎ hùzhào fàng jìn le xínglixiāng.","vi":"Cô ấy bỏ hộ chiếu vào va li.","en":"She put her passport in the suitcase."}]},"需要":{"en":"to need","exs":[{"use":"需要 + danh từ / động từ: cần.","ex":"你需要帮忙吗？","py":"Nǐ xūyào bāngmáng ma?","vi":"Bạn có cần giúp không?","en":"Do you need help?"},{"use":"需要 + 时间 / 钱.","ex":"做这件事需要很长时间。","py":"Zuò zhè jiàn shì xūyào hěn cháng shíjiān.","vi":"Làm việc này cần rất nhiều thời gian.","en":"This takes a long time."},{"use":"不需要: không cần.","ex":"你不需要担心。","py":"Nǐ bù xūyào dānxīn.","vi":"Bạn không cần phải lo.","en":"You don't need to worry."}]},"自己":{"en":"oneself","exs":[{"use":"Đại từ nhấn mạnh người thực hiện.","ex":"这件事我想自己做。","py":"Zhè jiàn shì wǒ xiǎng zìjǐ zuò.","vi":"Việc này tôi muốn tự làm.","en":"I want to do this myself."},{"use":"照顾自己.","ex":"你要照顾好自己。","py":"Nǐ yào zhàogù hǎo zìjǐ.","vi":"Bạn phải chăm sóc tốt cho bản thân.","en":"Take good care of yourself."},{"use":"自己的 + danh từ.","ex":"每个人都有自己的爱好。","py":"Měi ge rén dōu yǒu zìjǐ de àihào.","vi":"Mỗi người đều có sở thích riêng.","en":"Everyone has their own hobbies."}]},"过去":{"en":"the past","exs":[{"use":"Danh từ chỉ thời gian đã qua.","ex":"过去的事就别再提了。","py":"Guòqù de shì jiù bié zài tí le.","vi":"Chuyện đã qua thì đừng nhắc lại nữa.","en":"Let's not bring up the past again."},{"use":"过去 + 我 + ……: ngày trước tôi…","ex":"过去我常常骑自行车上学。","py":"Guòqù wǒ chángcháng qí zìxíngchē shàngxué.","vi":"Ngày trước tôi thường đạp xe đến trường.","en":"In the past I often cycled to school."},{"use":"跟过去不一样.","ex":"这里跟过去不一样了。","py":"Zhèlǐ gēn guòqù bù yíyàng le.","vi":"Nơi này không còn như trước nữa.","en":"This place isn't the same as before."}]},"坏":{"en":"broken; bad","exs":[{"use":"坏 (tính từ): hỏng, xấu. 坏了: bị hỏng.","ex":"我的手机坏了。","py":"Wǒ de shǒujī huài le.","vi":"Điện thoại của tôi hỏng rồi.","en":"My phone is broken."},{"use":"坏人 / 坏事.","ex":"他不是坏人。","py":"Tā bú shì huàirén.","vi":"Anh ấy không phải người xấu.","en":"He isn't a bad person."},{"use":"Tính từ + 坏了: … quá chừng.","ex":"我今天累坏了。","py":"Wǒ jīntiān lèi huài le.","vi":"Hôm nay tôi mệt rã rời.","en":"I'm exhausted today."}]},"经常":{"en":"often","exs":[{"use":"经常 + động từ: thường làm gì.","ex":"他经常去图书馆学习。","py":"Tā jīngcháng qù túshūguǎn xuéxí.","vi":"Anh ấy thường đến thư viện học bài.","en":"He often studies at the library."},{"use":"不经常: không thường xuyên.","ex":"我不经常看电视。","py":"Wǒ bù jīngcháng kàn diànshì.","vi":"Tôi không thường xem tivi.","en":"I don't watch TV often."},{"use":"经常 + 迟到 / 加班.","ex":"他最近经常加班。","py":"Tā zuìjìn jīngcháng jiābān.","vi":"Dạo này anh ấy thường xuyên làm thêm.","en":"He has been working overtime often recently."}]},"礼物":{"en":"gift; present","exs":[{"use":"Danh từ; 送礼物: tặng quà.","ex":"这是送给你的生日礼物。","py":"Zhè shì sòng gěi nǐ de shēngrì lǐwù.","vi":"Đây là quà sinh nhật tặng bạn.","en":"This is a birthday gift for you."},{"use":"收到礼物: nhận được quà.","ex":"她收到了很多礼物。","py":"Tā shōudào le hěn duō lǐwù.","vi":"Cô ấy nhận được rất nhiều quà.","en":"She received many gifts."},{"use":"买礼物.","ex":"我想给奶奶买一件礼物。","py":"Wǒ xiǎng gěi nǎinai mǎi yí jiàn lǐwù.","vi":"Tôi muốn mua quà cho bà.","en":"I want to buy a gift for my grandmother."}]},"奶奶":{"en":"paternal grandmother","exs":[{"use":"Danh từ chỉ quan hệ gia đình; cũng gọi bà lớn tuổi thân mật.","ex":"奶奶今年七十岁了。","py":"Nǎinai jīnnián qīshí suì le.","vi":"Năm nay bà nội bảy mươi tuổi.","en":"Grandma is seventy this year."},{"use":"跟奶奶住在一起.","ex":"我小时候跟奶奶住在一起。","py":"Wǒ xiǎoshíhou gēn nǎinai zhù zài yìqǐ.","vi":"Hồi nhỏ tôi sống cùng bà nội.","en":"I lived with my grandmother as a child."},{"use":"奶奶做的菜.","ex":"我最爱吃奶奶做的菜。","py":"Wǒ zuì ài chī nǎinai zuò de cài.","vi":"Tôi thích nhất món bà nội nấu.","en":"I love the food my grandmother cooks the most."}]},"起来":{"en":"up; (indicating the start of an action)","exs":[{"use":"动词 + 起来: hướng lên; bắt đầu một trạng thái.","ex":"他从椅子上站起来了。","py":"Tā cóng yǐzi shàng zhàn qǐlai le.","vi":"Anh ấy đứng dậy khỏi ghế.","en":"He stood up from the chair."},{"use":"想起来 / 记起来: nhớ ra.","ex":"我想起来了，他叫小明。","py":"Wǒ xiǎng qǐlai le, tā jiào Xiǎomíng.","vi":"Tôi nhớ ra rồi, anh ấy tên Tiểu Minh.","en":"I remember now; his name is Xiaoming."},{"use":"动词/形容词 + 起来: bắt đầu…","ex":"听到这个消息，大家都笑了起来。","py":"Tīngdào zhège xiāoxi, dàjiā dōu xiào le qǐlai.","vi":"Nghe tin này mọi người đều bật cười.","en":"Hearing the news, everyone started to laugh."}]},"校长":{"en":"headmaster; principal","exs":[{"use":"Danh từ chỉ chức vụ.","ex":"校长在会议室等你。","py":"Xiàozhǎng zài huìyìshì děng nǐ.","vi":"Hiệu trưởng đang đợi bạn ở phòng họp.","en":"The principal is waiting for you in the meeting room."},{"use":"王校长 / 校长先生.","ex":"王校长今天要来我们班。","py":"Wáng xiàozhǎng jīntiān yào lái wǒmen bān.","vi":"Hôm nay hiệu trưởng Vương sẽ đến lớp chúng tôi.","en":"Principal Wang is coming to our class today."},{"use":"当校长.","ex":"他三年前当了校长。","py":"Tā sān nián qián dāng le xiàozhǎng.","vi":"Ba năm trước ông ấy làm hiệu trưởng.","en":"He became principal three years ago."}]},"爷爷":{"en":"paternal grandfather","exs":[{"use":"Danh từ chỉ quan hệ gia đình.","ex":"爷爷每天早上都去公园。","py":"Yéye měitiān zǎoshang dōu qù gōngyuán.","vi":"Ông nội sáng nào cũng ra công viên.","en":"Grandpa goes to the park every morning."},{"use":"爷爷奶奶: ông bà nội.","ex":"爷爷奶奶住在乡下。","py":"Yéye nǎinai zhù zài xiāngxia.","vi":"Ông bà nội sống ở quê.","en":"My grandparents live in the countryside."},{"use":"给爷爷 + 打电话.","ex":"我给爷爷打了个电话。","py":"Wǒ gěi yéye dǎ le ge diànhuà.","vi":"Tôi gọi điện cho ông nội.","en":"I phoned my grandfather."}]},"一般":{"en":"generally; ordinary","exs":[{"use":"一般 + 动词: thường thì. 一般 (tính từ): bình thường.","ex":"我一般七点起床。","py":"Wǒ yìbān qī diǎn qǐchuáng.","vi":"Tôi thường dậy lúc bảy giờ.","en":"I usually get up at seven."},{"use":"一般来说: nói chung.","ex":"一般来说，周末人比较少。","py":"Yìbān lái shuō, zhōumò rén bǐjiào shǎo.","vi":"Nói chung cuối tuần người khá ít.","en":"Generally speaking, there are fewer people at weekends."},{"use":"不太一般 / 很一般: bình thường thôi.","ex":"这家饭馆的菜很一般。","py":"Zhè jiā fànguǎn de cài hěn yìbān.","vi":"Món ở quán này cũng bình thường.","en":"The food at this restaurant is just so-so."}]},"一边":{"en":"at the same time","exs":[{"use":"一边 + V1 + 一边 + V2: vừa làm V1 vừa làm V2.","ex":"他一边吃饭一边看电视。","py":"Tā yìbiān chīfàn yìbiān kàn diànshì.","vi":"Anh ấy vừa ăn cơm vừa xem tivi.","en":"He watches TV while eating."},{"use":"一边走一边说.","ex":"我们一边走一边聊天儿。","py":"Wǒmen yìbiān zǒu yìbiān liáotiānr.","vi":"Chúng tôi vừa đi vừa trò chuyện.","en":"We chat as we walk."},{"use":"不能一边……一边……: không thể vừa… vừa…","ex":"开车时不能一边打电话一边开。","py":"Kāichē shí bù néng yìbiān dǎ diànhuà yìbiān kāi.","vi":"Lái xe không được vừa nghe điện thoại vừa lái.","en":"You can't talk on the phone while driving."}]},"应该":{"en":"should; ought to","exs":[{"use":"应该 + động từ: nên làm gì.","ex":"你应该早点儿睡觉。","py":"Nǐ yīnggāi zǎodiǎnr shuìjiào.","vi":"Bạn nên đi ngủ sớm hơn.","en":"You should go to bed earlier."},{"use":"不应该: không nên.","ex":"你不应该这样说话。","py":"Nǐ bù yīnggāi zhèyàng shuōhuà.","vi":"Bạn không nên nói chuyện như vậy.","en":"You shouldn't talk like that."},{"use":"应该 + 会: chắc hẳn sẽ (suy đoán).","ex":"他现在应该到家了。","py":"Tā xiànzài yīnggāi dào jiā le.","vi":"Giờ này chắc anh ấy đã về đến nhà.","en":"He should be home by now."}]},"遇到":{"en":"to run into; to come across","exs":[{"use":"遇到 + người/việc: gặp phải.","ex":"我在路上遇到了老同学。","py":"Wǒ zài lùshang yùdào le lǎo tóngxué.","vi":"Trên đường tôi tình cờ gặp bạn học cũ.","en":"I ran into an old classmate on the road."},{"use":"遇到 + 问题 / 困难.","ex":"遇到问题可以问老师。","py":"Yùdào wèntí kěyǐ wèn lǎoshī.","vi":"Gặp vấn đề có thể hỏi thầy cô.","en":"If you run into problems, ask the teacher."},{"use":"没遇到过.","ex":"我还没遇到过这样的事。","py":"Wǒ hái méi yùdào guo zhèyàng de shì.","vi":"Tôi chưa từng gặp chuyện như thế.","en":"I've never come across anything like this."}]},"愿意":{"en":"to be willing","exs":[{"use":"愿意 + động từ: sẵn lòng làm gì.","ex":"我愿意帮你。","py":"Wǒ yuànyì bāng nǐ.","vi":"Tôi sẵn lòng giúp bạn.","en":"I'm willing to help you."},{"use":"不愿意: không muốn.","ex":"他不愿意告诉别人。","py":"Tā bú yuànyì gàosu biérén.","vi":"Anh ấy không muốn nói cho người khác biết.","en":"He doesn't want to tell others."},{"use":"愿意 + 跟 + 人 + …….","ex":"你愿意跟我一起去吗？","py":"Nǐ yuànyì gēn wǒ yìqǐ qù ma?","vi":"Bạn có muốn đi cùng tôi không?","en":"Would you like to go with me?"}]},"终于":{"en":"finally; at last","exs":[{"use":"终于 + 动词 + 了: cuối cùng cũng… (sau thời gian chờ đợi).","ex":"我终于找到了工作。","py":"Wǒ zhōngyú zhǎodào le gōngzuò.","vi":"Cuối cùng tôi cũng tìm được việc.","en":"I finally found a job."},{"use":"终于 + 到了 / 来了.","ex":"车终于来了。","py":"Chē zhōngyú lái le.","vi":"Xe cuối cùng cũng đến.","en":"The bus has finally come."},{"use":"他终于明白了.","ex":"经过解释，他终于明白了。","py":"Jīngguò jiěshì, tā zhōngyú míngbai le.","vi":"Sau khi giải thích, cuối cùng anh ấy cũng hiểu.","en":"After the explanation, he finally understood."}]},"生活":{"en":"life; to live","exs":[{"use":"Danh từ/động từ: cuộc sống.","ex":"他的生活很简单。","py":"Tā de shēnghuó hěn jiǎndān.","vi":"Cuộc sống của anh ấy rất đơn giản.","en":"His life is very simple."},{"use":"在 + nơi + 生活.","ex":"她在北京生活了五年。","py":"Tā zài Běijīng shēnghuó le wǔ nián.","vi":"Cô ấy sống ở Bắc Kinh năm năm.","en":"She has lived in Beijing for five years."},{"use":"生活 + 习惯 / 水平.","ex":"这里的生活习惯跟我家不一样。","py":"Zhèlǐ de shēnghuó xíguàn gēn wǒ jiā bù yíyàng.","vi":"Thói quen sinh hoạt ở đây khác ở nhà tôi.","en":"Daily habits here differ from those at my home."}]},"阿姨":{"en":"aunt; auntie","exs":[{"use":"Danh từ: gọi dì, cô; cũng gọi người giúp việc.","ex":"阿姨，请问这附近有银行吗？","py":"Āyí, qǐngwèn zhè fùjìn yǒu yínháng ma?","vi":"Cô ơi, cho cháu hỏi gần đây có ngân hàng không ạ?","en":"Auntie, is there a bank nearby?"},{"use":"王阿姨 / 李阿姨.","ex":"王阿姨每天来我家打扫。","py":"Wáng āyí měitiān lái wǒ jiā dǎsǎo.","vi":"Cô Vương ngày nào cũng đến nhà tôi dọn dẹp.","en":"Auntie Wang comes to clean our home every day."},{"use":"叔叔阿姨: chú dì (gọi người lớn).","ex":"叔叔阿姨，你们好！","py":"Shūshu āyí, nǐmen hǎo!","vi":"Cháu chào các cô chú ạ!","en":"Hello, uncles and aunties!"}]},"冰箱":{"en":"refrigerator","exs":[{"use":"Danh từ; 放在冰箱里: để vào tủ lạnh.","ex":"请把牛奶放进冰箱。","py":"Qǐng bǎ niúnǎi fàng jìn bīngxiāng.","vi":"Hãy để sữa vào tủ lạnh.","en":"Please put the milk into the fridge."},{"use":"冰箱里 + 有.","ex":"冰箱里有很多水果。","py":"Bīngxiāng lǐ yǒu hěn duō shuǐguǒ.","vi":"Trong tủ lạnh có nhiều trái cây.","en":"There is a lot of fruit in the fridge."},{"use":"买冰箱 / 新冰箱.","ex":"我们家买了一台新冰箱。","py":"Wǒmen jiā mǎi le yì tái xīn bīngxiāng.","vi":"Nhà chúng tôi mua một chiếc tủ lạnh mới.","en":"We bought a new refrigerator."}]},"菜单":{"en":"menu","exs":[{"use":"Danh từ: 看菜单, 点菜.","ex":"服务员，请给我菜单。","py":"Fúwùyuán, qǐng gěi wǒ càidān.","vi":"Phục vụ ơi, cho tôi xem thực đơn.","en":"Waiter, may I have the menu?"},{"use":"看菜单 + 点菜.","ex":"我们先看看菜单再点菜。","py":"Wǒmen xiān kànkan càidān zài diǎn cài.","vi":"Chúng ta xem thực đơn rồi hãy gọi món.","en":"Let's look at the menu before ordering."},{"use":"菜单 + 上 + 有.","ex":"菜单上的菜都很好吃。","py":"Càidān shàng de cài dōu hěn hǎochī.","vi":"Món trong thực đơn đều rất ngon.","en":"All the dishes on the menu are delicious."}]},"打扫":{"en":"to clean; to sweep","exs":[{"use":"打扫 + 房间 / 教室: dọn dẹp nơi nào.","ex":"周末我在家打扫房间。","py":"Zhōumò wǒ zài jiā dǎsǎo fángjiān.","vi":"Cuối tuần tôi ở nhà dọn phòng.","en":"I clean the room at home on weekends."},{"use":"打扫 + 干净: dọn sạch.","ex":"他把教室打扫得很干净。","py":"Tā bǎ jiàoshì dǎsǎo de hěn gānjìng.","vi":"Anh ấy dọn lớp học rất sạch sẽ.","en":"He cleaned the classroom very thoroughly."},{"use":"打扫 + 一下.","ex":"客人要来了，打扫一下吧。","py":"Kèrén yào lái le, dǎsǎo yíxià ba.","vi":"Khách sắp đến rồi, dọn dẹp một chút đi.","en":"Guests are coming; let's tidy up a bit."}]},"干净":{"en":"clean","exs":[{"use":"Tính từ; trái nghĩa 脏.","ex":"这个房间很干净。","py":"Zhège fángjiān hěn gānjìng.","vi":"Căn phòng này rất sạch sẽ.","en":"This room is very clean."},{"use":"洗干净 / 擦干净.","ex":"请把杯子洗干净。","py":"Qǐng bǎ bēizi xǐ gānjìng.","vi":"Hãy rửa sạch cái cốc.","en":"Please wash the cup clean."},{"use":"干干净净.","ex":"她把桌子擦得干干净净。","py":"Tā bǎ zhuōzi cā de gāngānjìngjìng.","vi":"Cô ấy lau bàn sạch bóng.","en":"She wiped the table spotless."}]},"故事":{"en":"story","exs":[{"use":"Danh từ; 讲故事: kể chuyện.","ex":"奶奶给孩子讲了一个故事。","py":"Nǎinai gěi háizi jiǎng le yí ge gùshi.","vi":"Bà kể cho đứa trẻ một câu chuyện.","en":"Grandma told the child a story."},{"use":"听故事 / 看故事书.","ex":"孩子们爱听故事。","py":"Háizimen ài tīng gùshi.","vi":"Trẻ con thích nghe kể chuyện.","en":"Children love listening to stories."},{"use":"故事 + 很有意思.","ex":"这个故事很有意思。","py":"Zhège gùshi hěn yǒu yìsi.","vi":"Câu chuyện này rất thú vị.","en":"This story is very interesting."}]},"刮风":{"en":"to be windy","exs":[{"use":"Động từ ly hợp: 刮 + 风; 刮大风: gió lớn.","ex":"今天刮大风，别出去了。","py":"Jīntiān guā dàfēng, bié chūqu le.","vi":"Hôm nay gió to, đừng ra ngoài nữa.","en":"It's very windy today; don't go out."},{"use":"刮风 + 下雨.","ex":"外面又刮风又下雨。","py":"Wàimiàn yòu guā fēng yòu xià yǔ.","vi":"Bên ngoài vừa có gió vừa có mưa.","en":"It's both windy and rainy outside."},{"use":"刮了一天风.","ex":"昨天刮了一天风。","py":"Zuótiān guā le yì tiān fēng.","vi":"Hôm qua gió thổi suốt cả ngày.","en":"It was windy all day yesterday."}]},"简单":{"en":"simple","exs":[{"use":"Tính từ; trái nghĩa 复杂.","ex":"这道菜做法很简单。","py":"Zhè dào cài zuòfǎ hěn jiǎndān.","vi":"Món này cách làm rất đơn giản.","en":"This dish is simple to make."},{"use":"简单 + 地 + động từ.","ex":"他简单地介绍了一下自己。","py":"Tā jiǎndān de jièshào le yíxià zìjǐ.","vi":"Anh ấy giới thiệu bản thân một cách ngắn gọn.","en":"He briefly introduced himself."},{"use":"不简单: không đơn giản (giỏi).","ex":"他一个人完成了，真不简单。","py":"Tā yí ge rén wánchéng le, zhēn bù jiǎndān.","vi":"Một mình anh ấy làm xong, thật không đơn giản.","en":"He finished it alone — quite an achievement."}]},"节目":{"en":"program; show","exs":[{"use":"Danh từ: 电视节目: chương trình truyền hình.","ex":"这个电视节目很受欢迎。","py":"Zhège diànshì jiémù hěn shòu huānyíng.","vi":"Chương trình truyền hình này rất được yêu thích.","en":"This TV program is very popular."},{"use":"看节目 / 表演节目.","ex":"晚上我们一起看节目吧。","py":"Wǎnshang wǒmen yìqǐ kàn jiémù ba.","vi":"Tối nay chúng ta cùng xem chương trình nhé.","en":"Let's watch a show together tonight."},{"use":"一个节目.","ex":"她为晚会准备了一个节目。","py":"Tā wèi wǎnhuì zhǔnbèi le yí ge jiémù.","vi":"Cô ấy chuẩn bị một tiết mục cho buổi tối giao lưu.","en":"She prepared a performance for the party."}]},"盘子":{"en":"plate; dish","exs":[{"use":"Danh từ; lượng từ: 个 / 只 (một đĩa: 一盘).","ex":"桌子上放着几个盘子。","py":"Zhuōzi shàng fàng zhe jǐ ge pánzi.","vi":"Trên bàn đặt mấy cái đĩa.","en":"A few plates are on the table."},{"use":"洗盘子: rửa đĩa.","ex":"饭后我来洗盘子。","py":"Fàn hòu wǒ lái xǐ pánzi.","vi":"Ăn xong để tôi rửa đĩa.","en":"I'll wash the dishes after the meal."},{"use":"盘子里 + 有.","ex":"盘子里有一些香蕉。","py":"Pánzi lǐ yǒu yìxiē xiāngjiāo.","vi":"Trong đĩa có mấy quả chuối.","en":"There are some bananas on the plate."}]},"然后":{"en":"then; after that","exs":[{"use":"先……，然后……: trước…, sau đó…","ex":"我先吃饭，然后去散步。","py":"Wǒ xiān chīfàn, ránhòu qù sànbù.","vi":"Tôi ăn cơm trước, sau đó đi dạo.","en":"I'll eat first, then go for a walk."},{"use":"然后 + (câu): rồi sau đó.","ex":"他打开门，然后走了进去。","py":"Tā dǎkāi mén, ránhòu zǒu le jìnqu.","vi":"Anh ấy mở cửa rồi bước vào.","en":"He opened the door and then walked in."},{"use":"然后呢?: rồi sao nữa?","ex":"然后呢？你怎么回答的？","py":"Ránhòu ne? Nǐ zěnme huídá de?","vi":"Rồi sao nữa? Bạn trả lời thế nào?","en":"And then? How did you answer?"}]},"声音":{"en":"sound; voice","exs":[{"use":"Danh từ: tiếng động, giọng nói.","ex":"我听到了奇怪的声音。","py":"Wǒ tīngdào le qíguài de shēngyīn.","vi":"Tôi nghe thấy một âm thanh lạ.","en":"I heard a strange sound."},{"use":"声音 + 大 / 小: tiếng to / nhỏ.","ex":"请把声音关小一点儿。","py":"Qǐng bǎ shēngyīn guān xiǎo yìdiǎnr.","vi":"Làm ơn vặn nhỏ âm thanh xuống một chút.","en":"Please turn the volume down a little."},{"use":"她的声音很好听.","ex":"她的声音很好听。","py":"Tā de shēngyīn hěn hǎotīng.","vi":"Giọng cô ấy rất hay.","en":"Her voice is lovely."}]},"叔叔":{"en":"uncle (father's younger brother); form of address for men","exs":[{"use":"Danh từ: chú; cách gọi người đàn ông lớn tuổi hơn mình.","ex":"叔叔下个月来我们家。","py":"Shūshu xià ge yuè lái wǒmen jiā.","vi":"Tháng sau chú sẽ đến nhà chúng tôi.","en":"My uncle is coming to our home next month."},{"use":"叔叔 + 您好.","ex":"叔叔，您好！请进。","py":"Shūshu, nín hǎo! Qǐng jìn.","vi":"Cháu chào chú! Mời chú vào ạ.","en":"Hello, uncle! Please come in."},{"use":"我的叔叔.","ex":"我叔叔是一名医生。","py":"Wǒ shūshu shì yì míng yīshēng.","vi":"Chú tôi là bác sĩ.","en":"My uncle is a doctor."}]},"洗澡":{"en":"to take a bath/shower","exs":[{"use":"Động từ ly hợp: 洗 + 澡.","ex":"我每天晚上都洗澡。","py":"Wǒ měitiān wǎnshang dōu xǐ zǎo.","vi":"Mỗi tối tôi đều tắm.","en":"I take a shower every evening."},{"use":"洗了个澡.","ex":"运动以后我洗了个热水澡。","py":"Yùndòng yǐhòu wǒ xǐ le ge rèshuǐ zǎo.","vi":"Sau khi tập thể thao tôi tắm nước nóng.","en":"I took a hot shower after exercise."},{"use":"去洗澡 / 洗完澡.","ex":"他洗完澡就睡觉了。","py":"Tā xǐ wán zǎo jiù shuìjiào le.","vi":"Anh ấy tắm xong là đi ngủ ngay.","en":"He went to bed right after his shower."}]},"香蕉":{"en":"banana","exs":[{"use":"Danh từ; lượng từ: 根, 个.","ex":"我早饭吃了一根香蕉。","py":"Wǒ zǎofàn chī le yì gēn xiāngjiāo.","vi":"Bữa sáng tôi ăn một quả chuối.","en":"I had a banana for breakfast."},{"use":"买香蕉.","ex":"超市的香蕉很新鲜。","py":"Chāoshì de xiāngjiāo hěn xīnxiān.","vi":"Chuối ở siêu thị rất tươi.","en":"The bananas at the supermarket are fresh."},{"use":"香蕉 + 很甜.","ex":"这些香蕉又大又甜。","py":"Zhèxiē xiāngjiāo yòu dà yòu tián.","vi":"Những quả chuối này vừa to vừa ngọt.","en":"These bananas are big and sweet."}]},"像":{"en":"to be like; to resemble","exs":[{"use":"A 像 B: A giống B.","ex":"她长得很像她妈妈。","py":"Tā zhǎng de hěn xiàng tā māma.","vi":"Cô ấy trông rất giống mẹ.","en":"She looks a lot like her mother."},{"use":"像 + 名词 + 一样: giống như…","ex":"这里的夏天像火炉一样热。","py":"Zhèlǐ de xiàtiān xiàng huǒlú yíyàng rè.","vi":"Mùa hè ở đây nóng như lò lửa.","en":"Summer here is as hot as a furnace."},{"use":"好像: dường như.","ex":"他好像不太高兴。","py":"Tā hǎoxiàng bú tài gāoxìng.","vi":"Hình như anh ấy không vui lắm.","en":"He doesn't seem very happy."}]},"月亮":{"en":"moon","exs":[{"use":"Danh từ; 月亮 + 圆 / 弯: trăng tròn / khuyết.","ex":"今晚的月亮特别圆。","py":"Jīnwǎn de yuèliang tèbié yuán.","vi":"Trăng tối nay đặc biệt tròn.","en":"The moon is especially round tonight."},{"use":"看月亮 / 赏月.","ex":"中秋节我们一起看月亮。","py":"Zhōngqiū jié wǒmen yìqǐ kàn yuèliang.","vi":"Tết Trung Thu chúng ta cùng ngắm trăng.","en":"At the Mid-Autumn Festival we look at the moon together."},{"use":"月亮 + 升起来.","ex":"月亮从山后升了起来。","py":"Yuèliang cóng shān hòu shēng le qǐlai.","vi":"Mặt trăng nhô lên từ sau núi.","en":"The moon rose from behind the mountain."}]},"除了":{"en":"besides; except","exs":[{"use":"除了……以外，都……: trừ… ra thì đều…","ex":"除了小王以外，大家都来了。","py":"Chúle Xiǎo Wáng yǐwài, dàjiā dōu lái le.","vi":"Ngoài Tiểu Vương ra thì mọi người đều đến rồi.","en":"Everyone came except Xiao Wang."},{"use":"除了……以外，还/也……: ngoài… ra còn…","ex":"除了英语以外，他还会说汉语。","py":"Chúle Yīngyǔ yǐwài, tā hái huì shuō Hànyǔ.","vi":"Ngoài tiếng Anh ra, anh ấy còn nói được tiếng Hán.","en":"Besides English, he also speaks Chinese."},{"use":"除了 + 这个 + 没有别的.","ex":"除了这件事，我没有别的担心。","py":"Chúle zhè jiàn shì, wǒ méiyǒu bié de dānxīn.","vi":"Ngoài việc này ra tôi không lo gì khác.","en":"Apart from this, I have no other worries."}]},"发":{"en":"to send; to issue","exs":[{"use":"发 + 邮件 / 短信 / 照片: gửi.","ex":"我给你发了一封电子邮件。","py":"Wǒ gěi nǐ fā le yì fēng diànzǐ yóujiàn.","vi":"Tôi đã gửi cho bạn một email.","en":"I sent you an email."},{"use":"发 + 给 + người.","ex":"请把照片发给我。","py":"Qǐng bǎ zhàopiàn fā gěi wǒ.","vi":"Hãy gửi ảnh cho tôi.","en":"Please send the photos to me."},{"use":"发现 / 发烧: các từ ghép với 发.","ex":"老师给每个学生发了一本书。","py":"Lǎoshī gěi měi ge xuésheng fā le yì běn shū.","vi":"Cô giáo phát cho mỗi học sinh một quyển sách.","en":"The teacher handed each student a book."}]},"极（了）":{"en":"extremely","exs":[{"use":"形容词 + 极了: … vô cùng.","ex":"这个蛋糕好吃极了。","py":"Zhège dàngāo hǎochī jí le.","vi":"Chiếc bánh này ngon vô cùng.","en":"This cake is extremely tasty."},{"use":"极 + 了: 累极了 / 高兴极了.","ex":"听到这个消息，我高兴极了。","py":"Tīngdào zhège xiāoxi, wǒ gāoxìng jí le.","vi":"Nghe tin này tôi vui vô cùng.","en":"I was overjoyed to hear the news."},{"use":"极 + 好 / 大 (trước tính từ): vô cùng.","ex":"这是一个极好的机会。","py":"Zhè shì yí ge jí hǎo de jīhuì.","vi":"Đây là một cơ hội cực kỳ tốt.","en":"This is an extremely good opportunity."}]},"街道":{"en":"street","exs":[{"use":"Danh từ: đường phố trong thành phố.","ex":"这条街道很干净。","py":"Zhè tiáo jiēdào hěn gānjìng.","vi":"Con phố này rất sạch sẽ.","en":"This street is very clean."},{"use":"街道 + 两边: hai bên đường.","ex":"街道两边有很多树。","py":"Jiēdào liǎngbiān yǒu hěn duō shù.","vi":"Hai bên đường có rất nhiều cây.","en":"There are many trees on both sides of the street."},{"use":"热闹的街道.","ex":"过节的时候街道很热闹。","py":"Guò jié de shíhou jiēdào hěn rènao.","vi":"Dịp lễ phố xá rất náo nhiệt.","en":"The streets are lively during festivals."}]},"节日":{"en":"festival; holiday","exs":[{"use":"Danh từ: ngày lễ truyền thống.","ex":"春节是中国最重要的节日。","py":"Chūn Jié shì Zhōngguó zuì zhòngyào de jiérì.","vi":"Tết Nguyên đán là ngày lễ quan trọng nhất Trung Quốc.","en":"The Spring Festival is China's most important holiday."},{"use":"过节日: đón lễ.","ex":"节日快乐！","py":"Jiérì kuàilè!","vi":"Chúc mừng ngày lễ!","en":"Happy holiday!"},{"use":"节日 + 的 + 气氛.","ex":"街上有很浓的节日气氛。","py":"Jiē shàng yǒu hěn nóng de jiérì qìfēn.","vi":"Trên phố đậm không khí lễ hội.","en":"The streets have a festive atmosphere."}]},"句子":{"en":"sentence","exs":[{"use":"Danh từ: 一个句子 / 一句话.","ex":"请用这个词造一个句子。","py":"Qǐng yòng zhège cí zào yí ge jùzi.","vi":"Hãy dùng từ này đặt một câu.","en":"Please make a sentence with this word."},{"use":"写句子 / 翻译句子.","ex":"我正在翻译这个句子。","py":"Wǒ zhèngzài fānyì zhège jùzi.","vi":"Tôi đang dịch câu này.","en":"I'm translating this sentence."},{"use":"长句子 / 短句子.","ex":"这个句子太长了，我读不懂。","py":"Zhège jùzi tài cháng le, wǒ dú bù dǒng.","vi":"Câu này dài quá, tôi đọc không hiểu.","en":"This sentence is too long for me to understand."}]},"练习":{"en":"to practice; exercise","exs":[{"use":"练习 + 动词/名词: luyện tập.","ex":"我每天练习写汉字。","py":"Wǒ měitiān liànxí xiě Hànzì.","vi":"Mỗi ngày tôi luyện viết chữ Hán.","en":"I practice writing characters every day."},{"use":"做练习: làm bài tập.","ex":"这些练习明天要交。","py":"Zhèxiē liànxí míngtiān yào jiāo.","vi":"Những bài tập này mai phải nộp.","en":"These exercises are due tomorrow."},{"use":"多练习: luyện nhiều.","ex":"想说好汉语就要多练习。","py":"Xiǎng shuō hǎo Hànyǔ jiù yào duō liànxí.","vi":"Muốn nói giỏi tiếng Hán thì phải luyện nhiều.","en":"To speak Chinese well you must practice a lot."}]},"留学":{"en":"to study abroad","exs":[{"use":"Động từ ly hợp: 留 + 学; 去 + nơi + 留学.","ex":"他打算明年去中国留学。","py":"Tā dǎsuàn míngnián qù Zhōngguó liú xué.","vi":"Sang năm anh ấy định đi Trung Quốc du học.","en":"He plans to study in China next year."},{"use":"留学生: du học sinh.","ex":"我们班有很多留学生。","py":"Wǒmen bān yǒu hěn duō liúxuéshēng.","vi":"Lớp chúng tôi có nhiều du học sinh.","en":"There are many international students in our class."},{"use":"在国外留学.","ex":"她在英国留学三年了。","py":"Tā zài Yīngguó liú xué sān nián le.","vi":"Cô ấy đã du học ở Anh ba năm.","en":"She has studied in the UK for three years."}]},"其他":{"en":"other; the rest","exs":[{"use":"其他 + danh từ: những… khác.","ex":"其他人都回家了。","py":"Qítā rén dōu huí jiā le.","vi":"Những người khác đều về nhà rồi.","en":"The others have all gone home."},{"use":"其他 + 的: những cái còn lại.","ex":"我只买了这个，其他的以后再说。","py":"Wǒ zhǐ mǎi le zhège, qítā de yǐhòu zài shuō.","vi":"Tôi chỉ mua cái này, còn lại để sau.","en":"I only bought this; the rest can wait."},{"use":"没有其他 + …….","ex":"除了这个，没有其他办法。","py":"Chúle zhège, méiyǒu qítā bànfǎ.","vi":"Ngoài cách này ra không còn cách nào khác.","en":"There's no other way apart from this."}]},"上网":{"en":"to go online","exs":[{"use":"Động từ ly hợp: 上 + 网.","ex":"他每天都上网看新闻。","py":"Tā měitiān dōu shàng wǎng kàn xīnwén.","vi":"Mỗi ngày anh ấy đều lên mạng xem tin tức.","en":"He goes online to read the news every day."},{"use":"上网 + 查资料.","ex":"我常常上网查资料。","py":"Wǒ chángcháng shàng wǎng chá zīliào.","vi":"Tôi thường lên mạng tra tài liệu.","en":"I often go online to look things up."},{"use":"不能上网.","ex":"这里不能上网。","py":"Zhèlǐ bù néng shàng wǎng.","vi":"Ở đây không vào mạng được.","en":"You can't get online here."}]},"世界":{"en":"world","exs":[{"use":"Danh từ: 世界上: trên thế giới.","ex":"世界上有很多不同的文化。","py":"Shìjiè shàng yǒu hěn duō bù tóng de wénhuà.","vi":"Trên thế giới có nhiều nền văn hóa khác nhau.","en":"There are many different cultures in the world."},{"use":"世界 + 各国: các nước trên thế giới.","ex":"世界各国的人都来参加。","py":"Shìjiè gèguó de rén dōu lái cānjiā.","vi":"Người từ khắp các nước trên thế giới đều đến tham gia.","en":"People from all over the world came."},{"use":"世界 + 地图.","ex":"墙上挂着一张世界地图。","py":"Qiáng shàng guà zhe yì zhāng shìjiè dìtú.","vi":"Trên tường treo một tấm bản đồ thế giới.","en":"A world map hangs on the wall."}]},"水平":{"en":"level; standard","exs":[{"use":"Danh từ: 汉语水平 / 生活水平.","ex":"他的汉语水平越来越高。","py":"Tā de Hànyǔ shuǐpíng yuè lái yuè gāo.","vi":"Trình độ tiếng Hán của anh ấy ngày càng cao.","en":"His Chinese level keeps getting higher."},{"use":"提高水平: nâng cao trình độ.","ex":"多听多说可以提高水平。","py":"Duō tīng duō shuō kěyǐ tígāo shuǐpíng.","vi":"Nghe nhiều nói nhiều giúp nâng cao trình độ.","en":"Listening and speaking more raises your level."},{"use":"水平 + 高 / 低.","ex":"他的游泳水平很高。","py":"Tā de yóuyǒng shuǐpíng hěn gāo.","vi":"Trình độ bơi của anh ấy rất cao.","en":"His swimming standard is very high."}]},"提高":{"en":"to improve; to raise","exs":[{"use":"提高 + 水平 / 成绩 / 能力.","ex":"我想提高我的汉语水平。","py":"Wǒ xiǎng tígāo wǒ de Hànyǔ shuǐpíng.","vi":"Tôi muốn nâng cao trình độ tiếng Hán.","en":"I want to improve my Chinese level."},{"use":"提高 + 得 + 很快.","ex":"他的成绩提高得很快。","py":"Tā de chéngjì tígāo de hěn kuài.","vi":"Điểm của anh ấy tăng rất nhanh.","en":"His grades are improving fast."},{"use":"提高 + 了 / 一下.","ex":"经过练习，他的口语提高了。","py":"Jīngguò liànxí, tā de kǒuyǔ tígāo le.","vi":"Nhờ luyện tập, khẩu ngữ của anh ấy đã tiến bộ.","en":"His spoken Chinese improved through practice."}]},"完成":{"en":"to complete","exs":[{"use":"完成 + 工作 / 任务 / 作业.","ex":"我已经完成了今天的作业。","py":"Wǒ yǐjīng wánchéng le jīntiān de zuòyè.","vi":"Tôi đã hoàn thành bài tập hôm nay.","en":"I've completed today's homework."},{"use":"按时完成.","ex":"请按时完成这项工作。","py":"Qǐng ànshí wánchéng zhè xiàng gōngzuò.","vi":"Xin hoàn thành công việc này đúng hạn.","en":"Please complete this work on time."},{"use":"没完成 / 完成不了.","ex":"这个任务我一个人完成不了。","py":"Zhège rènwu wǒ yí ge rén wánchéng bù liǎo.","vi":"Nhiệm vụ này một mình tôi không làm xong được.","en":"I can't complete this task alone."}]},"文化":{"en":"culture","exs":[{"use":"Danh từ: 中国文化, 文化 + 差异.","ex":"我对中国文化很感兴趣。","py":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với văn hóa Trung Quốc.","en":"I'm very interested in Chinese culture."},{"use":"了解文化.","ex":"旅行可以了解不同的文化。","py":"Lǚxíng kěyǐ liǎojiě bù tóng de wénhuà.","vi":"Du lịch giúp hiểu các nền văn hóa khác nhau.","en":"Travel helps you learn about different cultures."},{"use":"文化 + 不同.","ex":"两个国家的文化很不一样。","py":"Liǎng ge guójiā de wénhuà hěn bù yíyàng.","vi":"Văn hóa của hai nước rất khác nhau.","en":"The cultures of the two countries are very different."}]},"新闻":{"en":"news","exs":[{"use":"Danh từ: 看新闻 / 听新闻.","ex":"我每天早上都看新闻。","py":"Wǒ měitiān zǎoshang dōu kàn xīnwén.","vi":"Mỗi sáng tôi đều xem tin tức.","en":"I watch the news every morning."},{"use":"新闻 + 节目.","ex":"他喜欢看电视新闻节目。","py":"Tā xǐhuan kàn diànshì xīnwén jiémù.","vi":"Anh ấy thích xem chương trình thời sự trên tivi.","en":"He likes watching TV news programs."},{"use":"好 / 坏新闻.","ex":"我有一个好新闻要告诉你。","py":"Wǒ yǒu yí ge hǎo xīnwén yào gàosu nǐ.","vi":"Tôi có một tin tốt muốn báo cho bạn.","en":"I have some good news to tell you."}]},"要求":{"en":"requirement; to require","exs":[{"use":"Danh từ/động từ: 要求 + người + động từ.","ex":"老师要求我们每天写日记。","py":"Lǎoshī yāoqiú wǒmen měitiān xiě rìjì.","vi":"Cô giáo yêu cầu chúng tôi viết nhật ký mỗi ngày.","en":"The teacher requires us to keep a diary every day."},{"use":"提出要求.","ex":"他对工作的要求很高。","py":"Tā duì gōngzuò de yāoqiú hěn gāo.","vi":"Anh ấy đòi hỏi rất cao đối với công việc.","en":"He sets high standards for work."},{"use":"符合要求: đáp ứng yêu cầu.","ex":"你的成绩符合学校的要求。","py":"Nǐ de chéngjì fúhé xuéxiào de yāoqiú.","vi":"Điểm của bạn đáp ứng yêu cầu của trường.","en":"Your grades meet the school's requirements."}]},"注意":{"en":"to pay attention to","exs":[{"use":"Động từ ly hợp: 注意 + việc / động từ.","ex":"过马路要注意安全。","py":"Guò mǎlù yào zhùyì ānquán.","vi":"Qua đường phải chú ý an toàn.","en":"Pay attention to safety when crossing the road."},{"use":"注意 + 听 / 看.","ex":"请大家注意听老师讲话。","py":"Qǐng dàjiā zhùyì tīng lǎoshī jiǎng huà.","vi":"Mời mọi người chú ý nghe thầy nói.","en":"Please listen carefully to the teacher."},{"use":"注意身体: giữ gìn sức khỏe.","ex":"天气冷了，要注意身体。","py":"Tiānqì lěng le, yào zhùyì shēntǐ.","vi":"Trời lạnh rồi, nhớ giữ gìn sức khỏe.","en":"It's getting cold; take care of your health."}]},"各":{"en":"each; every","exs":[{"use":"各 + danh từ: mỗi, các.","ex":"各国的学生都来参加比赛。","py":"Gè guó de xuésheng dōu lái cānjiā bǐsài.","vi":"Học sinh các nước đều đến tham gia thi đấu.","en":"Students from each country came to compete."},{"use":"各位: quý vị, các vị.","ex":"各位朋友，欢迎大家！","py":"Gè wèi péngyou, huānyíng dàjiā!","vi":"Thưa các bạn, xin chào mừng mọi người!","en":"Dear friends, welcome everyone!"},{"use":"各 + 有 + ……: mỗi người có…","ex":"我们两个人各有各的爱好。","py":"Wǒmen liǎng ge rén gè yǒu gè de àihào.","vi":"Hai chúng tôi mỗi người có sở thích riêng.","en":"We each have our own hobbies."}]},"举行":{"en":"to hold (an event)","exs":[{"use":"举行 + 活动 / 比赛 / 会议: tổ chức.","ex":"学校明天举行运动会。","py":"Xuéxiào míngtiān jǔxíng yùndònghuì.","vi":"Ngày mai trường tổ chức hội thao.","en":"The school will hold a sports meet tomorrow."},{"use":"在……举行.","ex":"会议将在北京举行。","py":"Huìyì jiāng zài Běijīng jǔxíng.","vi":"Hội nghị sẽ được tổ chức tại Bắc Kinh.","en":"The meeting will be held in Beijing."},{"use":"举行 + 晚会.","ex":"我们为他举行了欢送晚会。","py":"Wǒmen wèi tā jǔxíng le huānsòng wǎnhuì.","vi":"Chúng tôi tổ chức tiệc chia tay cho anh ấy.","en":"We held a farewell party for him."}]},"鼻子":{"en":"nose","exs":[{"use":"Danh từ chỉ bộ phận cơ thể.","ex":"他的鼻子很高。","py":"Tā de bízi hěn gāo.","vi":"Mũi của anh ấy rất cao.","en":"He has a high-bridged nose."},{"use":"鼻子 + 疼 / 堵: đau / ngạt mũi.","ex":"我感冒了，鼻子不舒服。","py":"Wǒ gǎnmào le, bízi bù shūfu.","vi":"Tôi bị cảm, mũi khó chịu.","en":"I have a cold and my nose feels bad."},{"use":"眼睛、鼻子、嘴.","ex":"孩子的眼睛、鼻子、嘴都很像爸爸。","py":"Háizi de yǎnjing, bízi, zuǐ dōu hěn xiàng bàba.","vi":"Mắt, mũi, miệng đứa trẻ đều giống bố.","en":"The child's eyes, nose and mouth all resemble his father's."}]},"别人":{"en":"other people","exs":[{"use":"Đại từ chỉ người khác (không phải mình, không phải người đã nhắc).","ex":"别人都走了，只有我留下来。","py":"Biérén dōu zǒu le, zhǐyǒu wǒ liú xiàlai.","vi":"Người khác đều đi rồi, chỉ có tôi ở lại.","en":"Everyone else left; only I stayed."},{"use":"帮助别人: giúp đỡ người khác.","ex":"他很愿意帮助别人。","py":"Tā hěn yuànyì bāngzhù biérén.","vi":"Anh ấy rất sẵn lòng giúp đỡ người khác.","en":"He is very willing to help others."},{"use":"别人 + 的 + danh từ.","ex":"不要随便用别人的东西。","py":"Búyào suíbiàn yòng biérén de dōngxi.","vi":"Đừng tùy tiện dùng đồ của người khác.","en":"Don't use other people's things carelessly."}]},"城市":{"en":"city","exs":[{"use":"Danh từ chỉ đô thị.","ex":"上海是一个很大的城市。","py":"Shànghǎi shì yí ge hěn dà de chéngshì.","vi":"Thượng Hải là một thành phố rất lớn.","en":"Shanghai is a very big city."},{"use":"大城市 / 小城市.","ex":"我喜欢住在安静的小城市。","py":"Wǒ xǐhuan zhù zài ānjìng de xiǎo chéngshì.","vi":"Tôi thích sống ở thành phố nhỏ yên tĩnh.","en":"I like living in a quiet small city."},{"use":"城市 + 变化.","ex":"这几年，城市的变化非常大。","py":"Zhè jǐ nián, chéngshì de biànhuà fēicháng dà.","vi":"Mấy năm nay thành phố thay đổi rất nhiều.","en":"The city has changed enormously in recent years."}]},"公斤":{"en":"kilogram","exs":[{"use":"Lượng từ chỉ trọng lượng; 1 公斤 = 2 斤.","ex":"我买了两公斤苹果。","py":"Wǒ mǎi le liǎng gōngjīn píngguǒ.","vi":"Tôi mua hai ký táo.","en":"I bought two kilograms of apples."},{"use":"数字 + 公斤: nặng bao nhiêu ký.","ex":"他的体重六十五公斤。","py":"Tā de tǐzhòng liùshíwǔ gōngjīn.","vi":"Cân nặng của anh ấy là sáu mươi lăm ký.","en":"He weighs sixty-five kilograms."},{"use":"多少公斤: bao nhiêu ký.","ex":"这个行李箱有多少公斤？","py":"Zhège xínglixiāng yǒu duōshao gōngjīn?","vi":"Chiếc va li này nặng bao nhiêu ký?","en":"How many kilograms does this suitcase weigh?"}]},"关系":{"en":"relationship","exs":[{"use":"Danh từ: quan hệ giữa người với người.","ex":"他们的关系很好。","py":"Tāmen de guānxi hěn hǎo.","vi":"Quan hệ của họ rất tốt.","en":"They have a good relationship."},{"use":"跟 + 人 + 的关系.","ex":"我和同事的关系都不错。","py":"Wǒ hé tóngshì de guānxi dōu búcuò.","vi":"Quan hệ giữa tôi và đồng nghiệp đều khá tốt.","en":"I get along well with my colleagues."},{"use":"没关系: không sao.","ex":"没关系，我不介意。","py":"Méi guānxi, wǒ bú jièyì.","vi":"Không sao, tôi không để ý đâu.","en":"It doesn't matter; I don't mind."}]},"检查":{"en":"to check; to examine","exs":[{"use":"检查 + 身体 / 作业: kiểm tra.","ex":"医生给他检查了身体。","py":"Yīshēng gěi tā jiǎnchá le shēntǐ.","vi":"Bác sĩ đã khám sức khỏe cho anh ấy.","en":"The doctor gave him a checkup."},{"use":"检查 + 一下.","ex":"出门前检查一下门窗。","py":"Chūmén qián jiǎnchá yíxià ménchuāng.","vi":"Trước khi ra khỏi nhà hãy kiểm tra cửa.","en":"Check the doors and windows before you go out."},{"use":"检查 + 结果.","ex":"检查结果一切正常。","py":"Jiǎnchá jiéguǒ yíqiè zhèngcháng.","vi":"Kết quả kiểm tra mọi thứ đều bình thường.","en":"The test results are all normal."}]},"可爱":{"en":"lovely; cute","exs":[{"use":"Tính từ chỉ trẻ con, động vật, đồ vật dễ thương.","ex":"这个孩子真可爱。","py":"Zhège háizi zhēn kě'ài.","vi":"Đứa trẻ này thật đáng yêu.","en":"This child is so cute."},{"use":"可爱 + 的 + danh từ.","ex":"她养了一只可爱的小狗。","py":"Tā yǎng le yì zhī kě'ài de xiǎo gǒu.","vi":"Cô ấy nuôi một chú chó nhỏ đáng yêu.","en":"She has a lovely little dog."},{"use":"可爱极了.","ex":"那只熊猫可爱极了。","py":"Nà zhī xióngmāo kě'ài jí le.","vi":"Chú gấu trúc đó đáng yêu vô cùng.","en":"That panda is extremely cute."}]},"帽子":{"en":"hat; cap","exs":[{"use":"Danh từ; lượng từ: 顶.","ex":"他戴着一顶黑帽子。","py":"Tā dài zhe yì dǐng hēi màozi.","vi":"Anh ấy đội một chiếc mũ đen.","en":"He is wearing a black hat."},{"use":"戴帽子: đội mũ.","ex":"太阳很大，你戴上帽子吧。","py":"Tàiyáng hěn dà, nǐ dài shàng màozi ba.","vi":"Nắng to, bạn đội mũ vào đi.","en":"The sun is strong; put on a hat."},{"use":"买帽子.","ex":"我想买一顶新帽子。","py":"Wǒ xiǎng mǎi yì dǐng xīn màozi.","vi":"Tôi muốn mua một chiếc mũ mới.","en":"I want to buy a new hat."}]},"米":{"en":"metre; rice","exs":[{"use":"米 (lượng từ): mét. 米 (danh từ): gạo.","ex":"他的身高一米八。","py":"Tā de shēngāo yì mǐ bā.","vi":"Chiều cao của anh ấy là một mét tám.","en":"He is 1.8 metres tall."},{"use":"数字 + 米: bao nhiêu mét.","ex":"学校离这儿只有五百米。","py":"Xuéxiào lí zhèr zhǐyǒu wǔ bǎi mǐ.","vi":"Trường cách đây chỉ năm trăm mét.","en":"The school is only five hundred metres from here."},{"use":"米饭: cơm.","ex":"南方人喜欢吃米饭。","py":"Nánfāng rén xǐhuan chī mǐfàn.","vi":"Người miền Nam thích ăn cơm.","en":"Southerners like to eat rice."}]},"皮鞋":{"en":"leather shoes","exs":[{"use":"Danh từ; lượng từ: 双.","ex":"他穿着一双黑皮鞋。","py":"Tā chuān zhe yì shuāng hēi píxié.","vi":"Anh ấy đi một đôi giày da đen.","en":"He is wearing black leather shoes."},{"use":"买皮鞋 / 擦皮鞋.","ex":"我想给爸爸买一双皮鞋。","py":"Wǒ xiǎng gěi bàba mǎi yì shuāng píxié.","vi":"Tôi muốn mua cho bố một đôi giày da.","en":"I want to buy my dad a pair of leather shoes."},{"use":"新皮鞋 + 磨脚.","ex":"新皮鞋有点儿磨脚。","py":"Xīn píxié yǒudiǎnr mó jiǎo.","vi":"Giày da mới hơi cứng làm đau chân.","en":"The new leather shoes rub my feet a bit."}]},"认为":{"en":"to think; to consider","exs":[{"use":"认为 + (câu): cho rằng.","ex":"我认为这个办法很好。","py":"Wǒ rènwéi zhège bànfǎ hěn hǎo.","vi":"Tôi cho rằng cách này rất hay.","en":"I think this is a good approach."},{"use":"你认为 + 呢?: bạn nghĩ sao?","ex":"你认为谁会赢？","py":"Nǐ rènwéi shéi huì yíng?","vi":"Bạn cho rằng ai sẽ thắng?","en":"Who do you think will win?"},{"use":"不认为: không cho rằng.","ex":"我不认为他是故意的。","py":"Wǒ bú rènwéi tā shì gùyì de.","vi":"Tôi không cho rằng anh ấy cố ý.","en":"I don't think he did it on purpose."}]},"如果":{"en":"if","exs":[{"use":"如果……(的话)，(S)就……: nếu… thì…","ex":"如果明天下雨，我们就不去了。","py":"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le.","vi":"Nếu mai trời mưa thì chúng ta không đi nữa.","en":"If it rains tomorrow, we won't go."},{"use":"如果 + 你 + ……的话.","ex":"如果你有时间的话，请来我家玩儿。","py":"Rúguǒ nǐ yǒu shíjiān de huà, qǐng lái wǒ jiā wánr.","vi":"Nếu bạn có thời gian thì đến nhà tôi chơi nhé.","en":"If you have time, come visit me."},{"use":"如果 + 不 + ……: nếu không…","ex":"如果不努力，就考不好。","py":"Rúguǒ bù nǔlì, jiù kǎo bù hǎo.","vi":"Nếu không cố gắng thì sẽ thi không tốt.","en":"If you don't work hard you won't do well."}]},"刷牙":{"en":"to brush one's teeth","exs":[{"use":"Động từ ly hợp: 刷 + 牙.","ex":"我每天早晚都刷牙。","py":"Wǒ měitiān zǎo wǎn dōu shuā yá.","vi":"Mỗi sáng tối tôi đều đánh răng.","en":"I brush my teeth morning and night."},{"use":"刷牙 + 洗脸.","ex":"他起床后先刷牙洗脸。","py":"Tā qǐchuáng hòu xiān shuā yá xǐ liǎn.","vi":"Sau khi dậy anh ấy đánh răng rửa mặt trước.","en":"After getting up he first brushes his teeth and washes his face."},{"use":"刷了牙 / 刷完牙.","ex":"刷完牙就睡觉吧。","py":"Shuā wán yá jiù shuìjiào ba.","vi":"Đánh răng xong là đi ngủ thôi.","en":"Go to bed after brushing your teeth."}]},"头发":{"en":"hair","exs":[{"use":"Danh từ: 长头发 / 短头发.","ex":"她的头发又黑又长。","py":"Tā de tóufa yòu hēi yòu cháng.","vi":"Tóc cô ấy vừa đen vừa dài.","en":"Her hair is black and long."},{"use":"剪头发 / 洗头发.","ex":"我明天要去剪头发。","py":"Wǒ míngtiān yào qù jiǎn tóufa.","vi":"Mai tôi phải đi cắt tóc.","en":"I'm getting a haircut tomorrow."},{"use":"头发 + 长了.","ex":"你的头发长了，该剪了。","py":"Nǐ de tóufa zhǎng le, gāi jiǎn le.","vi":"Tóc bạn dài rồi, nên cắt đi.","en":"Your hair has grown; it's time for a cut."}]},"长":{"en":"to grow; to look (a certain way)","exs":[{"use":"长 (zhǎng): lớn lên, mọc. 长得 + …: trông như thế nào.","ex":"孩子长高了不少。","py":"Háizi zhǎng gāo le bù shǎo.","vi":"Đứa trẻ cao lên không ít.","en":"The child has grown a lot taller."},{"use":"长得 + 像 / 漂亮.","ex":"她长得很像她姐姐。","py":"Tā zhǎng de hěn xiàng tā jiějie.","vi":"Cô ấy trông rất giống chị gái.","en":"She looks a lot like her sister."},{"use":"长大: lớn lên.","ex":"我在北京长大。","py":"Wǒ zài Běijīng zhǎng dà.","vi":"Tôi lớn lên ở Bắc Kinh.","en":"I grew up in Beijing."}]},"词语":{"en":"word; expression","exs":[{"use":"Danh từ: từ và cụm từ.","ex":"这个词语是什么意思？","py":"Zhège cíyǔ shì shénme yìsi?","vi":"Từ này nghĩa là gì?","en":"What does this word mean?"},{"use":"学词语 / 记词语.","ex":"我每天学习十个新词语。","py":"Wǒ měitiān xuéxí shí ge xīn cíyǔ.","vi":"Mỗi ngày tôi học mười từ mới.","en":"I learn ten new words every day."},{"use":"词语 + 搭配.","ex":"请注意词语的搭配。","py":"Qǐng zhùyì cíyǔ de dāpèi.","vi":"Hãy chú ý cách kết hợp của từ ngữ.","en":"Please pay attention to word collocations."}]},"爱好":{"en":"hobby; interest","exs":[{"use":"Danh từ: 我的爱好是…; động từ: yêu thích.","ex":"我的爱好是听音乐。","py":"Wǒ de àihào shì tīng yīnyuè.","vi":"Sở thích của tôi là nghe nhạc.","en":"My hobby is listening to music."},{"use":"有什么爱好? : có sở thích gì?","ex":"你有什么爱好？","py":"Nǐ yǒu shénme àihào?","vi":"Bạn có sở thích gì?","en":"What are your hobbies?"},{"use":"共同的爱好: sở thích chung.","ex":"我们有很多共同的爱好。","py":"Wǒmen yǒu hěn duō gòngtóng de àihào.","vi":"Chúng tôi có nhiều sở thích chung.","en":"We have many hobbies in common."}]},"办法":{"en":"way; method","exs":[{"use":"Danh từ: 有办法 / 没办法.","ex":"我想到了一个好办法。","py":"Wǒ xiǎngdào le yí ge hǎo bànfǎ.","vi":"Tôi nghĩ ra một cách hay.","en":"I thought of a good method."},{"use":"没办法: hết cách.","ex":"路太远了，我也没办法。","py":"Lù tài yuǎn le, wǒ yě méi bànfǎ.","vi":"Đường xa quá, tôi cũng hết cách.","en":"It's too far; I can't do anything either."},{"use":"想办法: tìm cách.","ex":"我们来想想办法吧。","py":"Wǒmen lái xiǎngxiang bànfǎ ba.","vi":"Chúng ta cùng nghĩ cách nhé.","en":"Let's think of a way."}]},"饱":{"en":"full (after eating)","exs":[{"use":"Tính từ; trái nghĩa 饿.","ex":"我吃饱了，谢谢。","py":"Wǒ chī bǎo le, xièxie.","vi":"Tôi ăn no rồi, cảm ơn.","en":"I'm full, thank you."},{"use":"吃饱: ăn no.","ex":"你吃饱了吗？","py":"Nǐ chī bǎo le ma?","vi":"Bạn ăn no chưa?","en":"Have you had enough to eat?"},{"use":"没吃饱: chưa no.","ex":"这么点儿菜，我没吃饱。","py":"Zhème diǎnr cài, wǒ méi chī bǎo.","vi":"Chỉ có chút đồ ăn thế này, tôi chưa no.","en":"With so little food I'm not full yet."}]},"必须":{"en":"must; have to","exs":[{"use":"必须 + động từ: bắt buộc phải.","ex":"明天你必须来上班。","py":"Míngtiān nǐ bìxū lái shàngbān.","vi":"Ngày mai bạn bắt buộc phải đi làm.","en":"You must come to work tomorrow."},{"use":"必须 + 要: nhất thiết phải.","ex":"这件事必须马上解决。","py":"Zhè jiàn shì bìxū mǎshàng jiějué.","vi":"Việc này phải giải quyết ngay.","en":"This must be solved right away."},{"use":"不必: không cần (phủ định của 必须 là 不用 / 不必).","ex":"你不必来，我自己去就行。","py":"Nǐ bú bì lái, wǒ zìjǐ qù jiù xíng.","vi":"Bạn không cần đến, tôi tự đi là được.","en":"You needn't come; I can go by myself."}]},"冬（天）":{"en":"winter","exs":[{"use":"Danh từ chỉ mùa.","ex":"北方的冬天很冷。","py":"Běifāng de dōngtiān hěn lěng.","vi":"Mùa đông miền Bắc rất lạnh.","en":"Winter in the north is very cold."},{"use":"冬天 + 常常 + 下雪.","ex":"冬天常常下雪。","py":"Dōngtiān chángcháng xià xuě.","vi":"Mùa đông thường có tuyết.","en":"It often snows in winter."},{"use":"过冬: qua đông.","ex":"小鸟飞到南方去过冬。","py":"Xiǎo niǎo fēi dào nánfāng qù guò dōng.","vi":"Chim nhỏ bay về phương nam trú đông.","en":"The little birds fly south for the winter."}]},"根据":{"en":"according to; based on","exs":[{"use":"根据 + danh từ, + (câu): dựa vào…","ex":"根据天气预报，明天会下雨。","py":"Gēnjù tiānqì yùbào, míngtiān huì xià yǔ.","vi":"Theo dự báo thời tiết, ngày mai sẽ mưa.","en":"According to the forecast, it will rain tomorrow."},{"use":"根据 + 要求 / 情况.","ex":"我们根据你的要求做了修改。","py":"Wǒmen gēnjù nǐ de yāoqiú zuò le xiūgǎi.","vi":"Chúng tôi chỉnh sửa theo yêu cầu của bạn.","en":"We made changes according to your request."},{"use":"根据 + 什么? : dựa vào đâu?","ex":"你根据什么这样说？","py":"Nǐ gēnjù shénme zhèyàng shuō?","vi":"Bạn dựa vào đâu mà nói vậy?","en":"What are you basing that on?"}]},"后来":{"en":"later; afterwards","exs":[{"use":"后来 + (câu): kể chuyện đã qua; không dùng cho tương lai.","ex":"他先去了北京，后来去了上海。","py":"Tā xiān qù le Běijīng, hòulái qù le Shànghǎi.","vi":"Anh ấy đến Bắc Kinh trước, sau đó đến Thượng Hải.","en":"He went to Beijing first and then to Shanghai."},{"use":"后来呢? : rồi sau đó thì sao?","ex":"后来呢？他们结婚了吗？","py":"Hòulái ne? Tāmen jié hūn le ma?","vi":"Về sau thì sao? Họ đã cưới chưa?","en":"And then? Did they get married?"},{"use":"后来 + 才: mãi sau mới…","ex":"我后来才知道真相。","py":"Wǒ hòulái cái zhīdào zhēnxiàng.","vi":"Mãi sau tôi mới biết sự thật.","en":"Only later did I learn the truth."}]},"决定":{"en":"to decide; decision","exs":[{"use":"决定 + động từ: quyết định làm gì.","ex":"我决定明年去中国留学。","py":"Wǒ juédìng míngnián qù Zhōngguó liú xué.","vi":"Tôi quyết định sang năm đi Trung Quốc du học.","en":"I've decided to study in China next year."},{"use":"做决定: đưa ra quyết định.","ex":"这个决定很重要，你要想好。","py":"Zhège juédìng hěn zhòngyào, nǐ yào xiǎng hǎo.","vi":"Quyết định này rất quan trọng, bạn phải nghĩ kỹ.","en":"This decision is important; think it over."},{"use":"还没决定.","ex":"去哪儿玩儿，我们还没决定。","py":"Qù nǎr wánr, wǒmen hái méi juédìng.","vi":"Đi chơi ở đâu chúng tôi vẫn chưa quyết định.","en":"We haven't decided where to go yet."}]},"渴":{"en":"thirsty","exs":[{"use":"Tính từ; 口渴 / 渴了.","ex":"我渴了，想喝水。","py":"Wǒ kě le, xiǎng hē shuǐ.","vi":"Tôi khát rồi, muốn uống nước.","en":"I'm thirsty and want some water."},{"use":"又渴又饿.","ex":"爬了一天山，我又渴又饿。","py":"Pá le yì tiān shān, wǒ yòu kě yòu è.","vi":"Leo núi cả ngày, tôi vừa khát vừa đói.","en":"After hiking all day I'm thirsty and hungry."},{"use":"渴得 + …….","ex":"我渴得不想说话。","py":"Wǒ kě de bù xiǎng shuōhuà.","vi":"Tôi khát đến mức không muốn nói.","en":"I'm so thirsty I don't feel like talking."}]},"邻居":{"en":"neighbour","exs":[{"use":"Danh từ chỉ người sống gần nhà.","ex":"我的邻居很热情。","py":"Wǒ de línjū hěn rèqíng.","vi":"Hàng xóm của tôi rất nhiệt tình.","en":"My neighbour is very friendly."},{"use":"跟邻居 + 打招呼.","ex":"他每天早上都跟邻居打招呼。","py":"Tā měitiān zǎoshang dōu gēn línjū dǎ zhāohu.","vi":"Mỗi sáng anh ấy đều chào hàng xóm.","en":"He greets his neighbours every morning."},{"use":"老邻居 / 新邻居.","ex":"我们搬家以后有了新邻居。","py":"Wǒmen bān jiā yǐhòu yǒu le xīn línjū.","vi":"Sau khi chuyển nhà chúng tôi có hàng xóm mới.","en":"We have new neighbours since moving."}]},"请假":{"en":"to ask for leave","exs":[{"use":"Động từ ly hợp: 请 + 假; 请了一天假.","ex":"我感冒了，想请一天假。","py":"Wǒ gǎnmào le, xiǎng qǐng yì tiān jià.","vi":"Tôi bị cảm, muốn xin nghỉ một ngày.","en":"I have a cold and want to take a day off."},{"use":"向 + 人 + 请假.","ex":"他向老师请了两天假。","py":"Tā xiàng lǎoshī qǐng le liǎng tiān jià.","vi":"Anh ấy xin cô giáo nghỉ hai ngày.","en":"He asked the teacher for two days' leave."},{"use":"请假条: đơn xin nghỉ.","ex":"请你写一张请假条。","py":"Qǐng nǐ xiě yì zhāng qǐngjià tiáo.","vi":"Hãy viết một tờ đơn xin nghỉ.","en":"Please write a leave request."}]},"为了":{"en":"in order to; for the sake of","exs":[{"use":"为了 + mục đích, + (hành động).","ex":"为了学好汉语，他每天练习。","py":"Wèile xuéhǎo Hànyǔ, tā měitiān liànxí.","vi":"Để học giỏi tiếng Hán, anh ấy luyện tập mỗi ngày.","en":"To learn Chinese well, he practices every day."},{"use":"为了 + 你: vì bạn.","ex":"为了你，我愿意等。","py":"Wèile nǐ, wǒ yuànyì děng.","vi":"Vì bạn, tôi sẵn sàng đợi.","en":"For you, I'm willing to wait."},{"use":"为了 + 健康.","ex":"为了健康，他不再喝酒了。","py":"Wèile jiànkāng, tā bú zài hē jiǔ le.","vi":"Vì sức khỏe, anh ấy không uống rượu nữa.","en":"For his health, he doesn't drink any more."}]},"选择":{"en":"to choose; choice","exs":[{"use":"选择 + danh từ / động từ.","ex":"你选择哪一个？","py":"Nǐ xuǎnzé nǎ yí ge?","vi":"Bạn chọn cái nào?","en":"Which one do you choose?"},{"use":"有选择 / 没有选择.","ex":"我们没有别的选择。","py":"Wǒmen méiyǒu bié de xuǎnzé.","vi":"Chúng tôi không có lựa chọn nào khác.","en":"We have no other choice."},{"use":"选择 + 专业.","ex":"他选择了历史专业。","py":"Tā xuǎnzé le lìshǐ zhuānyè.","vi":"Anh ấy chọn ngành lịch sử.","en":"He chose to major in history."}]},"一共":{"en":"altogether; in total","exs":[{"use":"一共 + số lượng: tổng cộng.","ex":"这些东西一共多少钱？","py":"Zhèxiē dōngxi yígòng duōshao qián?","vi":"Những thứ này tổng cộng bao nhiêu tiền?","en":"How much is all this in total?"},{"use":"一共 + 有.","ex":"我们班一共有二十个人。","py":"Wǒmen bān yígòng yǒu èrshí ge rén.","vi":"Lớp chúng tôi tổng cộng có hai mươi người.","en":"Our class has twenty people altogether."},{"use":"一共 + 花 + 了.","ex":"这次旅行一共花了五千元。","py":"Zhè cì lǚxíng yígòng huā le wǔ qiān yuán.","vi":"Chuyến đi này tổng cộng tốn năm nghìn tệ.","en":"The trip cost 5,000 yuan in total."}]},"情况":{"en":"situation; condition","exs":[{"use":"Danh từ: tình hình.","ex":"你最近的情况怎么样？","py":"Nǐ zuìjìn de qíngkuàng zěnmeyàng?","vi":"Tình hình dạo này của bạn thế nào?","en":"How have things been with you lately?"},{"use":"了解情况: nắm tình hình.","ex":"我先了解一下情况。","py":"Wǒ xiān liǎojiě yíxià qíngkuàng.","vi":"Tôi tìm hiểu tình hình trước đã.","en":"Let me find out the situation first."},{"use":"特殊情况 / 这种情况.","ex":"这种情况下你应该马上告诉经理。","py":"Zhè zhǒng qíngkuàng xià nǐ yīnggāi mǎshàng gàosu jīnglǐ.","vi":"Trong tình huống này bạn nên báo giám đốc ngay.","en":"In this situation you should tell the manager at once."}]},"不但……而且……":{"en":"not only … but also …","exs":[{"use":"不但 A，而且 B: không chỉ A mà còn B (mức độ tăng dần).","ex":"他不但会唱歌，而且会跳舞。","py":"Tā búdàn huì chàng gē, érqiě huì tiàowǔ.","vi":"Anh ấy không những biết hát mà còn biết nhảy.","en":"He can not only sing but also dance."},{"use":"不但……，而且还…….","ex":"这家饭馆不但便宜，而且很好吃。","py":"Zhè jiā fànguǎn búdàn piányi, érqiě hěn hǎochī.","vi":"Quán này không những rẻ mà còn rất ngon.","en":"This restaurant is not only cheap but delicious."},{"use":"两个主语: 不但……，而且…… có thể đổi chủ ngữ.","ex":"不但我喜欢，而且孩子也喜欢。","py":"Búdàn wǒ xǐhuan, érqiě háizi yě xǐhuan.","vi":"Không những tôi thích mà đứa trẻ cũng thích.","en":"Not only do I like it, my child does too."}]},"地":{"en":"particle linking an adverbial and a verb","exs":[{"use":"形容词 + 地 + 动词: một cách…","ex":"他高兴地笑了。","py":"Tā gāoxìng de xiào le.","vi":"Anh ấy vui vẻ bật cười.","en":"He laughed happily."},{"use":"认真地 / 慢慢地 + 动词.","ex":"请你慢慢地说。","py":"Qǐng nǐ mànmàn de shuō.","vi":"Xin bạn nói chậm thôi.","en":"Please speak slowly."},{"use":"地 + 动词: nối trạng ngữ.","ex":"孩子们高高兴兴地回家了。","py":"Háizimen gāogāoxìngxìng de huí jiā le.","vi":"Bọn trẻ vui vẻ về nhà.","en":"The children went home happily."}]},"动物":{"en":"animal","exs":[{"use":"Danh từ chung chỉ các loài vật.","ex":"我喜欢可爱的小动物。","py":"Wǒ xǐhuan kě'ài de xiǎo dòngwù.","vi":"Tôi thích những con vật nhỏ đáng yêu.","en":"I like cute little animals."},{"use":"动物园: sở thú.","ex":"周末我们去动物园看动物。","py":"Zhōumò wǒmen qù dòngwùyuán kàn dòngwù.","vi":"Cuối tuần chúng ta đi sở thú xem động vật.","en":"We'll go to the zoo this weekend."},{"use":"爱护动物: yêu quý động vật.","ex":"我们要爱护动物。","py":"Wǒmen yào àihù dòngwù.","vi":"Chúng ta phải yêu quý động vật.","en":"We should treat animals kindly."}]},"段":{"en":"section; period (measure word)","exs":[{"use":"一段 + 时间 / 路 / 话: một đoạn, một khoảng.","ex":"我们走了一段路。","py":"Wǒmen zǒu le yí duàn lù.","vi":"Chúng tôi đã đi một đoạn đường.","en":"We walked for a stretch."},{"use":"一段时间: một khoảng thời gian.","ex":"这段时间我很忙。","py":"Zhè duàn shíjiān wǒ hěn máng.","vi":"Khoảng thời gian này tôi rất bận.","en":"I've been very busy this period."},{"use":"一段话 / 一段音乐.","ex":"请读一下这段话。","py":"Qǐng dú yíxià zhè duàn huà.","vi":"Hãy đọc đoạn văn này.","en":"Please read this passage."}]},"关于":{"en":"about; concerning","exs":[{"use":"关于 + danh từ + 的 + danh từ.","ex":"我看了一本关于历史的书。","py":"Wǒ kàn le yì běn guānyú lìshǐ de shū.","vi":"Tôi đã đọc một quyển sách về lịch sử.","en":"I read a book about history."},{"use":"关于 + (…)，…: về vấn đề…","ex":"关于这件事，我不太清楚。","py":"Guānyú zhè jiàn shì, wǒ bú tài qīngchu.","vi":"Về việc này tôi không rõ lắm.","en":"About this matter, I'm not sure."},{"use":"关于 + 的 + 问题.","ex":"他提了几个关于工作的问题。","py":"Tā tí le jǐ ge guānyú gōngzuò de wèntí.","vi":"Anh ấy đưa ra vài câu hỏi về công việc.","en":"He raised some questions about work."}]},"国家":{"en":"country; nation","exs":[{"use":"Danh từ: 不同的国家.","ex":"你去过多少个国家？","py":"Nǐ qù guo duōshao ge guójiā?","vi":"Bạn đã đi bao nhiêu quốc gia rồi?","en":"How many countries have you been to?"},{"use":"国家 + 大 / 小.","ex":"这是一个很小的国家。","py":"Zhè shì yí ge hěn xiǎo de guójiā.","vi":"Đây là một đất nước rất nhỏ.","en":"This is a very small country."},{"use":"国家 + 的 + 文化.","ex":"每个国家的文化都不一样。","py":"Měi ge guójiā de wénhuà dōu bù yíyàng.","vi":"Văn hóa mỗi quốc gia đều khác nhau.","en":"Every country's culture is different."}]},"机会":{"en":"opportunity; chance","exs":[{"use":"Danh từ: 有机会 / 没机会.","ex":"这是一个很好的机会。","py":"Zhè shì yí ge hěn hǎo de jīhuì.","vi":"Đây là một cơ hội rất tốt.","en":"This is a very good opportunity."},{"use":"有机会 + 一定 + …….","ex":"有机会我一定去看你。","py":"Yǒu jīhuì wǒ yídìng qù kàn nǐ.","vi":"Có cơ hội nhất định tôi sẽ đến thăm bạn.","en":"If I get the chance I'll surely visit you."},{"use":"失去机会 / 抓住机会.","ex":"你要抓住这次机会。","py":"Nǐ yào zhuāzhù zhè cì jīhuì.","vi":"Bạn phải nắm lấy cơ hội lần này.","en":"You should seize this opportunity."}]},"奇怪":{"en":"strange; odd","exs":[{"use":"Tính từ: 很奇怪.","ex":"真奇怪，他怎么还没来？","py":"Zhēn qíguài, tā zěnme hái méi lái?","vi":"Lạ thật, sao anh ấy vẫn chưa đến?","en":"How strange; why hasn't he come yet?"},{"use":"奇怪 + 的 + 声音.","ex":"我听到了一个奇怪的声音。","py":"Wǒ tīngdào le yí ge qíguài de shēngyīn.","vi":"Tôi nghe thấy một âm thanh kỳ lạ.","en":"I heard a strange sound."},{"use":"不奇怪: không có gì lạ.","ex":"他这么说，一点儿也不奇怪。","py":"Tā zhème shuō, yìdiǎnr yě bù qíguài.","vi":"Anh ấy nói vậy, chẳng có gì lạ cả.","en":"It's not strange at all that he says so."}]},"同意":{"en":"to agree","exs":[{"use":"同意 + 人/việc: đồng ý.","ex":"老师同意我们去爬山。","py":"Lǎoshī tóngyì wǒmen qù pá shān.","vi":"Cô giáo đồng ý cho chúng tôi đi leo núi.","en":"The teacher agreed to let us go hiking."},{"use":"不同意: không đồng ý.","ex":"我不同意你的看法。","py":"Wǒ bù tóngyì nǐ de kànfǎ.","vi":"Tôi không đồng ý với quan điểm của bạn.","en":"I don't agree with your view."},{"use":"同意 + 吗? : bạn có đồng ý không?","ex":"你同意这个办法吗？","py":"Nǐ tóngyì zhège bànfǎ ma?","vi":"Bạn có đồng ý với cách này không?","en":"Do you agree with this method?"}]},"万":{"en":"ten thousand","exs":[{"use":"Số từ: 一万 = 10.000.","ex":"这个城市有两百万人口。","py":"Zhège chéngshì yǒu liǎng bǎi wàn rénkǒu.","vi":"Thành phố này có hai triệu dân.","en":"This city has two million people."},{"use":"几万: vài chục nghìn.","ex":"这辆车要十几万元。","py":"Zhè liàng chē yào shí jǐ wàn yuán.","vi":"Chiếc xe này mười mấy vạn tệ.","en":"This car costs over a hundred thousand yuan."},{"use":"一万 + 块 / 元.","ex":"他一个月挣一万多。","py":"Tā yí ge yuè zhèng yí wàn duō.","vi":"Một tháng anh ấy kiếm hơn một vạn.","en":"He earns over ten thousand a month."}]},"相信":{"en":"to believe; to trust","exs":[{"use":"相信 + người / điều: tin vào.","ex":"我相信你一定能成功。","py":"Wǒ xiāngxìn nǐ yídìng néng chénggōng.","vi":"Tôi tin bạn nhất định sẽ thành công.","en":"I believe you will certainly succeed."},{"use":"不相信: không tin.","ex":"他不相信这是真的。","py":"Tā bù xiāngxìn zhè shì zhēn de.","vi":"Anh ấy không tin đây là thật.","en":"He doesn't believe this is true."},{"use":"相信自己: tin vào bản thân.","ex":"你要相信自己。","py":"Nǐ yào xiāngxìn zìjǐ.","vi":"Bạn phải tin vào chính mình.","en":"You have to believe in yourself."}]},"向":{"en":"towards; to","exs":[{"use":"向 + người/nơi + động từ: hướng về, hỏi…","ex":"请向前走一百米。","py":"Qǐng xiàng qián zǒu yì bǎi mǐ.","vi":"Xin đi về phía trước một trăm mét.","en":"Please walk a hundred metres forward."},{"use":"向 + 人 + 学习 / 请假 / 借.","ex":"我要向你学习。","py":"Wǒ yào xiàng nǐ xuéxí.","vi":"Tôi phải học hỏi bạn.","en":"I want to learn from you."},{"use":"向 + 左 / 右 + 转.","ex":"到了路口向左转。","py":"Dào le lùkǒu xiàng zuǒ zhuǎn.","vi":"Đến ngã tư thì rẽ trái.","en":"Turn left at the intersection."}]},"有名":{"en":"famous","exs":[{"use":"Tính từ: 很有名.","ex":"这家饭馆很有名。","py":"Zhè jiā fànguǎn hěn yǒumíng.","vi":"Quán ăn này rất nổi tiếng.","en":"This restaurant is very famous."},{"use":"有名 + 的 + danh từ.","ex":"他是一位有名的医生。","py":"Tā shì yí wèi yǒumíng de yīshēng.","vi":"Ông ấy là một bác sĩ nổi tiếng.","en":"He is a famous doctor."},{"use":"以……有名: nổi tiếng về…","ex":"这个城市以美食有名。","py":"Zhège chéngshì yǐ měishí yǒumíng.","vi":"Thành phố này nổi tiếng về ẩm thực.","en":"This city is famous for its food."}]},"种":{"en":"kind; type; to plant","exs":[{"use":"一种 + danh từ: một loại.","ex":"这是一种很有名的茶。","py":"Zhè shì yì zhǒng hěn yǒumíng de chá.","vi":"Đây là một loại trà rất nổi tiếng.","en":"This is a famous kind of tea."},{"use":"各种 / 这种: các loại / loại này.","ex":"超市里有各种各样的水果。","py":"Chāoshì lǐ yǒu gèzhǒng gèyàng de shuǐguǒ.","vi":"Trong siêu thị có đủ loại trái cây.","en":"The supermarket has all kinds of fruit."},{"use":"几种 / 两种.","ex":"这两种办法都可以。","py":"Zhè liǎng zhǒng bànfǎ dōu kěyǐ.","vi":"Cả hai cách này đều được.","en":"Both of these methods are fine."}]},"嘴":{"en":"mouth","exs":[{"use":"Danh từ chỉ bộ phận cơ thể.","ex":"孩子张大了嘴。","py":"Háizi zhāng dà le zuǐ.","vi":"Đứa trẻ há to miệng.","en":"The child opened his mouth wide."},{"use":"嘴 + 甜: miệng ngọt.","ex":"这个孩子嘴很甜。","py":"Zhège háizi zuǐ hěn tián.","vi":"Đứa trẻ này miệng rất ngọt.","en":"This child is sweet-talking."},{"use":"闭嘴 / 张嘴.","ex":"请张开嘴，我看看。","py":"Qǐng zhāngkāi zuǐ, wǒ kànkan.","vi":"Xin há miệng ra để tôi xem.","en":"Please open your mouth and let me look."}]},"特点":{"en":"characteristic; feature","exs":[{"use":"Danh từ: 有……的特点.","ex":"这座城市有自己的特点。","py":"Zhè zuò chéngshì yǒu zìjǐ de tèdiǎn.","vi":"Thành phố này có nét đặc trưng riêng.","en":"This city has its own character."},{"use":"主要特点.","ex":"熊猫的特点是爱吃竹子。","py":"Xióngmāo de tèdiǎn shì ài chī zhúzi.","vi":"Đặc điểm của gấu trúc là thích ăn tre.","en":"A panda's trait is loving bamboo."},{"use":"没有特点.","ex":"这个地方没什么特点。","py":"Zhège dìfang méi shénme tèdiǎn.","vi":"Nơi này chẳng có nét gì đặc biệt.","en":"This place has nothing special about it."}]},"船":{"en":"boat; ship","exs":[{"use":"Danh từ; lượng từ: 条, 只, 艘.","ex":"河上有一条小船。","py":"Hé shàng yǒu yì tiáo xiǎo chuán.","vi":"Trên sông có một chiếc thuyền nhỏ.","en":"There is a small boat on the river."},{"use":"坐船 / 开船.","ex":"我们坐船去对岸。","py":"Wǒmen zuò chuán qù duì'àn.","vi":"Chúng ta đi thuyền sang bờ bên kia.","en":"We take a boat to the other shore."},{"use":"船 + 票.","ex":"船票已经卖完了。","py":"Chuán piào yǐjīng mài wán le.","vi":"Vé tàu đã bán hết rồi.","en":"The boat tickets are sold out."}]},"短":{"en":"short","exs":[{"use":"Tính từ; trái nghĩa 长.","ex":"她喜欢短头发。","py":"Tā xǐhuan duǎn tóufa.","vi":"Cô ấy thích tóc ngắn.","en":"She likes short hair."},{"use":"短 + 时间 / 路.","ex":"在很短的时间里，他学会了开车。","py":"Zài hěn duǎn de shíjiān lǐ, tā xuéhuì le kāichē.","vi":"Trong thời gian rất ngắn anh ấy đã học lái xe.","en":"He learned to drive in a very short time."},{"use":"太短了: ngắn quá.","ex":"这条裤子太短了。","py":"Zhè tiáo kùzi tài duǎn le.","vi":"Chiếc quần này ngắn quá.","en":"These trousers are too short."}]},"耳朵":{"en":"ear","exs":[{"use":"Danh từ chỉ bộ phận cơ thể.","ex":"兔子的耳朵很长。","py":"Tùzi de ěrduo hěn cháng.","vi":"Tai thỏ rất dài.","en":"A rabbit's ears are long."},{"use":"耳朵 + 疼: đau tai.","ex":"我的耳朵有点儿疼。","py":"Wǒ de ěrduo yǒudiǎnr téng.","vi":"Tai tôi hơi đau.","en":"My ear hurts a bit."},{"use":"一只耳朵 / 两只耳朵.","ex":"他一只耳朵听不见。","py":"Tā yì zhī ěrduo tīng bú jiàn.","vi":"Một bên tai anh ấy không nghe được.","en":"He can't hear in one ear."}]},"过":{"en":"to spend (time); to pass","exs":[{"use":"过 + 节日 / 生日 / 时间: đón lễ, sinh nhật.","ex":"你打算怎么过周末？","py":"Nǐ dǎsuàn zěnme guò zhōumò?","vi":"Bạn định trải qua cuối tuần thế nào?","en":"How do you plan to spend the weekend?"},{"use":"过生日: tổ chức sinh nhật.","ex":"明天我过生日。","py":"Míngtiān wǒ guò shēngrì.","vi":"Ngày mai là sinh nhật tôi.","en":"Tomorrow is my birthday."},{"use":"过 + 马路 / 桥: băng qua.","ex":"过马路时要小心。","py":"Guò mǎlù shí yào xiǎoxīn.","vi":"Khi qua đường phải cẩn thận.","en":"Be careful when crossing the road."}]},"经过":{"en":"to pass by; to go through","exs":[{"use":"经过 + nơi chốn / quá trình.","ex":"这辆车经过我家门口。","py":"Zhè liàng chē jīngguò wǒ jiā ménkǒu.","vi":"Chiếc xe này đi qua cổng nhà tôi.","en":"This bus passes my front door."},{"use":"经过 + 努力 / 学习.","ex":"经过努力，他终于通过了考试。","py":"Jīngguò nǔlì, tā zhōngyú tōngguò le kǎoshì.","vi":"Qua nỗ lực, cuối cùng anh ấy đã vượt qua kỳ thi.","en":"After hard work he finally passed the exam."},{"use":"经过 + 一段时间.","ex":"经过一段时间，他习惯了这里。","py":"Jīngguò yí duàn shíjiān, tā xíguàn le zhèlǐ.","vi":"Sau một thời gian anh ấy đã quen nơi này.","en":"After a while he got used to it here."}]},"哭":{"en":"to cry","exs":[{"use":"Động từ; 哭 + 了 / 起来.","ex":"孩子哭了，快去看看。","py":"Háizi kū le, kuài qù kànkan.","vi":"Đứa trẻ khóc rồi, mau đi xem.","en":"The baby is crying; go and see."},{"use":"别哭: đừng khóc.","ex":"别哭了，没关系的。","py":"Bié kū le, méi guānxi de.","vi":"Đừng khóc nữa, không sao đâu.","en":"Don't cry; it's all right."},{"use":"哭 + 得 + …….","ex":"她哭得很伤心。","py":"Tā kū de hěn shāngxīn.","vi":"Cô ấy khóc rất đau lòng.","en":"She cried very sadly."}]},"蓝":{"en":"blue","exs":[{"use":"Tính từ chỉ màu; 蓝色.","ex":"今天的天空特别蓝。","py":"Jīntiān de tiānkōng tèbié lán.","vi":"Bầu trời hôm nay xanh đặc biệt.","en":"The sky is especially blue today."},{"use":"蓝 + 色 / 的.","ex":"我想买一条蓝裤子。","py":"Wǒ xiǎng mǎi yì tiáo lán kùzi.","vi":"Tôi muốn mua một chiếc quần xanh dương.","en":"I want to buy a pair of blue trousers."},{"use":"蓝天 / 蓝色.","ex":"他喜欢蓝色的帽子。","py":"Tā xǐhuan lánsè de màozi.","vi":"Anh ấy thích chiếc mũ màu xanh dương.","en":"He likes blue hats."}]},"脸":{"en":"face","exs":[{"use":"Danh từ chỉ khuôn mặt.","ex":"她的脸红了。","py":"Tā de liǎn hóng le.","vi":"Mặt cô ấy đỏ lên.","en":"Her face turned red."},{"use":"洗脸: rửa mặt.","ex":"起床后先洗脸刷牙。","py":"Qǐchuáng hòu xiān xǐ liǎn shuā yá.","vi":"Dậy xong rửa mặt đánh răng trước.","en":"After getting up, wash your face and brush your teeth first."},{"use":"圆脸 / 小脸.","ex":"这个女孩儿有一张圆圆的脸。","py":"Zhège nǚháir yǒu yì zhāng yuányuán de liǎn.","vi":"Cô bé này có khuôn mặt tròn tròn.","en":"This girl has a round face."}]},"马":{"en":"horse","exs":[{"use":"Danh từ; lượng từ: 匹.","ex":"草地上有一匹白马。","py":"Cǎodì shàng yǒu yì pǐ bái mǎ.","vi":"Trên bãi cỏ có một con ngựa trắng.","en":"There is a white horse on the grass."},{"use":"骑马: cưỡi ngựa.","ex":"他会骑马吗？","py":"Tā huì qí mǎ ma?","vi":"Anh ấy biết cưỡi ngựa không?","en":"Can he ride a horse?"},{"use":"马 + 跑得快.","ex":"这匹马跑得很快。","py":"Zhè pǐ mǎ pǎo de hěn kuài.","vi":"Con ngựa này chạy rất nhanh.","en":"This horse runs very fast."}]},"鸟":{"en":"bird","exs":[{"use":"Danh từ; lượng từ: 只.","ex":"树上有一只小鸟。","py":"Shù shàng yǒu yì zhī xiǎo niǎo.","vi":"Trên cây có một chú chim nhỏ.","en":"There is a little bird in the tree."},{"use":"鸟 + 叫: chim hót.","ex":"早上我被鸟叫声吵醒了。","py":"Zǎoshang wǒ bèi niǎo jiào shēng chǎo xǐng le.","vi":"Buổi sáng tôi bị tiếng chim hót đánh thức.","en":"I was woken by birdsong this morning."},{"use":"养鸟: nuôi chim.","ex":"爷爷喜欢养鸟。","py":"Yéye xǐhuan yǎng niǎo.","vi":"Ông nội thích nuôi chim.","en":"Grandpa likes keeping birds."}]},"秋（天）":{"en":"autumn; fall","exs":[{"use":"Danh từ chỉ mùa.","ex":"秋天的天气不冷也不热。","py":"Qiūtiān de tiānqì bù lěng yě bú rè.","vi":"Thời tiết mùa thu không lạnh cũng không nóng.","en":"Autumn weather is neither cold nor hot."},{"use":"秋天 + 的 + 叶子.","ex":"秋天的叶子变黄了。","py":"Qiūtiān de yèzi biàn huáng le.","vi":"Lá mùa thu đã chuyển vàng.","en":"The autumn leaves have turned yellow."},{"use":"春夏秋冬.","ex":"一年有春夏秋冬四个季节。","py":"Yì nián yǒu chūn xià qiū dōng sì ge jìjié.","vi":"Một năm có bốn mùa xuân hạ thu đông.","en":"A year has four seasons: spring, summer, autumn, winter."}]},"位":{"en":"measure word for people (polite)","exs":[{"use":"一位 + người: một vị (lịch sự).","ex":"这位是我们的新老师。","py":"Zhè wèi shì wǒmen de xīn lǎoshī.","vi":"Vị này là thầy giáo mới của chúng tôi.","en":"This is our new teacher."},{"use":"几位: mấy vị.","ex":"请问，你们一共几位？","py":"Qǐngwèn, nǐmen yígòng jǐ wèi?","vi":"Xin hỏi, các vị tổng cộng mấy người ạ?","en":"How many are in your party?"},{"use":"各位 / 哪位.","ex":"请问您是哪位？","py":"Qǐngwèn nín shì nǎ wèi?","vi":"Xin hỏi ngài là vị nào ạ?","en":"May I ask who is calling?"}]},"张":{"en":"measure word for flat things; surname Zhang","exs":[{"use":"一张 + giấy / ảnh / bàn / vé…","ex":"我买了两张电影票。","py":"Wǒ mǎi le liǎng zhāng diànyǐng piào.","vi":"Tôi mua hai vé xem phim.","en":"I bought two movie tickets."},{"use":"一张照片 / 一张桌子.","ex":"墙上贴着一张地图。","py":"Qiáng shàng tiē zhe yì zhāng dìtú.","vi":"Trên tường dán một tấm bản đồ.","en":"A map is pasted on the wall."},{"use":"张 + 先生: họ Trương.","ex":"张先生在办公室等你。","py":"Zhāng xiānsheng zài bàngōngshì děng nǐ.","vi":"Ông Trương đang đợi bạn ở văn phòng.","en":"Mr. Zhang is waiting for you in the office."}]},"黄河":{"en":"the Yellow River","exs":[{"use":"Danh từ riêng: con sông dài thứ hai Trung Quốc.","ex":"黄河是中国第二长的河。","py":"Huáng Hé shì Zhōngguó dì-èr cháng de hé.","vi":"Hoàng Hà là con sông dài thứ hai Trung Quốc.","en":"The Yellow River is China's second longest river."},{"use":"黄河 + 边 / 上.","ex":"我们坐船游览了黄河。","py":"Wǒmen zuò chuán yóulǎn le Huáng Hé.","vi":"Chúng tôi đi thuyền ngắm sông Hoàng Hà.","en":"We took a boat tour on the Yellow River."},{"use":"黄河 + 水 + 很黄.","ex":"黄河的水看起来是黄色的。","py":"Huáng Hé de shuǐ kàn qǐlai shì huángsè de.","vi":"Nước sông Hoàng Hà trông có màu vàng.","en":"The water of the Yellow River looks yellow."}]},"被":{"en":"by (passive marker)","exs":[{"use":"A + 被 + (B) + động từ + thành phần khác: A bị/được B làm gì.","ex":"我的自行车被朋友骑走了。","py":"Wǒ de zìxíngchē bèi péngyou qí zǒu le.","vi":"Xe đạp của tôi bị bạn đi mất rồi.","en":"My bike was ridden away by a friend."},{"use":"被 + 动词 + 了.","ex":"杯子被他打碎了。","py":"Bēizi bèi tā dǎsuì le.","vi":"Cái cốc bị anh ấy làm vỡ.","en":"The cup was broken by him."},{"use":"被 + 感动 / 影响.","ex":"我被这个故事感动了。","py":"Wǒ bèi zhège gùshi gǎndòng le.","vi":"Tôi bị câu chuyện này làm cảm động.","en":"I was moved by this story."}]},"成绩":{"en":"grade; result","exs":[{"use":"Danh từ: 学习成绩, 考试成绩.","ex":"他的成绩一直很好。","py":"Tā de chéngjì yìzhí hěn hǎo.","vi":"Điểm của anh ấy luôn rất tốt.","en":"His grades have always been good."},{"use":"提高成绩.","ex":"他努力学习，想提高成绩。","py":"Tā nǔlì xuéxí, xiǎng tígāo chéngjì.","vi":"Anh ấy chăm học để nâng cao thành tích.","en":"He studies hard to raise his grades."},{"use":"取得成绩: đạt thành tích.","ex":"她在比赛中取得了好成绩。","py":"Tā zài bǐsài zhōng qǔdé le hǎo chéngjì.","vi":"Cô ấy đạt kết quả tốt trong cuộc thi.","en":"She achieved good results in the contest."}]},"东":{"en":"east","exs":[{"use":"Danh từ chỉ phương hướng; 东边, 往东.","ex":"太阳从东边升起来。","py":"Tàiyáng cóng dōngbiān shēng qǐlai.","vi":"Mặt trời mọc từ phía đông.","en":"The sun rises in the east."},{"use":"往东走.","ex":"往东走就是火车站。","py":"Wǎng dōng zǒu jiù shì huǒchēzhàn.","vi":"Đi về phía đông là ga tàu hỏa.","en":"Go east and you reach the railway station."},{"use":"东西: đồ vật (đọc nhẹ: dōngxi).","ex":"你买了什么东西？","py":"Nǐ mǎi le shénme dōngxi?","vi":"Bạn đã mua những gì?","en":"What did you buy?"}]},"多么":{"en":"how; what (exclamation)","exs":[{"use":"多么 + tính từ + (啊): biết bao…","ex":"这里多么安静啊！","py":"Zhèlǐ duōme ānjìng a!","vi":"Nơi này yên tĩnh biết bao!","en":"How quiet it is here!"},{"use":"多么 + 希望: biết bao mong muốn.","ex":"我多么希望能再见到他。","py":"Wǒ duōme xīwàng néng zài jiàndào tā.","vi":"Tôi biết bao mong được gặp lại anh ấy.","en":"How I wish I could see him again."},{"use":"不管多么 + ……，都 + …….","ex":"不管多么累，他都坚持锻炼。","py":"Bùguǎn duōme lèi, tā dōu jiānchí duànliàn.","vi":"Dù mệt đến mấy, anh ấy vẫn kiên trì tập luyện.","en":"However tired he is, he keeps exercising."}]},"关心":{"en":"to care about","exs":[{"use":"关心 + người / việc.","ex":"谢谢你关心我。","py":"Xièxie nǐ guānxīn wǒ.","vi":"Cảm ơn bạn đã quan tâm tôi.","en":"Thank you for caring about me."},{"use":"关心 + 别人 / 朋友.","ex":"他很关心身边的人。","py":"Tā hěn guānxīn shēnbiān de rén.","vi":"Anh ấy rất quan tâm người xung quanh.","en":"He cares a lot about the people around him."},{"use":"受到关心.","ex":"在这里我感受到了大家的关心。","py":"Zài zhèlǐ wǒ gǎnshòu dào le dàjiā de guānxīn.","vi":"Ở đây tôi cảm nhận được sự quan tâm của mọi người.","en":"Here I feel everyone's care."}]},"解决":{"en":"to solve; to resolve","exs":[{"use":"解决 + 问题 / 困难.","ex":"这个问题终于解决了。","py":"Zhège wèntí zhōngyú jiějué le.","vi":"Vấn đề này cuối cùng đã được giải quyết.","en":"This problem has finally been solved."},{"use":"解决 + 不了: không giải quyết được.","ex":"这件事我一个人解决不了。","py":"Zhè jiàn shì wǒ yí ge rén jiějué bù liǎo.","vi":"Việc này một mình tôi không giải quyết được.","en":"I can't solve this by myself."},{"use":"想办法解决.","ex":"我们一起想办法解决吧。","py":"Wǒmen yìqǐ xiǎng bànfǎ jiějué ba.","vi":"Chúng ta cùng nghĩ cách giải quyết nhé.","en":"Let's figure out a solution together."}]},"难过":{"en":"sad; upset","exs":[{"use":"Tính từ chỉ tâm trạng buồn.","ex":"听到这个消息，我很难过。","py":"Tīngdào zhège xiāoxi, wǒ hěn nánguò.","vi":"Nghe tin này tôi rất buồn.","en":"I was very sad to hear the news."},{"use":"别难过: đừng buồn.","ex":"别难过，明天会更好。","py":"Bié nánguò, míngtiān huì gèng hǎo.","vi":"Đừng buồn, ngày mai sẽ tốt hơn.","en":"Don't be sad; tomorrow will be better."},{"use":"为 + ……+ 难过.","ex":"她为朋友的离开难过了很久。","py":"Tā wèi péngyou de líkāi nánguò le hěn jiǔ.","vi":"Cô ấy buồn rất lâu vì bạn ra đi.","en":"She was sad for a long time because her friend left."}]},"试":{"en":"to try","exs":[{"use":"试 + 一下 / 试试: thử xem.","ex":"我可以试一下这件衣服吗？","py":"Wǒ kěyǐ shì yíxià zhè jiàn yīfu ma?","vi":"Tôi thử chiếc áo này được không?","en":"May I try on this piece of clothing?"},{"use":"试 + 吃 / 穿 / 用.","ex":"你试试这个新手机。","py":"Nǐ shìshi zhège xīn shǒujī.","vi":"Bạn thử chiếc điện thoại mới này xem.","en":"Try this new phone."},{"use":"考试: thi (từ ghép).","ex":"明天有汉语考试。","py":"Míngtiān yǒu Hànyǔ kǎoshì.","vi":"Ngày mai có kỳ thi tiếng Hán.","en":"There is a Chinese exam tomorrow."}]},"碗":{"en":"bowl","exs":[{"use":"Danh từ; lượng từ: 碗 (một bát).","ex":"请给我一个碗。","py":"Qǐng gěi wǒ yí ge wǎn.","vi":"Làm ơn cho tôi một cái bát.","en":"Please give me a bowl."},{"use":"一碗 + 面 / 饭 / 汤.","ex":"我想吃一碗面条。","py":"Wǒ xiǎng chī yì wǎn miàntiáo.","vi":"Tôi muốn ăn một bát mì.","en":"I'd like a bowl of noodles."},{"use":"洗碗: rửa bát.","ex":"吃完饭我来洗碗。","py":"Chī wán fàn wǒ lái xǐ wǎn.","vi":"Ăn xong tôi sẽ rửa bát.","en":"I'll wash the dishes after we eat."}]},"信用卡":{"en":"credit card","exs":[{"use":"Danh từ; lượng từ: 张.","ex":"这里可以用信用卡吗？","py":"Zhèlǐ kěyǐ yòng xìnyòngkǎ ma?","vi":"Ở đây có dùng thẻ tín dụng được không?","en":"Can I use a credit card here?"},{"use":"刷信用卡: quẹt thẻ.","ex":"我想刷信用卡付钱。","py":"Wǒ xiǎng shuā xìnyòngkǎ fù qián.","vi":"Tôi muốn quẹt thẻ tín dụng để trả tiền.","en":"I'd like to pay by credit card."},{"use":"办信用卡 / 丢了信用卡.","ex":"他的信用卡丢了。","py":"Tā de xìnyòngkǎ diū le.","vi":"Thẻ tín dụng của anh ấy bị mất.","en":"His credit card is lost."}]},"照相机":{"en":"camera","exs":[{"use":"Danh từ; lượng từ: 个, 台.","ex":"我新买了一个照相机。","py":"Wǒ xīn mǎi le yí ge zhàoxiàngjī.","vi":"Tôi mới mua một chiếc máy ảnh.","en":"I just bought a new camera."},{"use":"用照相机 + 拍照.","ex":"他用照相机拍了很多照片。","py":"Tā yòng zhàoxiàngjī pāi le hěn duō zhàopiàn.","vi":"Anh ấy dùng máy ảnh chụp rất nhiều ảnh.","en":"He took lots of photos with his camera."},{"use":"带照相机 / 借照相机.","ex":"旅行的时候别忘了带照相机。","py":"Lǚxíng de shíhou bié wàng le dài zhàoxiàngjī.","vi":"Khi đi du lịch đừng quên mang máy ảnh.","en":"Don't forget your camera on the trip."}]},"只有……才……":{"en":"only if … (then) …","exs":[{"use":"只有 + điều kiện, 才 + kết quả: chỉ khi… mới…","ex":"只有努力学习，才能考好。","py":"Zhǐyǒu nǔlì xuéxí, cái néng kǎo hǎo.","vi":"Chỉ có học chăm mới thi tốt được.","en":"Only by studying hard can you do well."},{"use":"只有……才能…….","ex":"只有多练习，才能提高水平。","py":"Zhǐyǒu duō liànxí, cái néng tígāo shuǐpíng.","vi":"Chỉ có luyện tập nhiều mới nâng cao được trình độ.","en":"Only with more practice can you improve."},{"use":"只有 + 你 + 才 + 会.","ex":"只有你才会这样想。","py":"Zhǐyǒu nǐ cái huì zhèyàng xiǎng.","vi":"Chỉ có bạn mới nghĩ như vậy.","en":"Only you would think this way."}]},"真正":{"en":"truly; real","exs":[{"use":"真正 + 的 + danh từ / 真正 + động từ.","ex":"他是一个真正的朋友。","py":"Tā shì yí ge zhēnzhèng de péngyou.","vi":"Anh ấy là một người bạn thật sự.","en":"He is a true friend."},{"use":"真正 + 了解 / 明白.","ex":"我现在才真正明白这句话。","py":"Wǒ xiànzài cái zhēnzhèng míngbai zhè jù huà.","vi":"Bây giờ tôi mới thật sự hiểu câu này.","en":"Only now do I truly understand this sentence."},{"use":"真正的 + 意思.","ex":"你知道这个词真正的意思吗？","py":"Nǐ zhīdào zhège cí zhēnzhèng de yìsi ma?","vi":"Bạn có biết nghĩa thật sự của từ này không?","en":"Do you know the real meaning of this word?"}]}});
